window.A2_PODCASTS=[{"chapter":1,"title":"Ein freier Samstag","duration":"11 Min.","speakers":["Mia","Tarek"],"intro":"Freizeit, Verabredungen und ein Besuch im Restaurant.","keywords":["sich verabreden","verschieben","mitbringen","gemütlich","weil"],"lines":[{"speaker":"Mia","de":"Willkommen zu Folge 1: Ein freier Samstag. Ich bin Mia, 27 Jahre alt.","ar":"مرحبًا بكم في الحلقة 1: Ein freier Samstag. أنا Mia وعمري 27 عامًا.","pauseAfter":0.5,"kind":"intro","start":0.0,"end":6.504},{"speaker":"Tarek","de":"Und ich bin Tarek, 31 Jahre alt. Heute sprechen wir über Freizeit, Tätigkeiten, Verabredungen, Restaurant.","ar":"وأنا Tarek وعمري 31 عامًا. سنتحدث اليوم عن موضوعات الدرس.","pauseAfter":0.6,"kind":"intro","start":7.004,"end":15.428},{"speaker":"Mia","de":"Hör zuerst entspannt zu. Danach wiederholen wir wichtige Wörter und Redemittel, und am Ende gibt es Fragen für dich.","ar":"استمع أولًا بهدوء. بعد ذلك سنراجع كلمات وتعبيرات مهمة، وفي النهاية توجد أسئلة لك.","pauseAfter":0.7,"kind":"intro","start":16.028,"end":23.66},{"speaker":"Tarek","de":"Du kannst jederzeit pausieren, laut antworten und anschließend mit unserer Lösung vergleichen. Los geht es!","ar":"يمكنك إيقاف الحلقة والإجابة بصوت عالٍ ثم مقارنة إجابتك بحلنا. لنبدأ!","pauseAfter":1,"kind":"intro","start":24.36,"end":31.512},{"speaker":"Mia","de":"Hallo Tarek! Was machst du eigentlich am Wochenende?","ar":"مرحبًا يا طارق! ماذا تفعل عادةً في عطلة نهاية الأسبوع؟","pauseAfter":0.55,"kind":"scene","start":32.512,"end":36.472},{"speaker":"Tarek","de":"Am Samstag schlafe ich gern lange, weil ich unter der Woche früh aufstehen muss.","ar":"يوم السبت أحب النوم طويلًا، لأنني أضطر للاستيقاظ مبكرًا خلال الأسبوع.","pauseAfter":0.55,"kind":"scene","start":37.022,"end":41.678},{"speaker":"Mia","de":"Ich treffe mich oft mit Freunden. Diesen Samstag wollen wir gemeinsam kochen.","ar":"غالبًا ألتقي بأصدقائي. هذا السبت نريد أن نطبخ معًا.","pauseAfter":0.55,"kind":"scene","start":42.228,"end":47.292},{"speaker":"Tarek","de":"Das klingt gut. Wann und wo habt ihr euch verabredet?","ar":"هذا يبدو جيدًا. متى وأين اتفقتم على اللقاء؟","pauseAfter":0.55,"kind":"scene","start":47.842,"end":52.234},{"speaker":"Mia","de":"Wir treffen uns um vier bei mir. Jeder bringt etwas mit, aber Karim muss den Termin vielleicht verschieben.","ar":"سنلتقي الساعة الرابعة عندي. كل شخص سيحضر شيئًا، لكن كريم قد يضطر لتأجيل الموعد.","pauseAfter":0.55,"kind":"scene","start":52.784,"end":59.432},{"speaker":"Tarek","de":"Was kocht ihr denn?","ar":"وماذا ستطبخون؟","pauseAfter":0.55,"kind":"scene","start":59.982,"end":61.926},{"speaker":"Mia","de":"Zuerst wollten wir Pizza machen. Jetzt gehen wir aber in ein kleines, gemütliches Restaurant.","ar":"في البداية أردنا إعداد البيتزا، لكننا سنذهب الآن إلى مطعم صغير ومريح.","pauseAfter":0.55,"kind":"scene","start":62.476,"end":68.5},{"speaker":"Tarek","de":"Dann wünsche ich euch viel Spaß. Beim nächsten Mal komme ich gern mit!","ar":"إذن أتمنى لكم وقتًا ممتعًا. في المرة القادمة سآتي معكم بكل سرور!","pauseAfter":0.55,"kind":"scene","start":69.05,"end":74.018},{"speaker":"Mia","de":"Am Samstag ruft Mia noch einmal an, denn der Plan hat sich geändert.","ar":"يوم السبت تتصل ميا مرة أخرى لأن الخطة تغيرت.","pauseAfter":0.28,"kind":"scene","start":74.568,"end":79.104},{"speaker":"Tarek","de":"Hallo Mia, bleibt es bei vier Uhr oder müssen wir das Treffen verschieben?","ar":"مرحبًا ميا، هل ما زال الموعد الساعة الرابعة أم سنؤجله؟","pauseAfter":0.28,"kind":"scene","start":79.384,"end":83.824},{"speaker":"Mia","de":"Vier Uhr passt. Aber Karim hat abgesagt, weil sein Sohn krank geworden ist.","ar":"الساعة الرابعة مناسبة، لكن كريم اعتذر لأن ابنه مرض.","pauseAfter":0.28,"kind":"scene","start":84.104,"end":89.624},{"speaker":"Tarek","de":"Schade. Soll ich trotzdem den Salat und etwas zu trinken mitbringen?","ar":"مؤسف. هل أحضر السلطة وشيئًا للشرب رغم ذلك؟","pauseAfter":0.28,"kind":"scene","start":89.904,"end":95.232},{"speaker":"Mia","de":"Ja, bitte. Ich habe schon Brot gekauft und bereite eine Suppe vor.","ar":"نعم من فضلك. اشتريت الخبز وسأجهز الحساء.","pauseAfter":0.28,"kind":"scene","start":95.512,"end":100.552},{"speaker":"Tarek","de":"Dann kochen wir also doch zu Hause und gehen nicht ins Restaurant?","ar":"إذن سنطبخ في المنزل ولن نذهب إلى المطعم؟","pauseAfter":0.28,"kind":"scene","start":100.832,"end":105.056},{"speaker":"Mia","de":"Genau. Zu Hause können wir länger sitzen und uns in Ruhe unterhalten.","ar":"بالضبط. في المنزل يمكننا الجلوس مدة أطول والتحدث بهدوء.","pauseAfter":0.28,"kind":"scene","start":105.336,"end":110.136},{"speaker":"Tarek","de":"Gute Idee. Soll ich auch meine neue Kollegin Jana fragen?","ar":"فكرة جيدة. هل أدعو زميلتي الجديدة يانا أيضًا؟","pauseAfter":0.28,"kind":"scene","start":110.416,"end":115.384},{"speaker":"Mia","de":"Gern. Was macht sie beruflich und woher kommt sie?","ar":"بكل سرور. ما مهنتها ومن أين تأتي؟","pauseAfter":0.28,"kind":"scene","start":115.664,"end":119.456},{"speaker":"Tarek","de":"Sie arbeitet als Fotografin und kommt ursprünglich aus Leipzig.","ar":"تعمل مصورة وهي في الأصل من لايبزيغ.","pauseAfter":0.28,"kind":"scene","start":119.736,"end":123.912},{"speaker":"Mia","de":"Das ist interessant. In meiner Freizeit fotografiere ich nämlich auch gern.","ar":"هذا ممتع، فأنا أيضًا أحب التصوير في وقت فراغي.","pauseAfter":0.28,"kind":"scene","start":124.192,"end":129.424},{"speaker":"Tarek","de":"Perfekt, dann habt ihr sofort ein gemeinsames Thema.","ar":"ممتاز، إذن لديكما موضوع مشترك فورًا.","pauseAfter":0.28,"kind":"scene","start":129.704,"end":133.376},{"speaker":"Mia","de":"Später können wir noch das neue Café an der Ecke ausprobieren.","ar":"بعد ذلك يمكننا تجربة المقهى الجديد عند الزاوية.","pauseAfter":0.28,"kind":"scene","start":133.656,"end":137.496},{"speaker":"Tarek","de":"Ich habe gehört, dass es dort sehr gemütlich sein soll.","ar":"سمعت أن المكان هناك مريح جدًا.","pauseAfter":0.28,"kind":"scene","start":137.776,"end":141.304},{"speaker":"Mia","de":"Dann machen wir es so: erst gemeinsam essen und danach ins Café.","ar":"إذن نفعل ذلك: نأكل معًا أولًا ثم نذهب إلى المقهى.","pauseAfter":0.28,"kind":"scene","start":141.584,"end":145.856},{"speaker":"Tarek","de":"Abgemacht. Ich bin um vier da und melde mich, falls ich mich verspäte.","ar":"اتفقنا. سأكون هناك الساعة الرابعة وسأتصل إذا تأخرت.","pauseAfter":0.28,"kind":"scene","start":146.136,"end":151.416},{"speaker":"Mia","de":"Das war unsere erste Alltagsszene. Welche Wörter und Sätze hast du sofort verstanden?","ar":"كان هذا مشهدنا اليومي الأول. ما الكلمات والجمل التي فهمتها فورًا؟","pauseAfter":3.2,"kind":"interactive","start":151.696,"end":157.696},{"speaker":"Tarek","de":"Denk kurz nach. Du musst nicht jedes Wort verstehen. Wichtig ist zuerst die Situation.","ar":"فكّر قليلًا. ليس ضروريًا أن تفهم كل كلمة؛ المهم أولًا هو فهم الموقف.","pauseAfter":2.4,"kind":"interactive","start":160.896,"end":167.76},{"speaker":"Mia","de":"Die Situation passt zu Kapitel 1. Jetzt sehen wir uns den Wortschatz genauer an.","ar":"الموقف مرتبط بالدرس 1. والآن سنراجع المفردات بدقة أكبر.","pauseAfter":0.8,"kind":"section","start":170.16,"end":175.824},{"speaker":"Mia","de":"Wort Nummer 1: die Freizeit. Hör genau zu: die Freizeit.","ar":"الكلمة رقم 1: وقت الفراغ. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":176.624,"end":181.808},{"speaker":"Tarek","de":"die Freizeit bedeutet: Die Zeit, in der man nicht arbeitet oder lernt. Ein Beispiel: In meiner Freizeit gehe ich gern schwimmen.","ar":"معنى die Freizeit: وقت الفراغ.","pauseAfter":0.6,"kind":"vocab","start":182.258,"end":190.562},{"speaker":"Mia","de":"Jetzt bist du dran. Sprich laut nach: die Freizeit.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Freizeit.","pauseAfter":1.8,"kind":"interactive","start":191.162,"end":195.338},{"speaker":"Tarek","de":"Wort Nummer 2: sich vorstellen. Hör genau zu: sich vorstellen.","ar":"الكلمة رقم 2: يعرّف نفسه. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":197.138,"end":202.49},{"speaker":"Mia","de":"sich vorstellen bedeutet: Den eigenen Namen und wichtige Informationen sagen. Ein Beispiel: Darf ich mich kurz vorstellen?","ar":"معنى sich vorstellen: يعرّف نفسه.","pauseAfter":0.6,"kind":"vocab","start":202.94,"end":211.316},{"speaker":"Tarek","de":"Jetzt bist du dran. Sprich laut nach: sich vorstellen.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: sich vorstellen.","pauseAfter":1.8,"kind":"interactive","start":211.916,"end":216.62},{"speaker":"Mia","de":"Wort Nummer 3: der Beruf, -e. Hör genau zu: der Beruf, -e.","ar":"الكلمة رقم 3: المهنة. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":218.42,"end":223.58},{"speaker":"Tarek","de":"der Beruf, -e bedeutet: Eine Arbeit, für die man ausgebildet ist. Ein Beispiel: Was bist du von Beruf?","ar":"معنى der Beruf, -e: المهنة.","pauseAfter":0.6,"kind":"vocab","start":224.03,"end":231.47},{"speaker":"Mia","de":"Jetzt bist du dran. Sprich laut nach: der Beruf, -e.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Beruf, -e.","pauseAfter":1.8,"kind":"interactive","start":232.07,"end":236.438},{"speaker":"Tarek","de":"Wort Nummer 4: die Tätigkeit, -en. Hör genau zu: die Tätigkeit, -en.","ar":"الكلمة رقم 4: نشاط / عمل. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":238.238,"end":244.382},{"speaker":"Mia","de":"die Tätigkeit, -en bedeutet: Etwas, das man regelmäßig macht. Ein Beispiel: Lesen ist eine ruhige Tätigkeit.","ar":"معنى die Tätigkeit, -en: نشاط / عمل.","pauseAfter":0.6,"kind":"vocab","start":244.832,"end":253.568},{"speaker":"Tarek","de":"Jetzt bist du dran. Sprich laut nach: die Tätigkeit, -en.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Tätigkeit, -en.","pauseAfter":1.8,"kind":"interactive","start":254.168,"end":259.328},{"speaker":"Mia","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":261.128,"end":267.656},{"speaker":"Tarek","de":"Die Wörter waren: die Freizeit, sich vorstellen, der Beruf, -e, die Tätigkeit, -en.","ar":"الكلمات كانت: وقت الفراغ، يعرّف نفسه، المهنة، نشاط / عمل.","pauseAfter":1,"kind":"answer","start":270.656,"end":276.656},{"speaker":"Mia","de":"Wort Nummer 5: sich verabreden. Hör genau zu: sich verabreden.","ar":"الكلمة رقم 5: يتفق على مقابلة. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":277.656,"end":283.008},{"speaker":"Tarek","de":"sich verabreden bedeutet: Mit jemandem einen Treffpunkt und eine Zeit vereinbaren. Ein Beispiel: Wir haben uns für Samstag verabredet.","ar":"معنى sich verabreden: يتفق على مقابلة.","pauseAfter":0.6,"kind":"vocab","start":283.458,"end":292.242},{"speaker":"Mia","de":"Jetzt bist du dran. Sprich laut nach: sich verabreden.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: sich verabreden.","pauseAfter":1.8,"kind":"interactive","start":292.842,"end":297.138},{"speaker":"Tarek","de":"Wort Nummer 6: verschieben. Hör genau zu: verschieben.","ar":"الكلمة رقم 6: يؤجّل. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":298.938,"end":303.81},{"speaker":"Mia","de":"verschieben bedeutet: Etwas zu einem späteren Zeitpunkt machen. Ein Beispiel: Können wir unser Treffen verschieben?","ar":"معنى verschieben: يؤجّل.","pauseAfter":0.6,"kind":"vocab","start":304.26,"end":312.396},{"speaker":"Tarek","de":"Jetzt bist du dran. Sprich laut nach: verschieben.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: verschieben.","pauseAfter":1.8,"kind":"interactive","start":312.996,"end":317.436},{"speaker":"Mia","de":"Wort Nummer 7: absagen. Hör genau zu: absagen.","ar":"الكلمة رقم 7: يلغي. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":319.236,"end":323.868},{"speaker":"Tarek","de":"absagen bedeutet: Sagen, dass ein Termin nicht stattfindet. Ein Beispiel: Leider muss ich für heute absagen.","ar":"معنى absagen: يلغي.","pauseAfter":0.6,"kind":"vocab","start":324.318,"end":331.83},{"speaker":"Mia","de":"Jetzt bist du dran. Sprich laut nach: absagen.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: absagen.","pauseAfter":1.8,"kind":"interactive","start":332.43,"end":336.318},{"speaker":"Tarek","de":"Wort Nummer 8: mitbringen. Hör genau zu: mitbringen.","ar":"الكلمة رقم 8: يحضر معه. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":338.118,"end":342.966},{"speaker":"Mia","de":"mitbringen bedeutet: Etwas zu einem Treffen bringen. Ein Beispiel: Ich bringe einen Salat mit.","ar":"معنى mitbringen: يحضر معه.","pauseAfter":0.6,"kind":"vocab","start":343.416,"end":350.112},{"speaker":"Tarek","de":"Jetzt bist du dran. Sprich laut nach: mitbringen.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: mitbringen.","pauseAfter":1.8,"kind":"interactive","start":350.712,"end":355.2},{"speaker":"Mia","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":357.0,"end":363.528},{"speaker":"Tarek","de":"Die Wörter waren: sich verabreden, verschieben, absagen, mitbringen.","ar":"الكلمات كانت: يتفق على مقابلة، يؤجّل، يلغي، يحضر معه.","pauseAfter":1,"kind":"answer","start":366.528,"end":371.352},{"speaker":"Mia","de":"Wort Nummer 9: gemeinsam. Hör genau zu: gemeinsam.","ar":"الكلمة رقم 9: معًا. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":372.352,"end":377.152},{"speaker":"Tarek","de":"gemeinsam bedeutet: Zusammen mit anderen. Ein Beispiel: Wir kochen heute gemeinsam.","ar":"معنى gemeinsam: معًا.","pauseAfter":0.6,"kind":"vocab","start":377.602,"end":383.842},{"speaker":"Mia","de":"Jetzt bist du dran. Sprich laut nach: gemeinsam.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: gemeinsam.","pauseAfter":1.8,"kind":"interactive","start":384.442,"end":388.522},{"speaker":"Tarek","de":"Wort Nummer 10: das Gericht, -e. Hör genau zu: das Gericht, -e.","ar":"الكلمة رقم 10: طبق طعام. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":390.322,"end":395.242},{"speaker":"Mia","de":"das Gericht, -e bedeutet: Eine zubereitete Speise auf der Speisekarte. Ein Beispiel: Mein Lieblingsgericht ist Gemüsecurry.","ar":"معنى das Gericht, -e: طبق طعام.","pauseAfter":0.6,"kind":"vocab","start":395.692,"end":405.1},{"speaker":"Tarek","de":"Jetzt bist du dran. Sprich laut nach: das Gericht, -e.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: das Gericht, -e.","pauseAfter":1.8,"kind":"interactive","start":405.7,"end":410.572},{"speaker":"Tarek","de":"Sehr gut. Wörter allein reichen aber nicht. Im Gespräch brauchen wir fertige Sätze und passende Reaktionen.","ar":"جيد جدًا. الكلمات وحدها لا تكفي؛ في الحوار نحتاج إلى جمل جاهزة وردود مناسبة.","pauseAfter":0.8,"kind":"section","start":412.372,"end":420.388},{"speaker":"Mia","de":"Situation 1, Sich vorstellen. Was könntest du sagen?","ar":"الموقف رقم 1. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":421.188,"end":425.628},{"speaker":"Tarek","de":"Eine passende Formulierung ist: Ich heiße … und komme ursprünglich aus …","ar":"تعبير مناسب هو: اسمي ... وأنا أصلي من ...","pauseAfter":0.7,"kind":"phrase","start":427.828,"end":432.508},{"speaker":"Mia","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Ich heiße … und komme ursprünglich aus …","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":433.208,"end":439.496},{"speaker":"Tarek","de":"Situation 2, Sich vorstellen. Was könntest du sagen?","ar":"الموقف رقم 2. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":441.696,"end":446.688},{"speaker":"Mia","de":"Eine passende Formulierung ist: Zurzeit arbeite ich als … / studiere ich …","ar":"تعبير مناسب هو: حاليًا أعمل كـ... / أدرس ...","pauseAfter":0.7,"kind":"phrase","start":448.888,"end":454.24},{"speaker":"Tarek","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Zurzeit arbeite ich als … / studiere ich …","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":454.94,"end":460.94},{"speaker":"Mia","de":"Situation 3, Sich vorstellen. Was könntest du sagen?","ar":"الموقف رقم 3. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":463.14,"end":467.652},{"speaker":"Tarek","de":"Eine passende Formulierung ist: In meiner Freizeit interessiere ich mich besonders für …","ar":"تعبير مناسب هو: في وقت فراغي أهتم خصوصًا بـ ...","pauseAfter":0.7,"kind":"phrase","start":469.852,"end":475.084},{"speaker":"Mia","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: In meiner Freizeit interessiere ich mich besonders für …","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":475.784,"end":482.528},{"speaker":"Tarek","de":"Situation 4, Sich vorstellen. Was könntest du sagen?","ar":"الموقف رقم 4. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":484.728,"end":489.792},{"speaker":"Mia","de":"Eine passende Formulierung ist: Ich spreche … fließend und lerne gerade Deutsch.","ar":"تعبير مناسب هو: أتحدث ... بطلاقة وأتعلم الألمانية حاليًا.","pauseAfter":0.7,"kind":"phrase","start":491.992,"end":497.368},{"speaker":"Tarek","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Ich spreche … fließend und lerne gerade Deutsch.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":498.068,"end":504.164},{"speaker":"Mia","de":"Situation 5, Sich verabreden. Was könntest du sagen?","ar":"الموقف رقم 5. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":506.364,"end":511.02},{"speaker":"Tarek","de":"Eine passende Formulierung ist: Hast du am Freitagabend Zeit?","ar":"تعبير مناسب هو: عندك وقت مساء الجمعة؟","pauseAfter":0.7,"kind":"phrase","start":513.22,"end":517.492},{"speaker":"Mia","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Hast du am Freitagabend Zeit?","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":518.192,"end":523.712},{"speaker":"Tarek","de":"Situation 6, Sich verabreden. Was könntest du sagen?","ar":"الموقف رقم 6. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":525.912,"end":531.024},{"speaker":"Mia","de":"Eine passende Formulierung ist: Wie wäre es mit Samstag um drei?","ar":"تعبير مناسب هو: ما رأيك في السبت الساعة ثلاثة؟","pauseAfter":0.7,"kind":"phrase","start":533.224,"end":537.568},{"speaker":"Tarek","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Wie wäre es mit Samstag um drei?","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":538.268,"end":543.86},{"speaker":"Mia","de":"Jetzt kommt ein kurzer Hör- und Grammatikcheck. Antworte zuerst selbst. Danach hörst du die Lösung.","ar":"والآن اختبار قصير في الاستماع والقواعد. أجب أولًا بنفسك ثم استمع إلى الحل.","pauseAfter":0.8,"kind":"section","start":546.06,"end":553.284},{"speaker":"Mia","de":"Frage 1: Ich ___ gestern lange gearbeitet.","ar":"السؤال رقم 1. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":554.084,"end":559.268},{"speaker":"Mia","de":"Die Möglichkeiten sind: A, bin. B, habe. C, werde.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":559.768,"end":565.312},{"speaker":"Tarek","de":"Die richtige Antwort ist B: habe. arbeiten bildet das Perfekt mit haben.","ar":"الإجابة الصحيحة: arbeiten يستخدم haben.","pauseAfter":1,"kind":"answer","start":568.512,"end":574.056},{"speaker":"Tarek","de":"Frage 2: Wir sind nach Dresden ___.","ar":"السؤال رقم 2. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":575.056,"end":579.352},{"speaker":"Tarek","de":"Die Möglichkeiten sind: A, gefahrt. B, gefahren. C, gefahrtet.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":579.852,"end":586.404},{"speaker":"Mia","de":"Die richtige Antwort ist B: gefahren. fahren → ist gefahren.","ar":"الإجابة الصحيحة: تصريف fahren في Perfekt هو ist gefahren.","pauseAfter":1,"kind":"answer","start":589.604,"end":594.428},{"speaker":"Mia","de":"Frage 3: Ich komme später, weil ich noch arbeiten ___.","ar":"السؤال رقم 3. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":595.428,"end":601.14},{"speaker":"Mia","de":"Die Möglichkeiten sind: A, muss. B, müsse. C, gemusst.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":601.64,"end":607.472},{"speaker":"Tarek","de":"Die richtige Antwort ist A: muss. Im weil-Satz steht das konjugierte Verb am Ende.","ar":"الإجابة الصحيحة: الفعل يأتي في آخر جملة weil.","pauseAfter":1,"kind":"answer","start":610.672,"end":616.432},{"speaker":"Tarek","de":"Frage 4: Welche Form ist richtig?","ar":"السؤال رقم 4. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":617.432,"end":620.504},{"speaker":"Tarek","de":"Die Möglichkeiten sind: A, Ich habe studiert.. B, Ich habe gestudiert.. C, Ich bin studiert..","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":621.004,"end":628.78},{"speaker":"Mia","de":"Die richtige Antwort ist A: Ich habe studiert.. Verben auf -ieren bilden das Partizip ohne ge-.","ar":"الإجابة الصحيحة: أفعال -ieren بدون ge.","pauseAfter":1,"kind":"answer","start":631.98,"end":639.252},{"speaker":"Tarek","de":"Zum Abschluss: Nenne drei neue Wörter aus Kapitel 1 und bilde mit jedem Wort einen Satz.","ar":"في الختام: اذكر ثلاث كلمات جديدة من الدرس 1 وكوّن جملة بكل كلمة.","pauseAfter":4,"kind":"interactive","start":640.252,"end":645.772},{"speaker":"Mia","de":"Wenn das noch schwer ist, höre die Folge morgen noch einmal. Beim zweiten Hören wirst du deutlich mehr verstehen.","ar":"إذا كان الأمر ما زال صعبًا، فاستمع إلى الحلقة غدًا مرة أخرى. في المرة الثانية ستفهم أكثر بوضوح.","pauseAfter":0.7,"kind":"outro","start":649.772,"end":656.78},{"speaker":"Tarek","de":"Danke fürs Zuhören. Das war Ein freier Samstag. Bis zur nächsten Folge!","ar":"شكرًا على الاستماع. كانت هذه حلقة Ein freier Samstag. إلى الحلقة القادمة!","pauseAfter":1,"kind":"outro","start":657.48,"end":663.792}],"people":[{"name":"Mia","gender":"female","age":27,"voice":"de-DE-SeraphinaMultilingualNeural"},{"name":"Tarek","gender":"male","age":31,"voice":"de-DE-ConradNeural"}],"audio":"assets/podcasts/chapter-1.mp3?v=natural-dialogue-2","durationSeconds":664.85},{"chapter":2,"title":"Der Weg nach der Schule","duration":"11 Min.","speakers":["Nora","Jonas"],"intro":"Schule, Ausbildung, Erfahrungen und eine Präsentation.","keywords":["Ausbildung","Berufsschule","Erfahrung","sich bewerben","Präsentation"],"lines":[{"speaker":"Nora","de":"Willkommen zu Folge 2: Der Weg nach der Schule. Ich bin Nora, 19 Jahre alt.","ar":"مرحبًا بكم في الحلقة 2: Der Weg nach der Schule. أنا Nora وعمري 19 عامًا.","pauseAfter":0.5,"kind":"intro","start":0.0,"end":6.192},{"speaker":"Jonas","de":"Und ich bin Jonas, 20 Jahre alt. Heute sprechen wir über Schule, Erfahrungen, Ausbildung, Präsentieren.","ar":"وأنا Jonas وعمري 20 عامًا. سنتحدث اليوم عن موضوعات الدرس.","pauseAfter":0.6,"kind":"intro","start":6.692,"end":14.396},{"speaker":"Nora","de":"Hör zuerst entspannt zu. Danach wiederholen wir wichtige Wörter und Redemittel, und am Ende gibt es Fragen für dich.","ar":"استمع أولًا بهدوء. بعد ذلك سنراجع كلمات وتعبيرات مهمة، وفي النهاية توجد أسئلة لك.","pauseAfter":0.7,"kind":"intro","start":14.996,"end":22.628},{"speaker":"Jonas","de":"Du kannst jederzeit pausieren, laut antworten und anschließend mit unserer Lösung vergleichen. Los geht es!","ar":"يمكنك إيقاف الحلقة والإجابة بصوت عالٍ ثم مقارنة إجابتك بحلنا. لنبدأ!","pauseAfter":1,"kind":"intro","start":23.328,"end":30.624},{"speaker":"Nora","de":"Jonas, weißt du schon, was du nach der Schule machen möchtest?","ar":"يوناس، هل تعرف بالفعل ماذا تريد أن تفعل بعد المدرسة؟","pauseAfter":0.55,"kind":"scene","start":31.624,"end":35.656},{"speaker":"Jonas","de":"Ich interessiere mich für Technik und möchte eine Ausbildung als Mechatroniker machen.","ar":"أنا مهتم بالتقنية وأريد أن أتدرب مهنيًا كفني ميكاترونكس.","pauseAfter":0.55,"kind":"scene","start":36.206,"end":41.438},{"speaker":"Nora","de":"Warum hast du dich für diesen Beruf entschieden?","ar":"لماذا اخترت هذه المهنة؟","pauseAfter":0.55,"kind":"scene","start":41.988,"end":44.772},{"speaker":"Jonas","de":"Bei einem Praktikum habe ich viele Maschinen gesehen und durfte kleine Aufgaben selbst erledigen.","ar":"خلال تدريب عملي رأيت آلات كثيرة وسُمح لي بإنجاز مهام صغيرة بنفسي.","pauseAfter":0.55,"kind":"scene","start":45.322,"end":51.106},{"speaker":"Nora","de":"Musst du während der Ausbildung auch eine Berufsschule besuchen?","ar":"هل يجب عليك أيضًا حضور مدرسة مهنية أثناء التدريب؟","pauseAfter":0.55,"kind":"scene","start":51.656,"end":55.328},{"speaker":"Jonas","de":"Ja, an zwei Tagen pro Woche lerne ich dort Theorie. An den anderen Tagen arbeite ich im Betrieb.","ar":"نعم، أتعلم هناك النظريات يومين في الأسبوع. وفي الأيام الأخرى أعمل في الشركة.","pauseAfter":0.55,"kind":"scene","start":55.878,"end":62.502},{"speaker":"Nora","de":"Ich muss morgen meine Berufsidee in der Klasse präsentieren. Ich bin schon ein bisschen nervös.","ar":"يجب أن أعرض فكرتي المهنية غدًا أمام الفصل. أنا متوترة قليلًا بالفعل.","pauseAfter":0.55,"kind":"scene","start":63.052,"end":68.812},{"speaker":"Jonas","de":"Mach dir Stichpunkte und sprich langsam. Dann wird deine Präsentation bestimmt gut.","ar":"اكتبي نقاطًا مختصرة وتحدثي ببطء. عندها سيكون عرضك جيدًا بالتأكيد.","pauseAfter":0.55,"kind":"scene","start":69.362,"end":75.17},{"speaker":"Nora","de":"Am nächsten Tag üben Nora und Jonas gemeinsam für Noras Präsentation.","ar":"في اليوم التالي تتدرب نورا ويوناس معًا على العرض.","pauseAfter":0.28,"kind":"scene","start":75.72,"end":80.376},{"speaker":"Jonas","de":"Wie möchtest du anfangen? Der erste Satz ist besonders wichtig.","ar":"كيف تريدين البدء؟ الجملة الأولى مهمة جدًا.","pauseAfter":0.28,"kind":"scene","start":80.656,"end":85.696},{"speaker":"Nora","de":"Ich erzähle zuerst von meiner Schulzeit und meinem Lieblingsfach Biologie.","ar":"سأتحدث أولًا عن فترة المدرسة ومادتي المفضلة الأحياء.","pauseAfter":0.28,"kind":"scene","start":85.976,"end":90.392},{"speaker":"Jonas","de":"Und danach kannst du erklären, warum du eine Ausbildung machen möchtest.","ar":"وبعد ذلك يمكنك شرح سبب رغبتك في التدريب المهني.","pauseAfter":0.28,"kind":"scene","start":90.672,"end":95.016},{"speaker":"Nora","de":"Bei meinem Praktikum im Labor habe ich gute Erfahrungen gemacht.","ar":"اكتسبت خبرات جيدة خلال تدريبي في المختبر.","pauseAfter":0.28,"kind":"scene","start":95.296,"end":99.136},{"speaker":"Jonas","de":"Gab es dort auch eine Aufgabe, die dir schwergefallen ist?","ar":"هل كانت هناك مهمة صعبة عليك؟","pauseAfter":0.28,"kind":"scene","start":99.416,"end":103.544},{"speaker":"Nora","de":"Ja, am Anfang musste ich viele Geräte kennenlernen und genau dokumentieren.","ar":"نعم، في البداية كان عليّ تعلم أجهزة كثيرة وتوثيق كل شيء بدقة.","pauseAfter":0.28,"kind":"scene","start":103.824,"end":108.984},{"speaker":"Jonas","de":"Das zeigt, dass du sorgfältig arbeitest und schnell lernen kannst.","ar":"هذا يوضح أنك تعملين بعناية وتتعلمين بسرعة.","pauseAfter":0.28,"kind":"scene","start":109.264,"end":113.632},{"speaker":"Nora","de":"Meinst du, ich soll auch mein Zeugnis und meine Noten erwähnen?","ar":"هل أذكر شهادتي ودرجاتي أيضًا؟","pauseAfter":0.28,"kind":"scene","start":113.912,"end":117.848},{"speaker":"Jonas","de":"Nur kurz. Deine praktische Erfahrung ist für die Zuhörer interessanter.","ar":"باختصار فقط. خبرتك العملية أكثر إثارة للمستمعين.","pauseAfter":0.28,"kind":"scene","start":118.128,"end":123.576},{"speaker":"Nora","de":"Ich bin trotzdem nervös, wenn ich vor der ganzen Klasse stehe.","ar":"أنا متوترة رغم ذلك عندما أقف أمام الفصل كله.","pauseAfter":0.28,"kind":"scene","start":123.856,"end":127.672},{"speaker":"Jonas","de":"Schau nicht ständig auf deine Karten und mach nach jedem Abschnitt eine Pause.","ar":"لا تنظري باستمرار إلى البطاقات وخذي وقفة بعد كل جزء.","pauseAfter":0.28,"kind":"scene","start":127.952,"end":132.728},{"speaker":"Nora","de":"Kannst du am Ende eine Frage stellen, als wärst du im Publikum?","ar":"هل يمكنك طرح سؤال في النهاية كأنك من الجمهور؟","pauseAfter":0.28,"kind":"scene","start":133.008,"end":137.112},{"speaker":"Jonas","de":"Natürlich: Welche Voraussetzung braucht man für diese Ausbildung?","ar":"بالطبع: ما الشرط المطلوب لهذا التدريب المهني؟","pauseAfter":0.28,"kind":"scene","start":137.392,"end":141.784},{"speaker":"Nora","de":"Man braucht einen guten Schulabschluss und Interesse an Naturwissenschaften.","ar":"يحتاج المرء إلى شهادة مدرسية جيدة واهتمام بالعلوم الطبيعية.","pauseAfter":0.28,"kind":"scene","start":142.064,"end":146.528},{"speaker":"Jonas","de":"Sehr gut. Jetzt klingt deine Antwort klar, ruhig und überzeugend.","ar":"جيد جدًا. إجابتك الآن واضحة وهادئة ومقنعة.","pauseAfter":0.28,"kind":"scene","start":146.808,"end":152.472},{"speaker":"Nora","de":"Das war unsere erste Alltagsszene. Welche Wörter und Sätze hast du sofort verstanden?","ar":"كان هذا مشهدنا اليومي الأول. ما الكلمات والجمل التي فهمتها فورًا؟","pauseAfter":3.2,"kind":"interactive","start":152.752,"end":158.752},{"speaker":"Jonas","de":"Denk kurz nach. Du musst nicht jedes Wort verstehen. Wichtig ist zuerst die Situation.","ar":"فكّر قليلًا. ليس ضروريًا أن تفهم كل كلمة؛ المهم أولًا هو فهم الموقف.","pauseAfter":2.4,"kind":"interactive","start":161.952,"end":168.816},{"speaker":"Nora","de":"Die Situation passt zu Kapitel 2. Jetzt sehen wir uns den Wortschatz genauer an.","ar":"الموقف مرتبط بالدرس 2. والآن سنراجع المفردات بدقة أكبر.","pauseAfter":0.8,"kind":"section","start":171.216,"end":176.976},{"speaker":"Nora","de":"Wort Nummer 1: das Schulfach, ⸚er. Hör genau zu: das Schulfach, ⸚er.","ar":"الكلمة رقم 1: مادة دراسية. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":177.776,"end":183.656},{"speaker":"Jonas","de":"das Schulfach, ⸚er bedeutet: Ein Unterrichtsbereich wie Mathematik oder Geschichte. Ein Beispiel: Biologie war mein Lieblingsfach.","ar":"معنى das Schulfach, ⸚er: مادة دراسية.","pauseAfter":0.6,"kind":"vocab","start":184.106,"end":192.722},{"speaker":"Nora","de":"Jetzt bist du dran. Sprich laut nach: das Schulfach, ⸚er.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: das Schulfach, ⸚er.","pauseAfter":1.8,"kind":"interactive","start":193.322,"end":197.906},{"speaker":"Jonas","de":"Wort Nummer 2: die Grundschule, -n. Hör genau zu: die Grundschule, -n.","ar":"الكلمة رقم 2: المدرسة الابتدائية. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":199.706,"end":205.106},{"speaker":"Nora","de":"die Grundschule, -n bedeutet: Die erste Schule für Kinder. Ein Beispiel: Mit sechs Jahren kam ich in die Grundschule.","ar":"معنى die Grundschule, -n: المدرسة الابتدائية.","pauseAfter":0.6,"kind":"vocab","start":205.556,"end":213.74},{"speaker":"Jonas","de":"Jetzt bist du dran. Sprich laut nach: die Grundschule, -n.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Grundschule, -n.","pauseAfter":1.8,"kind":"interactive","start":214.34,"end":219.452},{"speaker":"Nora","de":"Wort Nummer 3: die Berufsschule, -n. Hör genau zu: die Berufsschule, -n.","ar":"الكلمة رقم 3: مدرسة التعليم المهني. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":221.252,"end":227.06},{"speaker":"Jonas","de":"die Berufsschule, -n bedeutet: Eine Schule während einer beruflichen Ausbildung. Ein Beispiel: Zweimal pro Woche war sie in der Berufsschule.","ar":"معنى die Berufsschule, -n: مدرسة التعليم المهني.","pauseAfter":0.6,"kind":"vocab","start":227.51,"end":236.558},{"speaker":"Nora","de":"Jetzt bist du dran. Sprich laut nach: die Berufsschule, -n.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Berufsschule, -n.","pauseAfter":1.8,"kind":"interactive","start":237.158,"end":242.078},{"speaker":"Jonas","de":"Wort Nummer 4: die Ausbildung, -en. Hör genau zu: die Ausbildung, -en.","ar":"الكلمة رقم 4: تدريب مهني. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":243.878,"end":250.118},{"speaker":"Nora","de":"die Ausbildung, -en bedeutet: Praktisches und theoretisches Lernen für einen Beruf. Ein Beispiel: Er macht eine Ausbildung zum Koch.","ar":"معنى die Ausbildung, -en: تدريب مهني.","pauseAfter":0.6,"kind":"vocab","start":250.568,"end":259.496},{"speaker":"Jonas","de":"Jetzt bist du dran. Sprich laut nach: die Ausbildung, -en.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Ausbildung, -en.","pauseAfter":1.8,"kind":"interactive","start":260.096,"end":265.256},{"speaker":"Nora","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":267.056,"end":273.584},{"speaker":"Jonas","de":"Die Wörter waren: das Schulfach, ⸚er, die Grundschule, -n, die Berufsschule, -n, die Ausbildung, -en.","ar":"الكلمات كانت: مادة دراسية، المدرسة الابتدائية، مدرسة التعليم المهني، تدريب مهني.","pauseAfter":1,"kind":"answer","start":276.584,"end":283.688},{"speaker":"Nora","de":"Wort Nummer 5: der Abschluss, ⸚e. Hör genau zu: der Abschluss, ⸚e.","ar":"الكلمة رقم 5: شهادة / تخرّج. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":284.688,"end":290.352},{"speaker":"Jonas","de":"der Abschluss, ⸚e bedeutet: Ein offizielles Ende von Schule oder Studium. Ein Beispiel: Für die Stelle braucht man einen Abschluss.","ar":"معنى der Abschluss, ⸚e: شهادة / تخرّج.","pauseAfter":0.6,"kind":"vocab","start":290.802,"end":299.418},{"speaker":"Nora","de":"Jetzt bist du dran. Sprich laut nach: der Abschluss, ⸚e.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Abschluss, ⸚e.","pauseAfter":1.8,"kind":"interactive","start":300.018,"end":304.818},{"speaker":"Jonas","de":"Wort Nummer 6: die Erfahrung, -en. Hör genau zu: die Erfahrung, -en.","ar":"الكلمة رقم 6: خبرة. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":306.618,"end":312.834},{"speaker":"Nora","de":"die Erfahrung, -en bedeutet: Wissen, das man durch Erlebnisse bekommt. Ein Beispiel: Das Praktikum war eine wichtige Erfahrung.","ar":"معنى die Erfahrung, -en: خبرة.","pauseAfter":0.6,"kind":"vocab","start":313.284,"end":322.188},{"speaker":"Jonas","de":"Jetzt bist du dran. Sprich laut nach: die Erfahrung, -en.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Erfahrung, -en.","pauseAfter":1.8,"kind":"interactive","start":322.788,"end":327.876},{"speaker":"Nora","de":"Wort Nummer 7: das Zeugnis, -se. Hör genau zu: das Zeugnis, -se.","ar":"الكلمة رقم 7: شهادة درجات. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":329.676,"end":336.156},{"speaker":"Jonas","de":"das Zeugnis, -se bedeutet: Ein Dokument mit Noten oder einer Bewertung. Ein Beispiel: Am Schuljahresende bekommen alle ein Zeugnis.","ar":"معنى das Zeugnis, -se: شهادة درجات.","pauseAfter":0.6,"kind":"vocab","start":336.606,"end":345.702},{"speaker":"Nora","de":"Jetzt bist du dran. Sprich laut nach: das Zeugnis, -se.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: das Zeugnis, -se.","pauseAfter":1.8,"kind":"interactive","start":346.302,"end":351.102},{"speaker":"Jonas","de":"Wort Nummer 8: die Note, -n. Hör genau zu: die Note, -n.","ar":"الكلمة رقم 8: درجة. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":352.902,"end":357.678},{"speaker":"Nora","de":"die Note, -n bedeutet: Eine Bewertung für eine Leistung. Ein Beispiel: Ich hatte eine gute Note in Deutsch.","ar":"معنى die Note, -n: درجة.","pauseAfter":0.6,"kind":"vocab","start":358.128,"end":365.976},{"speaker":"Jonas","de":"Jetzt bist du dran. Sprich laut nach: die Note, -n.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Note, -n.","pauseAfter":1.8,"kind":"interactive","start":366.576,"end":371.4},{"speaker":"Nora","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":373.2,"end":379.728},{"speaker":"Jonas","de":"Die Wörter waren: der Abschluss, ⸚e, die Erfahrung, -en, das Zeugnis, -se, die Note, -n.","ar":"الكلمات كانت: شهادة / تخرّج، خبرة، شهادة درجات، درجة.","pauseAfter":1,"kind":"answer","start":382.728,"end":389.688},{"speaker":"Nora","de":"Wort Nummer 9: bestehen. Hör genau zu: bestehen.","ar":"الكلمة رقم 9: ينجح في امتحان. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":390.688,"end":395.392},{"speaker":"Jonas","de":"bestehen bedeutet: Eine Prüfung erfolgreich machen. Ein Beispiel: Sie hat die Prüfung bestanden.","ar":"معنى bestehen: ينجح في امتحان.","pauseAfter":0.6,"kind":"vocab","start":395.842,"end":402.538},{"speaker":"Nora","de":"Jetzt bist du dran. Sprich laut nach: bestehen.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: bestehen.","pauseAfter":1.8,"kind":"interactive","start":403.138,"end":407.098},{"speaker":"Jonas","de":"Wort Nummer 10: sich erinnern an. Hör genau zu: sich erinnern an.","ar":"الكلمة رقم 10: يتذكر. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":408.898,"end":414.514},{"speaker":"Nora","de":"sich erinnern an bedeutet: Etwas aus der Vergangenheit wieder wissen. Ein Beispiel: Ich erinnere mich gern an meine Lehrerin.","ar":"معنى sich erinnern an: يتذكر.","pauseAfter":0.6,"kind":"vocab","start":414.964,"end":423.724},{"speaker":"Jonas","de":"Jetzt bist du dran. Sprich laut nach: sich erinnern an.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: sich erinnern an.","pauseAfter":1.8,"kind":"interactive","start":424.324,"end":429.148},{"speaker":"Jonas","de":"Sehr gut. Wörter allein reichen aber nicht. Im Gespräch brauchen wir fertige Sätze und passende Reaktionen.","ar":"جيد جدًا. الكلمات وحدها لا تكفي؛ في الحوار نحتاج إلى جمل جاهزة وردود مناسبة.","pauseAfter":0.8,"kind":"section","start":430.948,"end":438.964},{"speaker":"Nora","de":"Situation 1, Über die Schulzeit sprechen. Was könntest du sagen?","ar":"الموقف رقم 1. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":439.764,"end":444.876},{"speaker":"Jonas","de":"Eine passende Formulierung ist: Als ich in der Schule war, musste ich …","ar":"تعبير مناسب هو: لما كنت في المدرسة كان لازم ...","pauseAfter":0.7,"kind":"phrase","start":447.076,"end":451.588},{"speaker":"Nora","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Als ich in der Schule war, musste ich …","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":452.288,"end":458.24},{"speaker":"Jonas","de":"Situation 2, Über die Schulzeit sprechen. Was könntest du sagen?","ar":"الموقف رقم 2. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":460.44,"end":465.96},{"speaker":"Nora","de":"Eine passende Formulierung ist: Mein Lieblingsfach war …, weil …","ar":"تعبير مناسب هو: مادتي المفضلة كانت ... لأن ...","pauseAfter":0.7,"kind":"phrase","start":468.16,"end":472.48},{"speaker":"Jonas","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Mein Lieblingsfach war …, weil …","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":473.18,"end":478.484},{"speaker":"Nora","de":"Situation 3, Über die Schulzeit sprechen. Was könntest du sagen?","ar":"الموقف رقم 3. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":480.684,"end":485.772},{"speaker":"Jonas","de":"Eine passende Formulierung ist: Mit meiner Klassenlehrerin hatte ich gute Erfahrungen.","ar":"تعبير مناسب هو: كانت عندي تجارب جيدة مع مدرسة الفصل.","pauseAfter":0.7,"kind":"phrase","start":487.972,"end":493.204},{"speaker":"Nora","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Mit meiner Klassenlehrerin hatte ich gute Erfahrungen.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":493.904,"end":500.312},{"speaker":"Jonas","de":"Situation 4, Über die Schulzeit sprechen. Was könntest du sagen?","ar":"الموقف رقم 4. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":502.512,"end":508.056},{"speaker":"Nora","de":"Eine passende Formulierung ist: Ich erinnere mich besonders an …","ar":"تعبير مناسب هو: أتذكر خصوصًا ...","pauseAfter":0.7,"kind":"phrase","start":510.256,"end":514.936},{"speaker":"Jonas","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Ich erinnere mich besonders an …","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":515.636,"end":521.084},{"speaker":"Nora","de":"Situation 5, Die Meinung sagen. Was könntest du sagen?","ar":"الموقف رقم 5. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":523.284,"end":527.94},{"speaker":"Jonas","de":"Eine passende Formulierung ist: Meiner Meinung nach sollte Schule mehr auf das Leben vorbereiten.","ar":"تعبير مناسب هو: في رأيي المدرسة لازم تجهز للحياة أكتر.","pauseAfter":0.7,"kind":"phrase","start":530.14,"end":535.684},{"speaker":"Nora","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Meiner Meinung nach sollte Schule mehr auf das Leben vorbereiten.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":536.384,"end":543.104},{"speaker":"Jonas","de":"Situation 6, Die Meinung sagen. Was könntest du sagen?","ar":"الموقف رقم 6. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":545.304,"end":550.512},{"speaker":"Nora","de":"Eine passende Formulierung ist: Ich finde wichtig, dass …","ar":"تعبير مناسب هو: شايف إنه مهم إن ...","pauseAfter":0.7,"kind":"phrase","start":552.712,"end":556.792},{"speaker":"Jonas","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Ich finde wichtig, dass …","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":557.492,"end":562.58},{"speaker":"Nora","de":"Jetzt kommt ein kurzer Hör- und Grammatikcheck. Antworte zuerst selbst. Danach hörst du die Lösung.","ar":"والآن اختبار قصير في الاستماع والقواعد. أجب أولًا بنفسك ثم استمع إلى الحل.","pauseAfter":0.8,"kind":"section","start":564.78,"end":572.004},{"speaker":"Nora","de":"Frage 1: Früher ___ wir samstags zur Schule gehen.","ar":"السؤال رقم 1. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":572.804,"end":578.516},{"speaker":"Nora","de":"Die Möglichkeiten sind: A, müssen. B, mussten. C, gemusst.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":579.016,"end":584.872},{"speaker":"Jonas","de":"Die richtige Antwort ist B: mussten. Vergangenheit: mussten.","ar":"الإجابة الصحيحة: الماضي من müssen هو mussten.","pauseAfter":1,"kind":"answer","start":588.072,"end":593.496},{"speaker":"Jonas","de":"Frage 2: Ich ___ im Unterricht nicht essen.","ar":"السؤال رقم 2. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":594.496,"end":599.296},{"speaker":"Jonas","de":"Die Möglichkeiten sind: A, durfte. B, darfte. C, dürfen.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":599.796,"end":606.444},{"speaker":"Nora","de":"Die richtige Antwort ist A: durfte. dürfen → durfte.","ar":"الإجابة الصحيحة: الماضي من dürfen هو durfte.","pauseAfter":1,"kind":"answer","start":609.644,"end":613.988},{"speaker":"Nora","de":"Frage 3: Mit ___ Lehrerin spreche ich oft.","ar":"السؤال رقم 3. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":614.988,"end":620.364},{"speaker":"Nora","de":"Die Möglichkeiten sind: A, meine. B, meiner. C, meinem.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":620.864,"end":626.552},{"speaker":"Jonas","de":"Die richtige Antwort ist B: meiner. Feminin Dativ: meiner.","ar":"الإجابة الصحيحة: مؤنث Dativ: meiner.","pauseAfter":1,"kind":"answer","start":629.752,"end":635.296},{"speaker":"Jonas","de":"Frage 4: Er erzählt von ___ Praktikum.","ar":"السؤال رقم 4. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":636.296,"end":640.856},{"speaker":"Jonas","de":"Die Möglichkeiten sind: A, seinem. B, seinen. C, seiner.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":641.356,"end":647.884},{"speaker":"Nora","de":"Die richtige Antwort ist A: seinem. Neutrum Dativ: seinem Praktikum.","ar":"الإجابة الصحيحة: محايد Dativ: seinem.","pauseAfter":1,"kind":"answer","start":651.084,"end":656.796},{"speaker":"Jonas","de":"Zum Abschluss: Nenne drei neue Wörter aus Kapitel 2 und bilde mit jedem Wort einen Satz.","ar":"في الختام: اذكر ثلاث كلمات جديدة من الدرس 2 وكوّن جملة بكل كلمة.","pauseAfter":4,"kind":"interactive","start":657.796,"end":663.604},{"speaker":"Nora","de":"Wenn das noch schwer ist, höre die Folge morgen noch einmal. Beim zweiten Hören wirst du deutlich mehr verstehen.","ar":"إذا كان الأمر ما زال صعبًا، فاستمع إلى الحلقة غدًا مرة أخرى. في المرة الثانية ستفهم أكثر بوضوح.","pauseAfter":0.7,"kind":"outro","start":667.604,"end":674.612},{"speaker":"Jonas","de":"Danke fürs Zuhören. Das war Der Weg nach der Schule. Bis zur nächsten Folge!","ar":"شكرًا على الاستماع. كانت هذه حلقة Der Weg nach der Schule. إلى الحلقة القادمة!","pauseAfter":1,"kind":"outro","start":675.312,"end":681.744}],"people":[{"name":"Nora","gender":"female","age":19,"voice":"de-DE-SeraphinaMultilingualNeural"},{"name":"Jonas","gender":"male","age":20,"voice":"de-DE-KillianNeural"}],"audio":"assets/podcasts/chapter-2.mp3?v=natural-dialogue-2","durationSeconds":682.8},{"chapter":3,"title":"Ein Abend ohne Handy","duration":"11 Min.","speakers":["Lea","Samir"],"intro":"Medien, Online-Zeit, Filme und Meinungen.","keywords":["Bildschirm","teilen","Nachricht","spannend","Vergleich"],"lines":[{"speaker":"Lea","de":"Willkommen zu Folge 3: Ein Abend ohne Handy. Ich bin Lea, 25 Jahre alt.","ar":"مرحبًا بكم في الحلقة 3: Ein Abend ohne Handy. أنا Lea وعمري 25 عامًا.","pauseAfter":0.5,"kind":"intro","start":0.0,"end":6.888},{"speaker":"Samir","de":"Und ich bin Samir, 28 Jahre alt. Heute sprechen wir über Medien, Vergleiche, Meinungen, Film.","ar":"وأنا Samir وعمري 28 عامًا. سنتحدث اليوم عن موضوعات الدرس.","pauseAfter":0.6,"kind":"intro","start":7.388,"end":14.276},{"speaker":"Lea","de":"Hör zuerst entspannt zu. Danach wiederholen wir wichtige Wörter und Redemittel, und am Ende gibt es Fragen für dich.","ar":"استمع أولًا بهدوء. بعد ذلك سنراجع كلمات وتعبيرات مهمة، وفي النهاية توجد أسئلة لك.","pauseAfter":0.7,"kind":"intro","start":14.876,"end":22.508},{"speaker":"Samir","de":"Du kannst jederzeit pausieren, laut antworten und anschließend mit unserer Lösung vergleichen. Los geht es!","ar":"يمكنك إيقاف الحلقة والإجابة بصوت عالٍ ثم مقارنة إجابتك بحلنا. لنبدأ!","pauseAfter":1,"kind":"intro","start":23.208,"end":29.28},{"speaker":"Lea","de":"Samir, wie viele Stunden bist du jeden Tag online?","ar":"سمير، كم ساعة تكون متصلًا بالإنترنت كل يوم؟","pauseAfter":0.55,"kind":"scene","start":30.28,"end":33.784},{"speaker":"Samir","de":"Wahrscheinlich zu viele. Ich lese Nachrichten, beantworte Nachrichten und sehe kurze Videos.","ar":"على الأرجح ساعات كثيرة جدًا. أقرأ الأخبار وأجيب عن الرسائل وأشاهد مقاطع قصيرة.","pauseAfter":0.55,"kind":"scene","start":34.334,"end":39.974},{"speaker":"Lea","de":"Bei mir ist es ähnlich. Deshalb legen wir zu Hause die Handys beim Abendessen weg.","ar":"الأمر مشابه عندي. لذلك نضع الهواتف بعيدًا أثناء العشاء في المنزل.","pauseAfter":0.55,"kind":"scene","start":40.524,"end":45.996},{"speaker":"Samir","de":"Eine gute Idee. Gestern wollte ich einen Film sehen, aber ich habe ständig auf den Bildschirm geschaut.","ar":"فكرة جيدة. أمس أردت مشاهدة فيلم، لكنني ظللت أنظر إلى الشاشة باستمرار.","pauseAfter":0.55,"kind":"scene","start":46.546,"end":52.114},{"speaker":"Lea","de":"Welchen Film hast du ausgewählt?","ar":"أي فيلم اخترت؟","pauseAfter":0.55,"kind":"scene","start":52.664,"end":55.088},{"speaker":"Samir","de":"Eine deutsche Komödie. Sie war lustiger als der letzte Film, aber die Geschichte war nicht so spannend.","ar":"فيلم كوميدي ألماني. كان أكثر طرافة من الفيلم السابق، لكن القصة لم تكن مثيرة بنفس القدر.","pauseAfter":0.55,"kind":"scene","start":55.638,"end":61.182},{"speaker":"Lea","de":"Schickst du mir den Titel? Vielleicht sehen wir ihn am Freitag zusammen.","ar":"هل سترسل لي العنوان؟ ربما نشاهده معًا يوم الجمعة.","pauseAfter":0.55,"kind":"scene","start":61.732,"end":66.244},{"speaker":"Samir","de":"Gern. Aber wir teilen diesmal keine Fotos und lassen die Handys in der Tasche.","ar":"بكل سرور. لكن هذه المرة لن نشارك صورًا وسنترك الهواتف في الحقيبة.","pauseAfter":0.55,"kind":"scene","start":66.794,"end":71.306},{"speaker":"Lea","de":"Am Freitag treffen sich Lea und Samir tatsächlich zu einem Abend ohne Handy.","ar":"يوم الجمعة يلتقي ليا وسمير فعلًا لقضاء أمسية بلا هاتف.","pauseAfter":0.28,"kind":"scene","start":71.856,"end":76.512},{"speaker":"Samir","de":"Ich lege mein Handy in die Schublade. Machst du wirklich mit?","ar":"سأضع هاتفي في الدرج. هل ستشارك حقًا؟","pauseAfter":0.28,"kind":"scene","start":76.792,"end":80.464},{"speaker":"Lea","de":"Ja, aber vorher muss ich meiner Familie noch eine Nachricht schicken.","ar":"نعم، لكن يجب أن أرسل رسالة لعائلتي أولًا.","pauseAfter":0.28,"kind":"scene","start":80.744,"end":84.848},{"speaker":"Samir","de":"In Ordnung. Danach vergleichen wir zwei Filme und wählen gemeinsam einen aus.","ar":"حسنًا. بعدها نقارن فيلمين ونختار واحدًا معًا.","pauseAfter":0.28,"kind":"scene","start":85.128,"end":89.832},{"speaker":"Lea","de":"Diese Komödie hat eine bessere Bewertung als der andere Film.","ar":"هذا الفيلم الكوميدي تقييمه أفضل من الفيلم الآخر.","pauseAfter":0.28,"kind":"scene","start":90.112,"end":94.024},{"speaker":"Samir","de":"Die Quelle ist aber nicht sehr zuverlässig. Es gibt nur fünf Bewertungen.","ar":"لكن المصدر غير موثوق جدًا، فهناك خمسة تقييمات فقط.","pauseAfter":0.28,"kind":"scene","start":94.304,"end":98.696},{"speaker":"Lea","de":"Dann sehen wir uns lieber den Trailer an. Die Handlung wirkt spannend.","ar":"إذن من الأفضل أن نشاهد الإعلان. تبدو القصة مثيرة.","pauseAfter":0.28,"kind":"scene","start":98.976,"end":103.584},{"speaker":"Samir","de":"Die Hauptfigur gefällt mir. Sie spielt eine Journalistin in Berlin.","ar":"تعجبني الشخصية الرئيسية. إنها تؤدي دور صحفية في برلين.","pauseAfter":0.28,"kind":"scene","start":103.864,"end":108.064},{"speaker":"Lea","de":"Während des Films teilen wir keine Fotos und beantworten keine Nachrichten.","ar":"أثناء الفيلم لن نشارك صورًا ولن نجيب عن رسائل.","pauseAfter":0.28,"kind":"scene","start":108.344,"end":112.952},{"speaker":"Samir","de":"Das wird schwer. Meine Bildschirmzeit war heute schon vier Stunden.","ar":"سيكون ذلك صعبًا. وقت الشاشة عندي بلغ أربع ساعات اليوم.","pauseAfter":0.28,"kind":"scene","start":113.232,"end":117.192},{"speaker":"Lea","de":"Ein Vorteil ist, dass wir uns besser auf den Film konzentrieren können.","ar":"من المميزات أننا نستطيع التركيز على الفيلم بصورة أفضل.","pauseAfter":0.28,"kind":"scene","start":117.472,"end":121.816},{"speaker":"Samir","de":"Und ein Nachteil ist, dass niemand unsere wichtigen Nachrichten liest.","ar":"ومن العيوب أن أحدًا لن يقرأ رسائلنا المهمة.","pauseAfter":0.28,"kind":"scene","start":122.096,"end":125.816},{"speaker":"Lea","de":"Nach dem Film schauen wir zehn Minuten aufs Handy. Das ist ein guter Kompromiss.","ar":"بعد الفيلم ننظر إلى الهاتف عشر دقائق. هذا حل وسط جيد.","pauseAfter":0.28,"kind":"scene","start":126.096,"end":131.304},{"speaker":"Samir","de":"Einverstanden. Einerseits bleiben wir erreichbar, andererseits haben wir einen ruhigen Abend.","ar":"موافق. نبقى متاحين من ناحية ونقضي أمسية هادئة من ناحية أخرى.","pauseAfter":0.28,"kind":"scene","start":131.584,"end":137.008},{"speaker":"Lea","de":"Jetzt drück auf Start. Mein Handy bleibt wirklich in der Schublade.","ar":"الآن شغّل الفيلم. سيبقى هاتفي فعلًا في الدرج.","pauseAfter":0.28,"kind":"scene","start":137.288,"end":142.088},{"speaker":"Samir","de":"Meins auch. Heute gewinnt der Film gegen den kleinen Bildschirm.","ar":"وهاتفي أيضًا. اليوم سيفوز الفيلم على الشاشة الصغيرة.","pauseAfter":0.28,"kind":"scene","start":142.368,"end":146.328},{"speaker":"Lea","de":"Das war unsere erste Alltagsszene. Welche Wörter und Sätze hast du sofort verstanden?","ar":"كان هذا مشهدنا اليومي الأول. ما الكلمات والجمل التي فهمتها فورًا؟","pauseAfter":3.2,"kind":"interactive","start":146.608,"end":152.608},{"speaker":"Samir","de":"Denk kurz nach. Du musst nicht jedes Wort verstehen. Wichtig ist zuerst die Situation.","ar":"فكّر قليلًا. ليس ضروريًا أن تفهم كل كلمة؛ المهم أولًا هو فهم الموقف.","pauseAfter":2.4,"kind":"interactive","start":155.808,"end":161.544},{"speaker":"Lea","de":"Die Situation passt zu Kapitel 3. Jetzt sehen wir uns den Wortschatz genauer an.","ar":"الموقف مرتبط بالدرس 3. والآن سنراجع المفردات بدقة أكبر.","pauseAfter":0.8,"kind":"section","start":163.944,"end":169.584},{"speaker":"Lea","de":"Wort Nummer 1: das Medium, Medien. Hör genau zu: das Medium, Medien.","ar":"الكلمة رقم 1: وسيلة إعلام. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":170.384,"end":176.72},{"speaker":"Samir","de":"das Medium, Medien bedeutet: Ein Mittel für Information oder Unterhaltung. Ein Beispiel: Radio und Internet sind verschiedene Medien.","ar":"معنى das Medium, Medien: وسيلة إعلام.","pauseAfter":0.6,"kind":"vocab","start":177.17,"end":185.474},{"speaker":"Lea","de":"Jetzt bist du dran. Sprich laut nach: das Medium, Medien.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: das Medium, Medien.","pauseAfter":1.8,"kind":"interactive","start":186.074,"end":190.994},{"speaker":"Samir","de":"Wort Nummer 2: die Nachricht, -en. Hör genau zu: die Nachricht, -en.","ar":"الكلمة رقم 2: خبر / رسالة. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":192.794,"end":198.506},{"speaker":"Lea","de":"die Nachricht, -en bedeutet: Eine neue Information über ein Ereignis. Ein Beispiel: Ich lese morgens die Nachrichten.","ar":"معنى die Nachricht, -en: خبر / رسالة.","pauseAfter":0.6,"kind":"vocab","start":198.956,"end":207.476},{"speaker":"Samir","de":"Jetzt bist du dran. Sprich laut nach: die Nachricht, -en.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Nachricht, -en.","pauseAfter":1.8,"kind":"interactive","start":208.076,"end":212.372},{"speaker":"Lea","de":"Wort Nummer 3: die Bildschirmzeit. Hör genau zu: die Bildschirmzeit.","ar":"الكلمة رقم 3: وقت الشاشة. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":214.172,"end":219.764},{"speaker":"Samir","de":"die Bildschirmzeit bedeutet: Die Zeit vor Handy, Computer oder Fernseher. Ein Beispiel: Meine Bildschirmzeit ist heute zu lang.","ar":"معنى die Bildschirmzeit: وقت الشاشة.","pauseAfter":0.6,"kind":"vocab","start":220.214,"end":228.206},{"speaker":"Lea","de":"Jetzt bist du dran. Sprich laut nach: die Bildschirmzeit.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Bildschirmzeit.","pauseAfter":1.8,"kind":"interactive","start":228.806,"end":233.366},{"speaker":"Samir","de":"Wort Nummer 4: herunterladen. Hör genau zu: herunterladen.","ar":"الكلمة رقم 4: يحمّل. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":235.166,"end":240.134},{"speaker":"Lea","de":"herunterladen bedeutet: Daten aus dem Internet auf ein Gerät holen. Ein Beispiel: Ich lade den Film herunter.","ar":"معنى herunterladen: يحمّل.","pauseAfter":0.6,"kind":"vocab","start":240.584,"end":248.384},{"speaker":"Samir","de":"Jetzt bist du dran. Sprich laut nach: herunterladen.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: herunterladen.","pauseAfter":1.8,"kind":"interactive","start":248.984,"end":252.848},{"speaker":"Lea","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":254.648,"end":261.176},{"speaker":"Samir","de":"Die Wörter waren: das Medium, Medien, die Nachricht, -en, die Bildschirmzeit, herunterladen.","ar":"الكلمات كانت: وسيلة إعلام، خبر / رسالة، وقت الشاشة، يحمّل.","pauseAfter":1,"kind":"answer","start":264.176,"end":270.224},{"speaker":"Lea","de":"Wort Nummer 5: hochladen. Hör genau zu: hochladen.","ar":"الكلمة رقم 5: يرفع ملفًا. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":271.224,"end":276.12},{"speaker":"Samir","de":"hochladen bedeutet: Daten vom Gerät ins Internet stellen. Ein Beispiel: Sie lädt ein Foto hoch.","ar":"معنى hochladen: يرفع ملفًا.","pauseAfter":0.6,"kind":"vocab","start":276.57,"end":282.786},{"speaker":"Lea","de":"Jetzt bist du dran. Sprich laut nach: hochladen.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: hochladen.","pauseAfter":1.8,"kind":"interactive","start":283.386,"end":287.442},{"speaker":"Samir","de":"Wort Nummer 6: teilen. Hör genau zu: teilen.","ar":"الكلمة رقم 6: يشارك. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":289.242,"end":293.346},{"speaker":"Lea","de":"teilen bedeutet: Etwas digital an andere schicken. Ein Beispiel: Bitte teile den Link mit mir.","ar":"معنى teilen: يشارك.","pauseAfter":0.6,"kind":"vocab","start":293.796,"end":300.828},{"speaker":"Samir","de":"Jetzt bist du dran. Sprich laut nach: teilen.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: teilen.","pauseAfter":1.8,"kind":"interactive","start":301.428,"end":304.884},{"speaker":"Lea","de":"Wort Nummer 7: der Vorteil, -e. Hör genau zu: der Vorteil, -e.","ar":"الكلمة رقم 7: ميزة. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":306.684,"end":311.892},{"speaker":"Samir","de":"der Vorteil, -e bedeutet: Eine positive Seite. Ein Beispiel: Ein Vorteil ist der schnelle Zugang.","ar":"معنى der Vorteil, -e: ميزة.","pauseAfter":0.6,"kind":"vocab","start":312.342,"end":319.278},{"speaker":"Lea","de":"Jetzt bist du dran. Sprich laut nach: der Vorteil, -e.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Vorteil, -e.","pauseAfter":1.8,"kind":"interactive","start":319.878,"end":324.39},{"speaker":"Samir","de":"Wort Nummer 8: der Nachteil, -e. Hör genau zu: der Nachteil, -e.","ar":"الكلمة رقم 8: عيب. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":326.19,"end":331.47},{"speaker":"Lea","de":"der Nachteil, -e bedeutet: Eine negative Seite. Ein Beispiel: Ein Nachteil sind falsche Informationen.","ar":"معنى der Nachteil, -e: عيب.","pauseAfter":0.6,"kind":"vocab","start":331.92,"end":339.624},{"speaker":"Samir","de":"Jetzt bist du dran. Sprich laut nach: der Nachteil, -e.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Nachteil, -e.","pauseAfter":1.8,"kind":"interactive","start":340.224,"end":344.4},{"speaker":"Lea","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":346.2,"end":352.728},{"speaker":"Samir","de":"Die Wörter waren: hochladen, teilen, der Vorteil, -e, der Nachteil, -e.","ar":"الكلمات كانت: يرفع ملفًا، يشارك، ميزة، عيب.","pauseAfter":1,"kind":"answer","start":355.728,"end":360.96},{"speaker":"Lea","de":"Wort Nummer 9: zuverlässig. Hör genau zu: zuverlässig.","ar":"الكلمة رقم 9: موثوق. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":361.96,"end":367.264},{"speaker":"Samir","de":"zuverlässig bedeutet: So, dass man sich darauf verlassen kann. Ein Beispiel: Diese Quelle ist zuverlässig.","ar":"معنى zuverlässig: موثوق.","pauseAfter":0.6,"kind":"vocab","start":367.714,"end":374.746},{"speaker":"Lea","de":"Jetzt bist du dran. Sprich laut nach: zuverlässig.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: zuverlässig.","pauseAfter":1.8,"kind":"interactive","start":375.346,"end":379.618},{"speaker":"Samir","de":"Wort Nummer 10: die Quelle, -n. Hör genau zu: die Quelle, -n.","ar":"الكلمة رقم 10: مصدر. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":381.418,"end":386.626},{"speaker":"Lea","de":"die Quelle, -n bedeutet: Der Ort, von dem eine Information kommt. Ein Beispiel: Prüfe immer die Quelle.","ar":"معنى die Quelle, -n: مصدر.","pauseAfter":0.6,"kind":"vocab","start":387.076,"end":395.428},{"speaker":"Samir","de":"Jetzt bist du dran. Sprich laut nach: die Quelle, -n.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Quelle, -n.","pauseAfter":1.8,"kind":"interactive","start":396.028,"end":400.228},{"speaker":"Samir","de":"Sehr gut. Wörter allein reichen aber nicht. Im Gespräch brauchen wir fertige Sätze und passende Reaktionen.","ar":"جيد جدًا. الكلمات وحدها لا تكفي؛ في الحوار نحتاج إلى جمل جاهزة وردود مناسبة.","pauseAfter":0.8,"kind":"section","start":402.028,"end":408.892},{"speaker":"Lea","de":"Situation 1, Vor- und Nachteile. Was könntest du sagen?","ar":"الموقف رقم 1. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":409.692,"end":414.564},{"speaker":"Samir","de":"Eine passende Formulierung ist: Ein großer Vorteil ist, dass …","ar":"تعبير مناسب هو: ميزة كبيرة هي إن ...","pauseAfter":0.7,"kind":"phrase","start":416.764,"end":420.796},{"speaker":"Lea","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Ein großer Vorteil ist, dass …","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":421.496,"end":427.064},{"speaker":"Samir","de":"Situation 2, Vor- und Nachteile. Was könntest du sagen?","ar":"الموقف رقم 2. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":429.264,"end":433.704},{"speaker":"Lea","de":"Eine passende Formulierung ist: Dagegen spricht, dass …","ar":"تعبير مناسب هو: اللي ضد الموضوع إن ...","pauseAfter":0.7,"kind":"phrase","start":435.904,"end":440.248},{"speaker":"Samir","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Dagegen spricht, dass …","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":440.948,"end":445.964},{"speaker":"Lea","de":"Situation 3, Vor- und Nachteile. Was könntest du sagen?","ar":"الموقف رقم 3. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":448.164,"end":453.06},{"speaker":"Samir","de":"Eine passende Formulierung ist: Einerseits ist es praktisch, andererseits kostet es viel Zeit.","ar":"تعبير مناسب هو: من ناحية هو عملي ومن ناحية تانية بياخد وقت.","pauseAfter":0.7,"kind":"phrase","start":455.26,"end":460.684},{"speaker":"Lea","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Einerseits ist es praktisch, andererseits kostet es viel Zeit.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":461.384,"end":468.464},{"speaker":"Samir","de":"Situation 4, Vor- und Nachteile. Was könntest du sagen?","ar":"الموقف رقم 4. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":470.664,"end":475.104},{"speaker":"Lea","de":"Eine passende Formulierung ist: Für mich überwiegen die Vorteile.","ar":"تعبير مناسب هو: بالنسبة لي المميزات أكتر.","pauseAfter":0.7,"kind":"phrase","start":477.304,"end":481.864},{"speaker":"Samir","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Für mich überwiegen die Vorteile.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":482.564,"end":487.412},{"speaker":"Lea","de":"Situation 5, Vergleichen. Was könntest du sagen?","ar":"الموقف رقم 5. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":489.612,"end":493.932},{"speaker":"Samir","de":"Eine passende Formulierung ist: Podcasts sind flexibler als Radio.","ar":"تعبير مناسب هو: البودكاست أكثر مرونة من الراديو.","pauseAfter":0.7,"kind":"phrase","start":496.132,"end":500.284},{"speaker":"Lea","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Podcasts sind flexibler als Radio.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":500.984,"end":506.912},{"speaker":"Samir","de":"Situation 6, Vergleichen. Was könntest du sagen?","ar":"الموقف رقم 6. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":509.112,"end":513.048},{"speaker":"Lea","de":"Eine passende Formulierung ist: Das Tablet ist genauso praktisch wie der Laptop.","ar":"تعبير مناسب هو: التابلت عملي زي اللابتوب.","pauseAfter":0.7,"kind":"phrase","start":515.248,"end":520.408},{"speaker":"Samir","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Das Tablet ist genauso praktisch wie der Laptop.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":521.108,"end":526.604},{"speaker":"Lea","de":"Jetzt kommt ein kurzer Hör- und Grammatikcheck. Antworte zuerst selbst. Danach hörst du die Lösung.","ar":"والآن اختبار قصير في الاستماع والقواعد. أجب أولًا بنفسك ثم استمع إلى الحل.","pauseAfter":0.8,"kind":"section","start":528.804,"end":536.028},{"speaker":"Lea","de":"Frage 1: Ein Laptop ist ___ als ein Handy.","ar":"السؤال رقم 1. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":536.828,"end":542.324},{"speaker":"Lea","de":"Die Möglichkeiten sind: A, groß. B, größer. C, am größten.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":542.824,"end":549.04},{"speaker":"Samir","de":"Die richtige Antwort ist B: größer. Komparativ: größer.","ar":"الإجابة الصحيحة: صيغة المقارنة: größer.","pauseAfter":1,"kind":"answer","start":552.24,"end":556.728},{"speaker":"Samir","de":"Frage 2: Diese App ist genauso praktisch ___ jene.","ar":"السؤال رقم 2. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":557.728,"end":562.48},{"speaker":"Samir","de":"Die Möglichkeiten sind: A, als. B, wie. C, dass.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":562.98,"end":568.356},{"speaker":"Lea","de":"Die richtige Antwort ist B: wie. Gleichheit: genauso … wie.","ar":"الإجابة الصحيحة: التساوي باستخدام wie.","pauseAfter":1,"kind":"answer","start":571.556,"end":576.788},{"speaker":"Lea","de":"Frage 3: Von allen Filmen ist dieser ___.","ar":"السؤال رقم 3. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":577.788,"end":582.996},{"speaker":"Lea","de":"Die Möglichkeiten sind: A, spannender. B, am spannendsten. C, so spannend.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":583.496,"end":590.408},{"speaker":"Samir","de":"Die richtige Antwort ist B: am spannendsten. Superlativ mit am.","ar":"الإجابة الصحيحة: التفضيل مع am.","pauseAfter":1,"kind":"answer","start":593.608,"end":598.312},{"speaker":"Samir","de":"Frage 4: Ich glaube, dass der Film gut ___.","ar":"السؤال رقم 4. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":599.312,"end":604.016},{"speaker":"Samir","de":"Die Möglichkeiten sind: A, ist. B, sein. C, war ist.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":604.516,"end":609.676},{"speaker":"Lea","de":"Die richtige Antwort ist A: ist. Im dass-Satz steht das Verb am Ende.","ar":"الإجابة الصحيحة: الفعل في آخر جملة dass.","pauseAfter":1,"kind":"answer","start":612.876,"end":618.084},{"speaker":"Samir","de":"Zum Abschluss: Nenne drei neue Wörter aus Kapitel 3 und bilde mit jedem Wort einen Satz.","ar":"في الختام: اذكر ثلاث كلمات جديدة من الدرس 3 وكوّن جملة بكل كلمة.","pauseAfter":4,"kind":"interactive","start":619.084,"end":624.172},{"speaker":"Lea","de":"Wenn das noch schwer ist, höre die Folge morgen noch einmal. Beim zweiten Hören wirst du deutlich mehr verstehen.","ar":"إذا كان الأمر ما زال صعبًا، فاستمع إلى الحلقة غدًا مرة أخرى. في المرة الثانية ستفهم أكثر بوضوح.","pauseAfter":0.7,"kind":"outro","start":628.172,"end":635.18},{"speaker":"Samir","de":"Danke fürs Zuhören. Das war Ein Abend ohne Handy. Bis zur nächsten Folge!","ar":"شكرًا على الاستماع. كانت هذه حلقة Ein Abend ohne Handy. إلى الحلقة القادمة!","pauseAfter":1,"kind":"outro","start":635.88,"end":641.04}],"people":[{"name":"Lea","gender":"female","age":25,"voice":"de-DE-SeraphinaMultilingualNeural"},{"name":"Samir","gender":"male","age":28,"voice":"de-DE-FlorianMultilingualNeural"}],"audio":"assets/podcasts/chapter-3.mp3?v=natural-dialogue-2","durationSeconds":642.1},{"chapter":4,"title":"Eine echte Überraschung","duration":"11 Min.","speakers":["Emma","Omar"],"intro":"Gefühle, Feste, Glückwünsche und Dank.","keywords":["überrascht","aufgeregt","gratulieren","dankbar","sich freuen"],"lines":[{"speaker":"Emma","de":"Willkommen zu Folge 4: Eine echte Überraschung. Ich bin Emma, 34 Jahre alt.","ar":"مرحبًا بكم في الحلقة 4: Eine echte Überraschung. أنا Emma وعمري 34 عامًا.","pauseAfter":0.5,"kind":"intro","start":0.0,"end":6.504},{"speaker":"Omar","de":"Und ich bin Omar, 36 Jahre alt. Heute sprechen wir über Gefühle, Feste, Glückwünsche, Dank.","ar":"وأنا Omar وعمري 36 عامًا. سنتحدث اليوم عن موضوعات الدرس.","pauseAfter":0.6,"kind":"intro","start":7.004,"end":14.756},{"speaker":"Emma","de":"Hör zuerst entspannt zu. Danach wiederholen wir wichtige Wörter und Redemittel, und am Ende gibt es Fragen für dich.","ar":"استمع أولًا بهدوء. بعد ذلك سنراجع كلمات وتعبيرات مهمة، وفي النهاية توجد أسئلة لك.","pauseAfter":0.7,"kind":"intro","start":15.356,"end":22.988},{"speaker":"Omar","de":"Du kannst jederzeit pausieren, laut antworten und anschließend mit unserer Lösung vergleichen. Los geht es!","ar":"يمكنك إيقاف الحلقة والإجابة بصوت عالٍ ثم مقارنة إجابتك بحلنا. لنبدأ!","pauseAfter":1,"kind":"intro","start":23.688,"end":30.96},{"speaker":"Emma","de":"Omar, du siehst heute so glücklich aus. Was ist passiert?","ar":"عمر، تبدو سعيدًا جدًا اليوم. ماذا حدث؟","pauseAfter":0.55,"kind":"scene","start":31.96,"end":36.472},{"speaker":"Omar","de":"Meine Freunde haben gestern eine Überraschungsparty für mich organisiert.","ar":"نظّم أصدقائي أمس حفلة مفاجئة من أجلي.","pauseAfter":0.55,"kind":"scene","start":37.022,"end":41.414},{"speaker":"Emma","de":"Hast du vorher wirklich nichts gewusst?","ar":"هل حقًا لم تكن تعرف شيئًا من قبل؟","pauseAfter":0.55,"kind":"scene","start":41.964,"end":44.652},{"speaker":"Omar","de":"Nein. Als ich die Tür geöffnet habe, haben alle laut gratuliert. Ich war total überrascht.","ar":"لا. عندما فتحت الباب هنأني الجميع بصوت عالٍ. كنت متفاجئًا تمامًا.","pauseAfter":0.55,"kind":"scene","start":45.202,"end":52.546},{"speaker":"Emma","de":"Welche Geschenke hast du bekommen?","ar":"ما الهدايا التي حصلت عليها؟","pauseAfter":0.55,"kind":"scene","start":53.096,"end":55.448},{"speaker":"Omar","de":"Ein Fotobuch, Konzertkarten und viele persönliche Karten. Über das Fotobuch habe ich mich besonders gefreut.","ar":"كتاب صور وتذاكر حفل وبطاقات شخصية كثيرة. فرحت بكتاب الصور بشكل خاص.","pauseAfter":0.55,"kind":"scene","start":55.998,"end":63.39},{"speaker":"Emma","de":"Das kann ich verstehen. Gemeinsame Erinnerungen sind oft schöner als teure Geschenke.","ar":"أستطيع فهم ذلك. الذكريات المشتركة غالبًا أجمل من الهدايا الغالية.","pauseAfter":0.55,"kind":"scene","start":63.94,"end":69.532},{"speaker":"Omar","de":"Genau. Ich bin meinen Freunden sehr dankbar und möchte mich noch einmal bei allen bedanken.","ar":"بالضبط. أنا ممتن جدًا لأصدقائي وأريد أن أشكر الجميع مرة أخرى.","pauseAfter":0.55,"kind":"scene","start":70.082,"end":76.13},{"speaker":"Emma","de":"Nach der Party sitzen Emma und Omar noch in der Küche und sprechen über den Abend.","ar":"بعد الحفلة يجلس إيما وعمر في المطبخ ويتحدثان عن الأمسية.","pauseAfter":0.28,"kind":"scene","start":76.68,"end":81.456},{"speaker":"Omar","de":"Ich war zuerst aufgeregt, weil plötzlich so viele Menschen im Zimmer standen.","ar":"كنت متوترًا أولًا لأن عددًا كبيرًا من الناس كان في الغرفة فجأة.","pauseAfter":0.28,"kind":"scene","start":81.736,"end":86.68},{"speaker":"Emma","de":"Aber nach ein paar Minuten hast du sehr glücklich ausgesehen.","ar":"لكنك بدوت سعيدًا جدًا بعد دقائق قليلة.","pauseAfter":0.28,"kind":"scene","start":86.96,"end":90.704},{"speaker":"Omar","de":"Ja, besonders als meine Schwester die alten Fotos gezeigt hat.","ar":"نعم، خصوصًا عندما عرضت أختي الصور القديمة.","pauseAfter":0.28,"kind":"scene","start":90.984,"end":95.208},{"speaker":"Emma","de":"Auf einem Foto warst du vielleicht sechs Jahre alt und sehr stolz.","ar":"في إحدى الصور كان عمرك نحو ست سنوات وكنت فخورًا جدًا.","pauseAfter":0.28,"kind":"scene","start":95.488,"end":99.448},{"speaker":"Omar","de":"Damals hatte ich gerade schwimmen gelernt. Daran erinnere ich mich noch gut.","ar":"كنت قد تعلمت السباحة وقتها وما زلت أتذكر ذلك جيدًا.","pauseAfter":0.28,"kind":"scene","start":99.728,"end":105.08},{"speaker":"Emma","de":"Deine Freunde haben sich wirklich viel Mühe mit der Feier gegeben.","ar":"بذل أصدقاؤك جهدًا كبيرًا فعلًا في الحفلة.","pauseAfter":0.28,"kind":"scene","start":105.36,"end":109.08},{"speaker":"Omar","de":"Ich möchte mich bei jedem persönlich bedanken und nicht nur eine Nachricht schicken.","ar":"أريد شكر كل شخص بصورة شخصية وليس برسالة فقط.","pauseAfter":0.28,"kind":"scene","start":109.36,"end":113.992},{"speaker":"Emma","de":"Du könntest morgen anrufen und sagen, worüber du dich besonders gefreut hast.","ar":"يمكنك الاتصال غدًا وذكر أكثر شيء أسعدك.","pauseAfter":0.28,"kind":"scene","start":114.272,"end":119.048},{"speaker":"Omar","de":"Gute Idee. Nur schade, dass mein Cousin nicht kommen konnte.","ar":"فكرة جيدة. من المؤسف فقط أن ابن عمي لم يستطع الحضور.","pauseAfter":0.28,"kind":"scene","start":119.328,"end":124.296},{"speaker":"Emma","de":"Er war bestimmt enttäuscht. Seine Zugverbindung ist ausgefallen.","ar":"كان محبطًا بالتأكيد. لقد أُلغيت رحلة قطاره.","pauseAfter":0.28,"kind":"scene","start":124.576,"end":129.304},{"speaker":"Omar","de":"Ich rufe ihn später an. Vielleicht feiern wir nächste Woche noch einmal klein.","ar":"سأتصل به لاحقًا. ربما نحتفل بشكل صغير الأسبوع القادم.","pauseAfter":0.28,"kind":"scene","start":129.584,"end":135.152},{"speaker":"Emma","de":"Dann kann er dir persönlich gratulieren und sein Geschenk mitbringen.","ar":"عندها يمكنه تهنئتك شخصيًا وإحضار هديته.","pauseAfter":0.28,"kind":"scene","start":135.432,"end":139.272},{"speaker":"Omar","de":"Eigentlich brauche ich kein weiteres Geschenk. Gemeinsame Zeit reicht mir.","ar":"في الحقيقة لا أحتاج هدية أخرى. يكفيني الوقت المشترك.","pauseAfter":0.28,"kind":"scene","start":139.552,"end":144.952},{"speaker":"Emma","de":"Das ist eine schöne Einstellung. Du klingst wirklich dankbar.","ar":"هذه طريقة تفكير جميلة. تبدو ممتنًا فعلًا.","pauseAfter":0.28,"kind":"scene","start":145.232,"end":149.48},{"speaker":"Omar","de":"Das bin ich auch. Dieser Abend bleibt eine besondere Erinnerung.","ar":"أنا كذلك فعلًا. ستبقى هذه الأمسية ذكرى مميزة.","pauseAfter":0.28,"kind":"scene","start":149.76,"end":154.56},{"speaker":"Emma","de":"Das war unsere erste Alltagsszene. Welche Wörter und Sätze hast du sofort verstanden?","ar":"كان هذا مشهدنا اليومي الأول. ما الكلمات والجمل التي فهمتها فورًا؟","pauseAfter":3.2,"kind":"interactive","start":154.84,"end":160.84},{"speaker":"Omar","de":"Denk kurz nach. Du musst nicht jedes Wort verstehen. Wichtig ist zuerst die Situation.","ar":"فكّر قليلًا. ليس ضروريًا أن تفهم كل كلمة؛ المهم أولًا هو فهم الموقف.","pauseAfter":2.4,"kind":"interactive","start":164.04,"end":171.048},{"speaker":"Emma","de":"Die Situation passt zu Kapitel 4. Jetzt sehen wir uns den Wortschatz genauer an.","ar":"الموقف مرتبط بالدرس 4. والآن سنراجع المفردات بدقة أكبر.","pauseAfter":0.8,"kind":"section","start":173.448,"end":179.112},{"speaker":"Emma","de":"Wort Nummer 1: das Gefühl, -e. Hör genau zu: das Gefühl, -e.","ar":"الكلمة رقم 1: إحساس / شعور. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":179.912,"end":184.952},{"speaker":"Omar","de":"das Gefühl, -e bedeutet: Eine innere Reaktion wie Freude oder Angst. Ein Beispiel: Ich kann dieses Gefühl schwer beschreiben.","ar":"معنى das Gefühl, -e: إحساس / شعور.","pauseAfter":0.6,"kind":"vocab","start":185.402,"end":193.802},{"speaker":"Emma","de":"Jetzt bist du dran. Sprich laut nach: das Gefühl, -e.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: das Gefühl, -e.","pauseAfter":1.8,"kind":"interactive","start":194.402,"end":198.866},{"speaker":"Omar","de":"Wort Nummer 2: sich freuen. Hör genau zu: sich freuen.","ar":"الكلمة رقم 2: يفرح / يتطلع. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":200.666,"end":205.73},{"speaker":"Emma","de":"sich freuen bedeutet: Glücklich sein oder etwas gern erwarten. Ein Beispiel: Ich freue mich auf das Fest.","ar":"معنى sich freuen: يفرح / يتطلع.","pauseAfter":0.6,"kind":"vocab","start":206.18,"end":213.692},{"speaker":"Omar","de":"Jetzt bist du dran. Sprich laut nach: sich freuen.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: sich freuen.","pauseAfter":1.8,"kind":"interactive","start":214.292,"end":218.852},{"speaker":"Emma","de":"Wort Nummer 3: sich ärgern. Hör genau zu: sich ärgern.","ar":"الكلمة رقم 3: يتضايق. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":220.652,"end":225.452},{"speaker":"Omar","de":"sich ärgern bedeutet: Wütend oder unzufrieden werden. Ein Beispiel: Er ärgert sich über die Verspätung.","ar":"معنى sich ärgern: يتضايق.","pauseAfter":0.6,"kind":"vocab","start":225.902,"end":233.15},{"speaker":"Emma","de":"Jetzt bist du dran. Sprich laut nach: sich ärgern.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: sich ärgern.","pauseAfter":1.8,"kind":"interactive","start":233.75,"end":237.782},{"speaker":"Omar","de":"Wort Nummer 4: sich wundern. Hör genau zu: sich wundern.","ar":"الكلمة رقم 4: يستغرب. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":239.582,"end":244.838},{"speaker":"Emma","de":"sich wundern bedeutet: Etwas überraschend finden. Ein Beispiel: Ich wundere mich über die Nachricht.","ar":"معنى sich wundern: يستغرب.","pauseAfter":0.6,"kind":"vocab","start":245.288,"end":252.176},{"speaker":"Omar","de":"Jetzt bist du dran. Sprich laut nach: sich wundern.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: sich wundern.","pauseAfter":1.8,"kind":"interactive","start":252.776,"end":257.48},{"speaker":"Emma","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":259.28,"end":265.808},{"speaker":"Omar","de":"Die Wörter waren: das Gefühl, -e, sich freuen, sich ärgern, sich wundern.","ar":"الكلمات كانت: إحساس / شعور، يفرح / يتطلع، يتضايق، يستغرب.","pauseAfter":1,"kind":"answer","start":268.808,"end":274.16},{"speaker":"Emma","de":"Wort Nummer 5: sich entspannen. Hör genau zu: sich entspannen.","ar":"الكلمة رقم 5: يسترخي. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":275.16,"end":280.272},{"speaker":"Omar","de":"sich entspannen bedeutet: Ruhig werden und Stress verlieren. Ein Beispiel: Am Wochenende entspanne ich mich.","ar":"معنى sich entspannen: يسترخي.","pauseAfter":0.6,"kind":"vocab","start":280.722,"end":287.97},{"speaker":"Emma","de":"Jetzt bist du dran. Sprich laut nach: sich entspannen.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: sich entspannen.","pauseAfter":1.8,"kind":"interactive","start":288.57,"end":292.842},{"speaker":"Omar","de":"Wort Nummer 6: aufgeregt. Hör genau zu: aufgeregt.","ar":"الكلمة رقم 6: متحمس ومتوتر. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":294.642,"end":299.634},{"speaker":"Emma","de":"aufgeregt bedeutet: Nervös und gespannt zugleich. Ein Beispiel: Vor der Feier war sie sehr aufgeregt.","ar":"معنى aufgeregt: متحمس ومتوتر.","pauseAfter":0.6,"kind":"vocab","start":300.084,"end":307.644},{"speaker":"Omar","de":"Jetzt bist du dran. Sprich laut nach: aufgeregt.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: aufgeregt.","pauseAfter":1.8,"kind":"interactive","start":308.244,"end":312.804},{"speaker":"Emma","de":"Wort Nummer 7: enttäuscht. Hör genau zu: enttäuscht.","ar":"الكلمة رقم 7: محبط. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":314.604,"end":319.284},{"speaker":"Omar","de":"enttäuscht bedeutet: Traurig, weil etwas nicht wie erwartet ist. Ein Beispiel: Er ist vom Ergebnis enttäuscht.","ar":"معنى enttäuscht: محبط.","pauseAfter":0.6,"kind":"vocab","start":319.734,"end":327.486},{"speaker":"Emma","de":"Jetzt bist du dran. Sprich laut nach: enttäuscht.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: enttäuscht.","pauseAfter":1.8,"kind":"interactive","start":328.086,"end":332.142},{"speaker":"Omar","de":"Wort Nummer 8: stolz. Hör genau zu: stolz.","ar":"الكلمة رقم 8: فخور. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":333.942,"end":338.574},{"speaker":"Emma","de":"stolz bedeutet: Sehr zufrieden mit einer Leistung. Ein Beispiel: Ihre Eltern sind stolz auf sie.","ar":"معنى stolz: فخور.","pauseAfter":0.6,"kind":"vocab","start":339.024,"end":345.696},{"speaker":"Omar","de":"Jetzt bist du dran. Sprich laut nach: stolz.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: stolz.","pauseAfter":1.8,"kind":"interactive","start":346.296,"end":350.688},{"speaker":"Emma","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":352.488,"end":359.016},{"speaker":"Omar","de":"Die Wörter waren: sich entspannen, aufgeregt, enttäuscht, stolz.","ar":"الكلمات كانت: يسترخي، متحمس ومتوتر، محبط، فخور.","pauseAfter":1,"kind":"answer","start":362.016,"end":366.864},{"speaker":"Emma","de":"Wort Nummer 9: die Feier, -n. Hör genau zu: die Feier, -n.","ar":"الكلمة رقم 9: احتفال. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":367.864,"end":373.144},{"speaker":"Omar","de":"die Feier, -n bedeutet: Ein Fest für einen besonderen Anlass. Ein Beispiel: Die Feier beginnt um sieben.","ar":"معنى die Feier, -n: احتفال.","pauseAfter":0.6,"kind":"vocab","start":373.594,"end":381.034},{"speaker":"Emma","de":"Jetzt bist du dran. Sprich laut nach: die Feier, -n.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Feier, -n.","pauseAfter":1.8,"kind":"interactive","start":381.634,"end":386.146},{"speaker":"Omar","de":"Wort Nummer 10: der Anlass, ⸚e. Hör genau zu: der Anlass, ⸚e.","ar":"الكلمة رقم 10: مناسبة / سبب. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":387.946,"end":393.13},{"speaker":"Emma","de":"der Anlass, ⸚e bedeutet: Der Grund für ein Fest oder Ereignis. Ein Beispiel: Was ist der Anlass für die Feier?","ar":"معنى der Anlass, ⸚e: مناسبة / سبب.","pauseAfter":0.6,"kind":"vocab","start":393.58,"end":402.1},{"speaker":"Omar","de":"Jetzt bist du dran. Sprich laut nach: der Anlass, ⸚e.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Anlass, ⸚e.","pauseAfter":1.8,"kind":"interactive","start":402.7,"end":407.788},{"speaker":"Omar","de":"Sehr gut. Wörter allein reichen aber nicht. Im Gespräch brauchen wir fertige Sätze und passende Reaktionen.","ar":"جيد جدًا. الكلمات وحدها لا تكفي؛ في الحوار نحتاج إلى جمل جاهزة وردود مناسبة.","pauseAfter":0.8,"kind":"section","start":409.588,"end":417.748},{"speaker":"Emma","de":"Situation 1, Gratulieren und danken. Was könntest du sagen?","ar":"الموقف رقم 1. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":418.548,"end":423.66},{"speaker":"Omar","de":"Eine passende Formulierung ist: Herzlichen Glückwunsch zum Geburtstag!","ar":"تعبير مناسب هو: كل سنة وأنت طيب!","pauseAfter":0.7,"kind":"phrase","start":425.86,"end":430.444},{"speaker":"Emma","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Herzlichen Glückwunsch zum Geburtstag!","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":431.144,"end":437.144},{"speaker":"Omar","de":"Situation 2, Gratulieren und danken. Was könntest du sagen?","ar":"الموقف رقم 2. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":439.344,"end":444.792},{"speaker":"Emma","de":"Eine passende Formulierung ist: Ich gratuliere dir zur bestandenen Prüfung.","ar":"تعبير مناسب هو: أهنئك على نجاحك في الامتحان.","pauseAfter":0.7,"kind":"phrase","start":446.992,"end":451.912},{"speaker":"Omar","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Ich gratuliere dir zur bestandenen Prüfung.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":452.612,"end":458.564},{"speaker":"Emma","de":"Situation 3, Gratulieren und danken. Was könntest du sagen?","ar":"الموقف رقم 3. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":460.764,"end":465.876},{"speaker":"Omar","de":"Eine passende Formulierung ist: Vielen Dank, das ist wirklich lieb von dir.","ar":"تعبير مناسب هو: شكرًا جدًا، ده لطف منك.","pauseAfter":0.7,"kind":"phrase","start":468.076,"end":473.044},{"speaker":"Emma","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Vielen Dank, das ist wirklich lieb von dir.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":473.744,"end":479.648},{"speaker":"Omar","de":"Situation 4, Gratulieren und danken. Was könntest du sagen?","ar":"الموقف رقم 4. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":481.848,"end":487.344},{"speaker":"Emma","de":"Eine passende Formulierung ist: Ich habe mich sehr über dein Geschenk gefreut.","ar":"تعبير مناسب هو: فرحت جدًا بهديتك.","pauseAfter":0.7,"kind":"phrase","start":489.544,"end":494.272},{"speaker":"Omar","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Ich habe mich sehr über dein Geschenk gefreut.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":494.972,"end":500.684},{"speaker":"Emma","de":"Situation 5, Auf Nachrichten reagieren. Was könntest du sagen?","ar":"الموقف رقم 5. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":502.884,"end":508.044},{"speaker":"Omar","de":"Eine passende Formulierung ist: Das freut mich wirklich für dich!","ar":"تعبير مناسب هو: أنا فرحان لك جدًا!","pauseAfter":0.7,"kind":"phrase","start":510.244,"end":514.468},{"speaker":"Emma","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Das freut mich wirklich für dich!","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":515.168,"end":520.496},{"speaker":"Omar","de":"Situation 6, Auf Nachrichten reagieren. Was könntest du sagen?","ar":"الموقف رقم 6. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":522.696,"end":528.288},{"speaker":"Emma","de":"Eine passende Formulierung ist: Wie schön! Erzähl doch mal.","ar":"تعبير مناسب هو: جميل جدًا! احكي بقى.","pauseAfter":0.7,"kind":"phrase","start":530.488,"end":535.072},{"speaker":"Omar","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Wie schön! Erzähl doch mal.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":535.772,"end":541.868},{"speaker":"Emma","de":"Jetzt kommt ein kurzer Hör- und Grammatikcheck. Antworte zuerst selbst. Danach hörst du die Lösung.","ar":"والآن اختبار قصير في الاستماع والقواعد. أجب أولًا بنفسك ثم استمع إلى الحل.","pauseAfter":0.8,"kind":"section","start":544.068,"end":551.292},{"speaker":"Emma","de":"Frage 1: Wenn ich traurig ___, spreche ich mit Freunden.","ar":"السؤال رقم 1. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":552.092,"end":558.404},{"speaker":"Emma","de":"Die Möglichkeiten sind: A, bin. B, bist. C, sein.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":558.904,"end":564.256},{"speaker":"Omar","de":"Die richtige Antwort ist A: bin. Das Verb steht am Ende des wenn-Satzes.","ar":"الإجابة الصحيحة: الفعل في آخر جملة wenn.","pauseAfter":1,"kind":"answer","start":567.456,"end":572.856},{"speaker":"Omar","de":"Frage 2: Ich freue ___ auf die Feier.","ar":"السؤال رقم 2. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":573.856,"end":578.32},{"speaker":"Omar","de":"Die Möglichkeiten sind: A, mich. B, mir. C, sich.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":578.82,"end":585.108},{"speaker":"Emma","de":"Die richtige Antwort ist A: mich. ich → mich.","ar":"الإجابة الصحيحة: مع ich نستخدم mich.","pauseAfter":1,"kind":"answer","start":588.308,"end":591.98},{"speaker":"Emma","de":"Frage 3: Wir treffen ___ um acht Uhr.","ar":"السؤال رقم 3. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":592.98,"end":597.828},{"speaker":"Emma","de":"Die Möglichkeiten sind: A, euch. B, uns. C, sich.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":598.328,"end":603.728},{"speaker":"Omar","de":"Die richtige Antwort ist B: uns. wir → uns.","ar":"الإجابة الصحيحة: مع wir نستخدم uns.","pauseAfter":1,"kind":"answer","start":606.928,"end":611.152},{"speaker":"Omar","de":"Frage 4: Sie bedankt sich ___ das Geschenk.","ar":"السؤال رقم 4. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":612.152,"end":616.784},{"speaker":"Omar","de":"Die Möglichkeiten sind: A, auf. B, für. C, über.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":617.284,"end":623.548},{"speaker":"Emma","de":"Die richtige Antwort ist B: für. sich bedanken für.","ar":"الإجابة الصحيحة: يشكر على = sich bedanken für.","pauseAfter":1,"kind":"answer","start":626.748,"end":631.26},{"speaker":"Omar","de":"Zum Abschluss: Nenne drei neue Wörter aus Kapitel 4 und bilde mit jedem Wort einen Satz.","ar":"في الختام: اذكر ثلاث كلمات جديدة من الدرس 4 وكوّن جملة بكل كلمة.","pauseAfter":4,"kind":"interactive","start":632.26,"end":637.804},{"speaker":"Emma","de":"Wenn das noch schwer ist, höre die Folge morgen noch einmal. Beim zweiten Hören wirst du deutlich mehr verstehen.","ar":"إذا كان الأمر ما زال صعبًا، فاستمع إلى الحلقة غدًا مرة أخرى. في المرة الثانية ستفهم أكثر بوضوح.","pauseAfter":0.7,"kind":"outro","start":641.804,"end":648.812},{"speaker":"Omar","de":"Danke fürs Zuhören. Das war Eine echte Überraschung. Bis zur nächsten Folge!","ar":"شكرًا على الاستماع. كانت هذه حلقة Eine echte Überraschung. إلى الحلقة القادمة!","pauseAfter":1,"kind":"outro","start":649.512,"end":656.04}],"people":[{"name":"Emma","gender":"female","age":34,"voice":"de-DE-SeraphinaMultilingualNeural"},{"name":"Omar","gender":"male","age":36,"voice":"de-DE-ConradNeural"}],"audio":"assets/podcasts/chapter-4.mp3?v=natural-dialogue-2","durationSeconds":657.1},{"chapter":5,"title":"Ein Termin in der Stadt","duration":"11 Min.","speakers":["Lina","Paul"],"intro":"Stadt, Bank, Behörde und höfliche Bitten.","keywords":["Bürgeramt","Formular","Konto","Termin","Könnten Sie"],"lines":[{"speaker":"Lina","de":"Willkommen zu Folge 5: Ein Termin in der Stadt. Ich bin Lina, 30 Jahre alt.","ar":"مرحبًا بكم في الحلقة 5: Ein Termin in der Stadt. أنا Lina وعمري 30 عامًا.","pauseAfter":0.5,"kind":"intro","start":0.0,"end":6.288},{"speaker":"Paul","de":"Und ich bin Paul, 47 Jahre alt. Heute sprechen wir über Stadt, Bewerbung, Bank, Behörde, höfliche Bitten.","ar":"وأنا Paul وعمري 47 عامًا. سنتحدث اليوم عن موضوعات الدرس.","pauseAfter":0.6,"kind":"intro","start":6.788,"end":14.756},{"speaker":"Lina","de":"Hör zuerst entspannt zu. Danach wiederholen wir wichtige Wörter und Redemittel, und am Ende gibt es Fragen für dich.","ar":"استمع أولًا بهدوء. بعد ذلك سنراجع كلمات وتعبيرات مهمة، وفي النهاية توجد أسئلة لك.","pauseAfter":0.7,"kind":"intro","start":15.356,"end":22.988},{"speaker":"Paul","de":"Du kannst jederzeit pausieren, laut antworten und anschließend mit unserer Lösung vergleichen. Los geht es!","ar":"يمكنك إيقاف الحلقة والإجابة بصوت عالٍ ثم مقارنة إجابتك بحلنا. لنبدأ!","pauseAfter":1,"kind":"intro","start":23.688,"end":29.928},{"speaker":"Lina","de":"Guten Morgen. Könnten Sie mir sagen, wo das Bürgeramt ist?","ar":"صباح الخير. هل يمكن أن تخبرني أين مكتب خدمات المواطنين؟","pauseAfter":0.55,"kind":"scene","start":30.928,"end":35.176},{"speaker":"Paul","de":"Natürlich. Gehen Sie geradeaus und biegen Sie an der Apotheke rechts ab.","ar":"بالطبع. اذهبي إلى الأمام ثم انعطفي يمينًا عند الصيدلية.","pauseAfter":0.55,"kind":"scene","start":35.726,"end":40.334},{"speaker":"Lina","de":"Vielen Dank. Ich muss dort meine neue Adresse anmelden.","ar":"شكرًا جزيلًا. يجب أن أسجل عنواني الجديد هناك.","pauseAfter":0.55,"kind":"scene","start":40.884,"end":44.988},{"speaker":"Paul","de":"Haben Sie vorher einen Termin vereinbart? Ohne Termin muss man oft lange warten.","ar":"هل حجزت موعدًا مسبقًا؟ من دون موعد يضطر المرء غالبًا للانتظار طويلًا.","pauseAfter":0.55,"kind":"scene","start":45.538,"end":50.53},{"speaker":"Lina","de":"Ja, und das Formular habe ich schon online ausgefüllt.","ar":"نعم، وقد ملأت الاستمارة بالفعل عبر الإنترنت.","pauseAfter":0.55,"kind":"scene","start":51.08,"end":54.776},{"speaker":"Paul","de":"Sehr gut. Brauchen Sie danach noch etwas in der Stadt?","ar":"جيد جدًا. هل تحتاجين إلى شيء آخر في المدينة بعد ذلك؟","pauseAfter":0.55,"kind":"scene","start":55.326,"end":58.974},{"speaker":"Lina","de":"Ich möchte bei der Bank ein Konto eröffnen. Würden Sie mir bitte eine Bank in der Nähe empfehlen?","ar":"أريد فتح حساب في البنك. هل تتفضل بترشيح بنك قريب لي؟","pauseAfter":0.55,"kind":"scene","start":59.524,"end":65.524},{"speaker":"Paul","de":"Am Marktplatz gibt es eine Filiale. Sie ist direkt gegenüber vom Rathaus.","ar":"توجد فرع في ساحة السوق. وهو مباشرة مقابل مبنى البلدية.","pauseAfter":0.55,"kind":"scene","start":66.074,"end":70.898},{"speaker":"Lina","de":"Nach dem Termin im Bürgeramt geht Lina zur Bank am Marktplatz.","ar":"بعد موعد مكتب المواطنين تذهب لينا إلى البنك في ساحة السوق.","pauseAfter":0.28,"kind":"scene","start":71.448,"end":75.768},{"speaker":"Paul","de":"Guten Tag. Was kann ich für Sie tun?","ar":"مرحبًا. كيف يمكنني مساعدتك؟","pauseAfter":0.28,"kind":"scene","start":76.048,"end":78.88},{"speaker":"Lina","de":"Ich möchte gern ein Konto eröffnen. Welche Unterlagen brauche ich dafür?","ar":"أريد فتح حساب. ما المستندات المطلوبة؟","pauseAfter":0.28,"kind":"scene","start":79.16,"end":84.32},{"speaker":"Paul","de":"Wir brauchen Ihren Ausweis, Ihre Adresse und dieses ausgefüllte Formular.","ar":"نحتاج بطاقة هويتك وعنوانك وهذه الاستمارة بعد ملئها.","pauseAfter":0.28,"kind":"scene","start":84.6,"end":88.992},{"speaker":"Lina","de":"Könnten Sie mir bitte erklären, wo ich unterschreiben muss?","ar":"هل يمكنك توضيح مكان التوقيع من فضلك؟","pauseAfter":0.28,"kind":"scene","start":89.272,"end":92.848},{"speaker":"Paul","de":"Natürlich. Unterschreiben Sie unten rechts und tragen Sie hier Ihre Telefonnummer ein.","ar":"بالطبع. وقّعي أسفل اليمين واكتبي رقم هاتفك هنا.","pauseAfter":0.28,"kind":"scene","start":93.128,"end":98.144},{"speaker":"Lina","de":"Kann ich mit dem Konto später auch online Geld überweisen?","ar":"هل يمكنني تحويل المال عبر الإنترنت بهذا الحساب لاحقًا؟","pauseAfter":0.28,"kind":"scene","start":98.424,"end":102.144},{"speaker":"Paul","de":"Ja. Die Zugangsdaten bekommen Sie in den nächsten Tagen per Post.","ar":"نعم. ستصلك بيانات الدخول بالبريد خلال الأيام القادمة.","pauseAfter":0.28,"kind":"scene","start":102.424,"end":106.6},{"speaker":"Lina","de":"Ich bin erst vor einer Woche in dieses Viertel gezogen.","ar":"انتقلت إلى هذا الحي منذ أسبوع واحد فقط.","pauseAfter":0.28,"kind":"scene","start":106.88,"end":110.288},{"speaker":"Paul","de":"Dann kennen Sie die Innenstadt wahrscheinlich noch nicht so gut.","ar":"إذن غالبًا لا تعرفين وسط المدينة جيدًا بعد.","pauseAfter":0.28,"kind":"scene","start":110.568,"end":113.616},{"speaker":"Lina","de":"Stimmt. Ich muss heute außerdem noch eine Bewerbung abschicken.","ar":"صحيح. ويجب عليّ أيضًا إرسال طلب وظيفة اليوم.","pauseAfter":0.28,"kind":"scene","start":113.896,"end":118.096},{"speaker":"Paul","de":"In der Bibliothek gegenüber können Sie kostenlos einen Computer benutzen.","ar":"يمكنك استخدام كمبيوتر مجانًا في المكتبة المقابلة.","pauseAfter":0.28,"kind":"scene","start":118.376,"end":122.36},{"speaker":"Lina","de":"Das ist praktisch. Morgen habe ich sogar schon ein Vorstellungsgespräch.","ar":"هذا عملي. لدي غدًا بالفعل مقابلة عمل.","pauseAfter":0.28,"kind":"scene","start":122.64,"end":127.512},{"speaker":"Paul","de":"Dann wünsche ich Ihnen viel Erfolg. Zu welcher Stelle haben Sie sich beworben?","ar":"أتمنى لك النجاح. لأي وظيفة قدمتِ؟","pauseAfter":0.28,"kind":"scene","start":127.792,"end":132.28},{"speaker":"Lina","de":"Für eine Stelle im Kundenservice. Dafür habe ich bereits Erfahrung.","ar":"لوظيفة في خدمة العملاء، ولدي خبرة بالفعل في هذا المجال.","pauseAfter":0.28,"kind":"scene","start":132.56,"end":137.336},{"speaker":"Paul","de":"Sehr gut. Das Konto ist gleich eröffnet, dann können Sie alles Weitere erledigen.","ar":"جيد جدًا. سيفتح الحساب حالًا ثم يمكنك إنجاز بقية الأمور.","pauseAfter":0.28,"kind":"scene","start":137.616,"end":142.872},{"speaker":"Lina","de":"Das war unsere erste Alltagsszene. Welche Wörter und Sätze hast du sofort verstanden?","ar":"كان هذا مشهدنا اليومي الأول. ما الكلمات والجمل التي فهمتها فورًا؟","pauseAfter":3.2,"kind":"interactive","start":143.152,"end":149.152},{"speaker":"Paul","de":"Denk kurz nach. Du musst nicht jedes Wort verstehen. Wichtig ist zuerst die Situation.","ar":"فكّر قليلًا. ليس ضروريًا أن تفهم كل كلمة؛ المهم أولًا هو فهم الموقف.","pauseAfter":2.4,"kind":"interactive","start":152.352,"end":158.232},{"speaker":"Lina","de":"Die Situation passt zu Kapitel 5. Jetzt sehen wir uns den Wortschatz genauer an.","ar":"الموقف مرتبط بالدرس 5. والآن سنراجع المفردات بدقة أكبر.","pauseAfter":0.8,"kind":"section","start":160.632,"end":166.344},{"speaker":"Lina","de":"Wort Nummer 1: die Innenstadt, ⸚e. Hör genau zu: die Innenstadt, ⸚e.","ar":"الكلمة رقم 1: وسط المدينة. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":167.144,"end":172.688},{"speaker":"Paul","de":"die Innenstadt, ⸚e bedeutet: Der zentrale Teil einer Stadt. Ein Beispiel: In der Innenstadt gibt es viele Geschäfte.","ar":"معنى die Innenstadt, ⸚e: وسط المدينة.","pauseAfter":0.6,"kind":"vocab","start":173.138,"end":180.698},{"speaker":"Lina","de":"Jetzt bist du dran. Sprich laut nach: die Innenstadt, ⸚e.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Innenstadt, ⸚e.","pauseAfter":1.8,"kind":"interactive","start":181.298,"end":186.122},{"speaker":"Paul","de":"Wort Nummer 2: das Viertel, -. Hör genau zu: das Viertel, -.","ar":"الكلمة رقم 2: حي. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":187.922,"end":193.394},{"speaker":"Lina","de":"das Viertel, - bedeutet: Ein Teil einer Stadt. Ein Beispiel: Wir wohnen in einem ruhigen Viertel.","ar":"معنى das Viertel, -: حي.","pauseAfter":0.6,"kind":"vocab","start":193.844,"end":201.02},{"speaker":"Paul","de":"Jetzt bist du dran. Sprich laut nach: das Viertel, -.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: das Viertel, -.","pauseAfter":1.8,"kind":"interactive","start":201.62,"end":205.748},{"speaker":"Lina","de":"Wort Nummer 3: die Behörde, -n. Hör genau zu: die Behörde, -n.","ar":"الكلمة رقم 3: مصلحة حكومية. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":207.548,"end":212.732},{"speaker":"Paul","de":"die Behörde, -n bedeutet: Eine staatliche Stelle für offizielle Aufgaben. Ein Beispiel: Ich habe morgen einen Termin bei der Behörde.","ar":"معنى die Behörde, -n: مصلحة حكومية.","pauseAfter":0.6,"kind":"vocab","start":213.182,"end":221.414},{"speaker":"Lina","de":"Jetzt bist du dran. Sprich laut nach: die Behörde, -n.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Behörde, -n.","pauseAfter":1.8,"kind":"interactive","start":222.014,"end":226.622},{"speaker":"Paul","de":"Wort Nummer 4: das Formular, -e. Hör genau zu: das Formular, -e.","ar":"الكلمة رقم 4: استمارة. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":228.422,"end":233.966},{"speaker":"Lina","de":"das Formular, -e bedeutet: Ein Dokument mit Feldern zum Ausfüllen. Ein Beispiel: Bitte füllen Sie das Formular aus.","ar":"معنى das Formular, -e: استمارة.","pauseAfter":0.6,"kind":"vocab","start":234.416,"end":242.888},{"speaker":"Paul","de":"Jetzt bist du dran. Sprich laut nach: das Formular, -e.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: das Formular, -e.","pauseAfter":1.8,"kind":"interactive","start":243.488,"end":247.904},{"speaker":"Lina","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":249.704,"end":256.232},{"speaker":"Paul","de":"Die Wörter waren: die Innenstadt, ⸚e, das Viertel, -, die Behörde, -n, das Formular, -e.","ar":"الكلمات كانت: وسط المدينة، حي، مصلحة حكومية، استمارة.","pauseAfter":1,"kind":"answer","start":259.232,"end":265.64},{"speaker":"Lina","de":"Wort Nummer 5: der Ausweis, -e. Hör genau zu: der Ausweis, -e.","ar":"الكلمة رقم 5: بطاقة هوية. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":266.64,"end":272.28},{"speaker":"Paul","de":"der Ausweis, -e bedeutet: Ein offizielles Dokument mit Foto. Ein Beispiel: Bringen Sie Ihren Ausweis mit.","ar":"معنى der Ausweis, -e: بطاقة هوية.","pauseAfter":0.6,"kind":"vocab","start":272.73,"end":279.954},{"speaker":"Lina","de":"Jetzt bist du dran. Sprich laut nach: der Ausweis, -e.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Ausweis, -e.","pauseAfter":1.8,"kind":"interactive","start":280.554,"end":285.186},{"speaker":"Paul","de":"Wort Nummer 6: beantragen. Hör genau zu: beantragen.","ar":"الكلمة رقم 6: يقدّم طلبًا رسميًا. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":286.986,"end":291.834},{"speaker":"Lina","de":"beantragen bedeutet: Offiziell um ein Dokument bitten. Ein Beispiel: Sie möchte einen neuen Ausweis beantragen.","ar":"معنى beantragen: يقدّم طلبًا رسميًا.","pauseAfter":0.6,"kind":"vocab","start":292.284,"end":299.94},{"speaker":"Paul","de":"Jetzt bist du dran. Sprich laut nach: beantragen.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: beantragen.","pauseAfter":1.8,"kind":"interactive","start":300.54,"end":304.332},{"speaker":"Lina","de":"Wort Nummer 7: das Konto, Konten. Hör genau zu: das Konto, Konten.","ar":"الكلمة رقم 7: حساب بنكي. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":306.132,"end":312.516},{"speaker":"Paul","de":"das Konto, Konten bedeutet: Ein Platz bei einer Bank für Geld. Ein Beispiel: Ich möchte ein Konto eröffnen.","ar":"معنى das Konto, Konten: حساب بنكي.","pauseAfter":0.6,"kind":"vocab","start":312.966,"end":319.95},{"speaker":"Lina","de":"Jetzt bist du dran. Sprich laut nach: das Konto, Konten.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: das Konto, Konten.","pauseAfter":1.8,"kind":"interactive","start":320.55,"end":325.422},{"speaker":"Paul","de":"Wort Nummer 8: überweisen. Hör genau zu: überweisen.","ar":"الكلمة رقم 8: يحوّل مالًا. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":327.222,"end":331.878},{"speaker":"Lina","de":"überweisen bedeutet: Geld auf ein anderes Konto schicken. Ein Beispiel: Ich überweise die Miete jeden Monat.","ar":"معنى überweisen: يحوّل مالًا.","pauseAfter":0.6,"kind":"vocab","start":332.328,"end":340.272},{"speaker":"Paul","de":"Jetzt bist du dran. Sprich laut nach: überweisen.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: überweisen.","pauseAfter":1.8,"kind":"interactive","start":340.872,"end":344.592},{"speaker":"Lina","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":346.392,"end":352.92},{"speaker":"Paul","de":"Die Wörter waren: der Ausweis, -e, beantragen, das Konto, Konten, überweisen.","ar":"الكلمات كانت: بطاقة هوية، يقدّم طلبًا رسميًا، حساب بنكي، يحوّل مالًا.","pauseAfter":1,"kind":"answer","start":355.92,"end":361.824},{"speaker":"Lina","de":"Wort Nummer 9: die Bewerbung, -en. Hör genau zu: die Bewerbung, -en.","ar":"الكلمة رقم 9: طلب توظيف. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":362.824,"end":368.944},{"speaker":"Paul","de":"die Bewerbung, -en bedeutet: Unterlagen und Anfrage für eine Arbeitsstelle. Ein Beispiel: Er schickt heute seine Bewerbung.","ar":"معنى die Bewerbung, -en: طلب توظيف.","pauseAfter":0.6,"kind":"vocab","start":369.394,"end":377.194},{"speaker":"Lina","de":"Jetzt bist du dran. Sprich laut nach: die Bewerbung, -en.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Bewerbung, -en.","pauseAfter":1.8,"kind":"interactive","start":377.794,"end":382.378},{"speaker":"Paul","de":"Wort Nummer 10: das Vorstellungsgespräch, -e. Hör genau zu: das Vorstellungsgespräch, -e.","ar":"الكلمة رقم 10: مقابلة عمل. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":384.178,"end":390.994},{"speaker":"Lina","de":"das Vorstellungsgespräch, -e bedeutet: Ein Gespräch vor einer möglichen Einstellung. Ein Beispiel: Das Vorstellungsgespräch dauert eine Stunde.","ar":"معنى das Vorstellungsgespräch, -e: مقابلة عمل.","pauseAfter":0.6,"kind":"vocab","start":391.444,"end":401.476},{"speaker":"Paul","de":"Jetzt bist du dran. Sprich laut nach: das Vorstellungsgespräch, -e.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: das Vorstellungsgespräch, -e.","pauseAfter":1.8,"kind":"interactive","start":402.076,"end":407.068},{"speaker":"Paul","de":"Sehr gut. Wörter allein reichen aber nicht. Im Gespräch brauchen wir fertige Sätze und passende Reaktionen.","ar":"جيد جدًا. الكلمات وحدها لا تكفي؛ في الحوار نحتاج إلى جمل جاهزة وردود مناسبة.","pauseAfter":0.8,"kind":"section","start":408.868,"end":415.924},{"speaker":"Lina","de":"Situation 1, Im Vorstellungsgespräch. Was könntest du sagen?","ar":"الموقف رقم 1. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":416.724,"end":421.764},{"speaker":"Paul","de":"Eine passende Formulierung ist: Warum interessieren Sie sich für diese Stelle?","ar":"تعبير مناسب هو: ليه مهتم بالوظيفة دي؟","pauseAfter":0.7,"kind":"phrase","start":423.964,"end":428.38},{"speaker":"Lina","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Warum interessieren Sie sich für diese Stelle?","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":429.08,"end":435.008},{"speaker":"Paul","de":"Situation 2, Im Vorstellungsgespräch. Was könntest du sagen?","ar":"الموقف رقم 2. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":437.208,"end":441.936},{"speaker":"Lina","de":"Eine passende Formulierung ist: Ich habe bereits Erfahrung im Bereich …","ar":"تعبير مناسب هو: عندي خبرة بالفعل في مجال ...","pauseAfter":0.7,"kind":"phrase","start":444.136,"end":448.672},{"speaker":"Paul","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Ich habe bereits Erfahrung im Bereich …","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":449.372,"end":454.82},{"speaker":"Lina","de":"Situation 3, Im Vorstellungsgespräch. Was könntest du sagen?","ar":"الموقف رقم 3. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":457.02,"end":462.06},{"speaker":"Paul","de":"Eine passende Formulierung ist: Zu meinen Stärken gehören …","ar":"تعبير مناسب هو: من نقاط قوتي ...","pauseAfter":0.7,"kind":"phrase","start":464.26,"end":468.004},{"speaker":"Lina","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Zu meinen Stärken gehören …","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":468.704,"end":474.008},{"speaker":"Paul","de":"Situation 4, Im Vorstellungsgespräch. Was könntest du sagen?","ar":"الموقف رقم 4. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":476.208,"end":480.84},{"speaker":"Lina","de":"Eine passende Formulierung ist: Ab wann könnten Sie bei uns anfangen?","ar":"تعبير مناسب هو: تقدر تبدأ عندنا من إمتى؟","pauseAfter":0.7,"kind":"phrase","start":483.04,"end":487.552},{"speaker":"Paul","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Ab wann könnten Sie bei uns anfangen?","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":488.252,"end":493.46},{"speaker":"Lina","de":"Situation 5, Bei Bank und Behörde. Was könntest du sagen?","ar":"الموقف رقم 5. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":495.66,"end":500.676},{"speaker":"Paul","de":"Eine passende Formulierung ist: Ich möchte gern ein Konto eröffnen.","ar":"تعبير مناسب هو: أحب أفتح حساب.","pauseAfter":0.7,"kind":"phrase","start":502.876,"end":506.932},{"speaker":"Lina","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Ich möchte gern ein Konto eröffnen.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":507.632,"end":513.368},{"speaker":"Paul","de":"Situation 6, Bei Bank und Behörde. Was könntest du sagen?","ar":"الموقف رقم 6. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":515.568,"end":520.224},{"speaker":"Lina","de":"Eine passende Formulierung ist: Welche Unterlagen brauche ich dafür?","ar":"تعبير مناسب هو: محتاج أنهي أوراق لكده؟","pauseAfter":0.7,"kind":"phrase","start":522.424,"end":526.84},{"speaker":"Paul","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Welche Unterlagen brauche ich dafür?","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":527.54,"end":532.676},{"speaker":"Lina","de":"Jetzt kommt ein kurzer Hör- und Grammatikcheck. Antworte zuerst selbst. Danach hörst du die Lösung.","ar":"والآن اختبار قصير في الاستماع والقواعد. أجب أولًا بنفسك ثم استمع إلى الحل.","pauseAfter":0.8,"kind":"section","start":534.876,"end":542.1},{"speaker":"Lina","de":"Frage 1: Ich sehe den ___ Park.","ar":"السؤال رقم 1. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":542.9,"end":547.436},{"speaker":"Lina","de":"Die Möglichkeiten sind: A, große. B, großen. C, großes.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":547.936,"end":554.176},{"speaker":"Paul","de":"Die richtige Antwort ist B: großen. Akkusativ maskulin: den großen Park.","ar":"الإجابة الصحيحة: مذكر Akkusativ: großen.","pauseAfter":1,"kind":"answer","start":557.376,"end":562.824},{"speaker":"Paul","de":"Frage 2: Wir besuchen die ___ Behörde.","ar":"السؤال رقم 2. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":563.824,"end":568.384},{"speaker":"Paul","de":"Die Möglichkeiten sind: A, neue. B, neuen. C, neuer.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":568.884,"end":574.308},{"speaker":"Lina","de":"Die richtige Antwort ist A: neue. Akkusativ feminin: die neue Behörde.","ar":"الإجابة الصحيحة: مؤنث Akkusativ: neue.","pauseAfter":1,"kind":"answer","start":577.508,"end":583.34},{"speaker":"Lina","de":"Frage 3: Ich komme mit ___ Ausweis.","ar":"السؤال رقم 3. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":584.34,"end":589.308},{"speaker":"Lina","de":"Die Möglichkeiten sind: A, den neuen. B, dem neuen. C, der neue.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":589.808,"end":595.952},{"speaker":"Paul","de":"Die richtige Antwort ist B: dem neuen. mit + Dativ: dem neuen.","ar":"الإجابة الصحيحة: mit معها Dativ.","pauseAfter":1,"kind":"answer","start":599.152,"end":604.24},{"speaker":"Paul","de":"Frage 4: Ohne ___ Formular geht es nicht.","ar":"السؤال رقم 4. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":605.24,"end":609.728},{"speaker":"Paul","de":"Die Möglichkeiten sind: A, das richtige. B, dem richtigen. C, der richtigen.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":610.228,"end":616.9},{"speaker":"Lina","de":"Die richtige Antwort ist A: das richtige. ohne + Akkusativ: das richtige.","ar":"الإجابة الصحيحة: ohne معها Akkusativ.","pauseAfter":1,"kind":"answer","start":620.1,"end":626.46},{"speaker":"Paul","de":"Zum Abschluss: Nenne drei neue Wörter aus Kapitel 5 und bilde mit jedem Wort einen Satz.","ar":"في الختام: اذكر ثلاث كلمات جديدة من الدرس 5 وكوّن جملة بكل كلمة.","pauseAfter":4,"kind":"interactive","start":627.46,"end":632.668},{"speaker":"Lina","de":"Wenn das noch schwer ist, höre die Folge morgen noch einmal. Beim zweiten Hören wirst du deutlich mehr verstehen.","ar":"إذا كان الأمر ما زال صعبًا، فاستمع إلى الحلقة غدًا مرة أخرى. في المرة الثانية ستفهم أكثر بوضوح.","pauseAfter":0.7,"kind":"outro","start":636.668,"end":643.676},{"speaker":"Paul","de":"Danke fürs Zuhören. Das war Ein Termin in der Stadt. Bis zur nächsten Folge!","ar":"شكرًا على الاستماع. كانت هذه حلقة Ein Termin in der Stadt. إلى الحلقة القادمة!","pauseAfter":1,"kind":"outro","start":644.376,"end":649.8}],"people":[{"name":"Lina","gender":"female","age":30,"voice":"de-DE-SeraphinaMultilingualNeural"},{"name":"Paul","gender":"male","age":47,"voice":"de-DE-FlorianMultilingualNeural"}],"audio":"assets/podcasts/chapter-5.mp3?v=natural-dialogue-2","durationSeconds":650.86},{"chapter":6,"title":"Mein erster Arbeitstag","duration":"11 Min.","speakers":["Aya","Ben"],"intro":"Berufe, Arbeitsplatz, Telefon und Veranstaltungen.","keywords":["Kollege","Aufgabe","Besprechung","weiterleiten","Veranstaltung"],"lines":[{"speaker":"Aya","de":"Willkommen zu Folge 6: Mein erster Arbeitstag. Ich bin Aya, 24 Jahre alt.","ar":"مرحبًا بكم في الحلقة 6: Mein erster Arbeitstag. أنا Aya وعمري 24 عامًا.","pauseAfter":0.5,"kind":"intro","start":0.0,"end":6.888},{"speaker":"Ben","de":"Und ich bin Ben, 39 Jahre alt. Heute sprechen wir über Berufe, Bahnreisen, Veranstaltungen, Telefon.","ar":"وأنا Ben وعمري 39 عامًا. سنتحدث اليوم عن موضوعات الدرس.","pauseAfter":0.6,"kind":"intro","start":7.388,"end":15.692},{"speaker":"Aya","de":"Hör zuerst entspannt zu. Danach wiederholen wir wichtige Wörter und Redemittel, und am Ende gibt es Fragen für dich.","ar":"استمع أولًا بهدوء. بعد ذلك سنراجع كلمات وتعبيرات مهمة، وفي النهاية توجد أسئلة لك.","pauseAfter":0.7,"kind":"intro","start":16.292,"end":23.924},{"speaker":"Ben","de":"Du kannst jederzeit pausieren, laut antworten und anschließend mit unserer Lösung vergleichen. Los geht es!","ar":"يمكنك إيقاف الحلقة والإجابة بصوت عالٍ ثم مقارنة إجابتك بحلنا. لنبدأ!","pauseAfter":1,"kind":"intro","start":24.624,"end":32.112},{"speaker":"Ben","de":"Aya, wie war dein erster Tag in der neuen Firma?","ar":"آية، كيف كان يومك الأول في الشركة الجديدة؟","pauseAfter":0.55,"kind":"scene","start":33.112,"end":36.856},{"speaker":"Aya","de":"Sehr interessant, aber auch anstrengend. Meine Kollegin hat mir zuerst alle Räume gezeigt.","ar":"كان ممتعًا جدًا لكنه متعب أيضًا. أرتني زميلتي أولًا جميع الغرف.","pauseAfter":0.55,"kind":"scene","start":37.406,"end":43.766},{"speaker":"Ben","de":"Welche Aufgaben hast du bekommen?","ar":"ما المهام التي حصلتِ عليها؟","pauseAfter":0.55,"kind":"scene","start":44.316,"end":47.076},{"speaker":"Aya","de":"Ich beantworte E-Mails, organisiere Termine und helfe bei Veranstaltungen.","ar":"أجيب عن رسائل البريد الإلكتروني وأنظم المواعيد وأساعد في الفعاليات.","pauseAfter":0.55,"kind":"scene","start":47.626,"end":52.762},{"speaker":"Ben","de":"Musstest du schon mit Kunden telefonieren?","ar":"هل اضطررتِ بالفعل للتحدث هاتفيًا مع العملاء؟","pauseAfter":0.55,"kind":"scene","start":53.312,"end":56.504},{"speaker":"Aya","de":"Ja. Ein Kunde wollte mit meinem Chef sprechen, aber er war gerade in einer Besprechung.","ar":"نعم. أراد أحد العملاء التحدث مع مديري، لكنه كان في اجتماع حينها.","pauseAfter":0.55,"kind":"scene","start":57.054,"end":62.646},{"speaker":"Ben","de":"Und was hast du gesagt?","ar":"وماذا قلتِ؟","pauseAfter":0.55,"kind":"scene","start":63.196,"end":65.428},{"speaker":"Aya","de":"Ich habe seinen Namen und seine Nummer notiert und versprochen, die Nachricht weiterzuleiten.","ar":"دوّنت اسمه ورقمه ووعدت بتمرير الرسالة.","pauseAfter":0.55,"kind":"scene","start":65.978,"end":71.522},{"speaker":"Aya","de":"Am Nachmittag hilft Aya bei der Vorbereitung einer Veranstaltung in der Firma.","ar":"بعد الظهر تساعد آية في التحضير لفعالية في الشركة.","pauseAfter":0.28,"kind":"scene","start":72.072,"end":76.8},{"speaker":"Ben","de":"Aya, bist du für die Gästeliste oder für den Raum zuständig?","ar":"آية، هل أنت مسؤولة عن قائمة الضيوف أم القاعة؟","pauseAfter":0.28,"kind":"scene","start":77.08,"end":81.544},{"speaker":"Aya","de":"Für beides ein bisschen. Zuerst kontrolliere ich die Anmeldungen.","ar":"عن الاثنين قليلًا. سأراجع التسجيلات أولًا.","pauseAfter":0.28,"kind":"scene","start":81.824,"end":86.552},{"speaker":"Ben","de":"Der Vortrag beginnt um sechs. Die Technik muss vorher funktionieren.","ar":"تبدأ المحاضرة الساعة السادسة ويجب أن تعمل التقنية قبل ذلك.","pauseAfter":0.28,"kind":"scene","start":86.832,"end":92.136},{"speaker":"Aya","de":"Ich verbinde gleich den Laptop mit dem großen Bildschirm.","ar":"سأوصل الكمبيوتر بالشاشة الكبيرة حالًا.","pauseAfter":0.28,"kind":"scene","start":92.416,"end":95.944},{"speaker":"Ben","de":"Gut. Danach ruf bitte den Referenten zurück. Er hat eine Nachricht hinterlassen.","ar":"جيد. بعدها اتصلي بالمحاضر، فقد ترك رسالة.","pauseAfter":0.28,"kind":"scene","start":96.224,"end":102.728},{"speaker":"Aya","de":"Er kommt mit dem Zug. Hoffentlich erreicht er seinen Anschluss.","ar":"سيأتي بالقطار. آمل أن يلحق بقطاره التالي.","pauseAfter":0.28,"kind":"scene","start":103.008,"end":107.424},{"speaker":"Ben","de":"Wenn er ihn verpasst, beginnt die Veranstaltung später.","ar":"إذا فاته القطار فستبدأ الفعالية متأخرة.","pauseAfter":0.28,"kind":"scene","start":107.704,"end":111.424},{"speaker":"Aya","de":"Soll ich am Bahnhof nach einer anderen Verbindung suchen?","ar":"هل أبحث عن رحلة أخرى من المحطة؟","pauseAfter":0.28,"kind":"scene","start":111.704,"end":115.232},{"speaker":"Ben","de":"Ja, und frag ihn, auf welchem Gleis sein Zug ankommt.","ar":"نعم، واسأليه على أي رصيف سيصل قطاره.","pauseAfter":0.28,"kind":"scene","start":115.512,"end":119.568},{"speaker":"Aya","de":"Zu meinen Aufgaben gehört heute wirklich alles: Telefon, Technik und Gäste.","ar":"مهامي اليوم تشمل كل شيء فعلًا: الهاتف والتقنية والضيوف.","pauseAfter":0.28,"kind":"scene","start":119.848,"end":125.128},{"speaker":"Ben","de":"Das ist am ersten Arbeitstag viel, aber du machst das sehr ruhig.","ar":"هذا كثير في أول يوم عمل لكنك تتصرفين بهدوء.","pauseAfter":0.28,"kind":"scene","start":125.408,"end":129.608},{"speaker":"Aya","de":"Später möchte ich gern selbst Veranstaltungen organisieren.","ar":"أريد لاحقًا أن أنظم فعاليات بنفسي.","pauseAfter":0.28,"kind":"scene","start":129.888,"end":133.584},{"speaker":"Ben","de":"Dann ist heute eine gute Übung für deinen Traumberuf.","ar":"إذن اليوم تدريب جيد لمهنة أحلامك.","pauseAfter":0.28,"kind":"scene","start":133.864,"end":137.44},{"speaker":"Aya","de":"Der Referent ruft gerade an. Ich nehme das Gespräch im Büro an.","ar":"المحاضر يتصل الآن. سأجيب في المكتب.","pauseAfter":0.28,"kind":"scene","start":137.72,"end":142.544},{"speaker":"Ben","de":"Perfekt. Ich kümmere mich inzwischen um die Stühle und Getränke.","ar":"ممتاز. سأهتم في الوقت نفسه بالكراسي والمشروبات.","pauseAfter":0.28,"kind":"scene","start":142.824,"end":147.96},{"speaker":"Aya","de":"Das war unsere erste Alltagsszene. Welche Wörter und Sätze hast du sofort verstanden?","ar":"كان هذا مشهدنا اليومي الأول. ما الكلمات والجمل التي فهمتها فورًا؟","pauseAfter":3.2,"kind":"interactive","start":148.24,"end":154.24},{"speaker":"Ben","de":"Denk kurz nach. Du musst nicht jedes Wort verstehen. Wichtig ist zuerst die Situation.","ar":"فكّر قليلًا. ليس ضروريًا أن تفهم كل كلمة؛ المهم أولًا هو فهم الموقف.","pauseAfter":2.4,"kind":"interactive","start":157.44,"end":164.496},{"speaker":"Aya","de":"Die Situation passt zu Kapitel 6. Jetzt sehen wir uns den Wortschatz genauer an.","ar":"الموقف مرتبط بالدرس 6. والآن سنراجع المفردات بدقة أكبر.","pauseAfter":0.8,"kind":"section","start":166.896,"end":172.56},{"speaker":"Aya","de":"Wort Nummer 1: die Tätigkeit, -en. Hör genau zu: die Tätigkeit, -en.","ar":"الكلمة رقم 1: مهمة / نشاط. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":173.36,"end":179.552},{"speaker":"Ben","de":"die Tätigkeit, -en bedeutet: Eine konkrete Aufgabe im Beruf. Ein Beispiel: Zu meinen Tätigkeiten gehört die Kundenberatung.","ar":"معنى die Tätigkeit, -en: مهمة / نشاط.","pauseAfter":0.6,"kind":"vocab","start":180.002,"end":188.714},{"speaker":"Aya","de":"Jetzt bist du dran. Sprich laut nach: die Tätigkeit, -en.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Tätigkeit, -en.","pauseAfter":1.8,"kind":"interactive","start":189.314,"end":194.042},{"speaker":"Ben","de":"Wort Nummer 2: die Abteilung, -en. Hör genau zu: die Abteilung, -en.","ar":"الكلمة رقم 2: قسم. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":195.842,"end":202.058},{"speaker":"Aya","de":"die Abteilung, -en bedeutet: Ein Bereich in einer Firma. Ein Beispiel: Sie arbeitet in der Personalabteilung.","ar":"معنى die Abteilung, -en: قسم.","pauseAfter":0.6,"kind":"vocab","start":202.508,"end":210.38},{"speaker":"Ben","de":"Jetzt bist du dran. Sprich laut nach: die Abteilung, -en.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Abteilung, -en.","pauseAfter":1.8,"kind":"interactive","start":210.98,"end":216.164},{"speaker":"Aya","de":"Wort Nummer 3: die Schicht, -en. Hör genau zu: die Schicht, -en.","ar":"الكلمة رقم 3: وردية. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":217.964,"end":223.772},{"speaker":"Ben","de":"die Schicht, -en bedeutet: Eine feste Arbeitszeit am Tag oder in der Nacht. Ein Beispiel: Diese Woche habe ich Frühschicht.","ar":"معنى die Schicht, -en: وردية.","pauseAfter":0.6,"kind":"vocab","start":224.222,"end":232.622},{"speaker":"Aya","de":"Jetzt bist du dran. Sprich laut nach: die Schicht, -en.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Schicht, -en.","pauseAfter":1.8,"kind":"interactive","start":233.222,"end":237.566},{"speaker":"Ben","de":"Wort Nummer 4: die Bewerbung, -en. Hör genau zu: die Bewerbung, -en.","ar":"الكلمة رقم 4: طلب توظيف. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":239.366,"end":245.558},{"speaker":"Aya","de":"die Bewerbung, -en bedeutet: Unterlagen für eine Arbeitsstelle. Ein Beispiel: Die Bewerbung ist schon abgeschickt.","ar":"معنى die Bewerbung, -en: طلب توظيف.","pauseAfter":0.6,"kind":"vocab","start":246.008,"end":253.952},{"speaker":"Ben","de":"Jetzt bist du dran. Sprich laut nach: die Bewerbung, -en.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Bewerbung, -en.","pauseAfter":1.8,"kind":"interactive","start":254.552,"end":259.736},{"speaker":"Aya","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":261.536,"end":268.064},{"speaker":"Ben","de":"Die Wörter waren: die Tätigkeit, -en, die Abteilung, -en, die Schicht, -en, die Bewerbung, -en.","ar":"الكلمات كانت: مهمة / نشاط، قسم، وردية، طلب توظيف.","pauseAfter":1,"kind":"answer","start":271.064,"end":277.928},{"speaker":"Aya","de":"Wort Nummer 5: der Traumberuf, -e. Hör genau zu: der Traumberuf, -e.","ar":"الكلمة رقم 5: مهنة الأحلام. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":278.928,"end":284.784},{"speaker":"Ben","de":"der Traumberuf, -e bedeutet: Der Beruf, den man besonders gern machen möchte. Ein Beispiel: Pilotin war lange ihr Traumberuf.","ar":"معنى der Traumberuf, -e: مهنة الأحلام.","pauseAfter":0.6,"kind":"vocab","start":285.234,"end":294.258},{"speaker":"Aya","de":"Jetzt bist du dran. Sprich laut nach: der Traumberuf, -e.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Traumberuf, -e.","pauseAfter":1.8,"kind":"interactive","start":294.858,"end":299.538},{"speaker":"Ben","de":"Wort Nummer 6: selbstständig. Hör genau zu: selbstständig.","ar":"الكلمة رقم 6: يعمل لحسابه. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":301.338,"end":307.098},{"speaker":"Aya","de":"selbstständig bedeutet: Mit einer eigenen Firma oder ohne festen Arbeitgeber. Ein Beispiel: Er arbeitet als selbstständiger Designer.","ar":"معنى selbstständig: يعمل لحسابه.","pauseAfter":0.6,"kind":"vocab","start":307.548,"end":316.764},{"speaker":"Ben","de":"Jetzt bist du dran. Sprich laut nach: selbstständig.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: selbstständig.","pauseAfter":1.8,"kind":"interactive","start":317.364,"end":322.26},{"speaker":"Aya","de":"Wort Nummer 7: zuständig für. Hör genau zu: zuständig für.","ar":"الكلمة رقم 7: مسؤول عن. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":324.06,"end":329.628},{"speaker":"Ben","de":"zuständig für bedeutet: Für eine Aufgabe verantwortlich. Ein Beispiel: Ich bin für neue Kunden zuständig.","ar":"معنى zuständig für: مسؤول عن.","pauseAfter":0.6,"kind":"vocab","start":330.078,"end":337.662},{"speaker":"Aya","de":"Jetzt bist du dran. Sprich laut nach: zuständig für.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: zuständig für.","pauseAfter":1.8,"kind":"interactive","start":338.262,"end":342.63},{"speaker":"Ben","de":"Wort Nummer 8: die Verbindung, -en. Hör genau zu: die Verbindung, -en.","ar":"الكلمة رقم 8: وصلة / رحلة مواصلات. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":344.43,"end":350.646},{"speaker":"Aya","de":"die Verbindung, -en bedeutet: Eine Reisemöglichkeit zwischen zwei Orten. Ein Beispiel: Gibt es eine direkte Verbindung nach Basel?","ar":"معنى die Verbindung, -en: وصلة / رحلة مواصلات.","pauseAfter":0.6,"kind":"vocab","start":351.096,"end":360.792},{"speaker":"Ben","de":"Jetzt bist du dran. Sprich laut nach: die Verbindung, -en.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Verbindung, -en.","pauseAfter":1.8,"kind":"interactive","start":361.392,"end":366.576},{"speaker":"Aya","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":368.376,"end":374.904},{"speaker":"Ben","de":"Die Wörter waren: der Traumberuf, -e, selbstständig, zuständig für, die Verbindung, -en.","ar":"الكلمات كانت: مهنة الأحلام، يعمل لحسابه، مسؤول عن، وصلة / رحلة مواصلات.","pauseAfter":1,"kind":"answer","start":377.904,"end":384.504},{"speaker":"Aya","de":"Wort Nummer 9: umsteigen. Hör genau zu: umsteigen.","ar":"الكلمة رقم 9: يغيّر القطار. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":385.504,"end":390.16},{"speaker":"Ben","de":"umsteigen bedeutet: Von einem Zug oder Bus in einen anderen wechseln. Ein Beispiel: In Mannheim müssen Sie umsteigen.","ar":"معنى umsteigen: يغيّر القطار.","pauseAfter":0.6,"kind":"vocab","start":390.61,"end":398.722},{"speaker":"Aya","de":"Jetzt bist du dran. Sprich laut nach: umsteigen.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: umsteigen.","pauseAfter":1.8,"kind":"interactive","start":399.322,"end":403.33},{"speaker":"Ben","de":"Wort Nummer 10: der Anschluss, ⸚e. Hör genau zu: der Anschluss, ⸚e.","ar":"الكلمة رقم 10: وصلة المواصلات التالية. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":405.13,"end":410.386},{"speaker":"Aya","de":"der Anschluss, ⸚e bedeutet: Der nächste passende Zug oder Bus. Ein Beispiel: Wir haben nur zehn Minuten bis zum Anschluss.","ar":"معنى der Anschluss, ⸚e: وصلة المواصلات التالية.","pauseAfter":0.6,"kind":"vocab","start":410.836,"end":419.86},{"speaker":"Ben","de":"Jetzt bist du dran. Sprich laut nach: der Anschluss, ⸚e.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Anschluss, ⸚e.","pauseAfter":1.8,"kind":"interactive","start":420.46,"end":425.572},{"speaker":"Ben","de":"Sehr gut. Wörter allein reichen aber nicht. Im Gespräch brauchen wir fertige Sätze und passende Reaktionen.","ar":"جيد جدًا. الكلمات وحدها لا تكفي؛ في الحوار نحتاج إلى جمل جاهزة وردود مناسبة.","pauseAfter":0.8,"kind":"section","start":427.372,"end":435.604},{"speaker":"Aya","de":"Situation 1, Über Berufe sprechen. Was könntest du sagen?","ar":"الموقف رقم 1. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":436.404,"end":441.324},{"speaker":"Ben","de":"Eine passende Formulierung ist: Ich bin hauptsächlich für … zuständig.","ar":"تعبير مناسب هو: أنا مسؤول أساسًا عن ...","pauseAfter":0.7,"kind":"phrase","start":443.524,"end":448.228},{"speaker":"Aya","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Ich bin hauptsächlich für … zuständig.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":448.928,"end":455.0},{"speaker":"Ben","de":"Situation 2, Über Berufe sprechen. Was könntest du sagen?","ar":"الموقف رقم 2. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":457.2,"end":462.648},{"speaker":"Aya","de":"Eine passende Formulierung ist: Zu meinen Aufgaben gehört …","ar":"تعبير مناسب هو: من مهامي ...","pauseAfter":0.7,"kind":"phrase","start":464.848,"end":469.072},{"speaker":"Ben","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Zu meinen Aufgaben gehört …","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":469.772,"end":474.98},{"speaker":"Aya","de":"Situation 3, Über Berufe sprechen. Was könntest du sagen?","ar":"الموقف رقم 3. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":477.18,"end":482.052},{"speaker":"Ben","de":"Eine passende Formulierung ist: Später möchte ich gern … werden.","ar":"تعبير مناسب هو: في المستقبل أحب أصبح ...","pauseAfter":0.7,"kind":"phrase","start":484.252,"end":488.716},{"speaker":"Aya","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Später möchte ich gern … werden.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":489.416,"end":495.272},{"speaker":"Ben","de":"Situation 4, Über Berufe sprechen. Was könntest du sagen?","ar":"الموقف رقم 4. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":497.472,"end":502.92},{"speaker":"Aya","de":"Eine passende Formulierung ist: An diesem Beruf gefällt mir besonders …","ar":"تعبير مناسب هو: اللي يعجبني خصوصًا في المهنة دي ...","pauseAfter":0.7,"kind":"phrase","start":505.12,"end":509.68},{"speaker":"Ben","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: An diesem Beruf gefällt mir besonders …","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":510.38,"end":516.164},{"speaker":"Aya","de":"Situation 5, Am Fahrkartenschalter. Was könntest du sagen?","ar":"الموقف رقم 5. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":518.364,"end":523.212},{"speaker":"Ben","de":"Eine passende Formulierung ist: Ich hätte gern eine Fahrkarte nach …","ar":"تعبير مناسب هو: عايز تذكرة إلى ...","pauseAfter":0.7,"kind":"phrase","start":525.412,"end":529.828},{"speaker":"Aya","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Ich hätte gern eine Fahrkarte nach …","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":530.528,"end":536.384},{"speaker":"Ben","de":"Situation 6, Am Fahrkartenschalter. Was könntest du sagen?","ar":"الموقف رقم 6. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":538.584,"end":544.08},{"speaker":"Aya","de":"Eine passende Formulierung ist: Gibt es eine direkte Verbindung?","ar":"تعبير مناسب هو: في رحلة مباشرة؟","pauseAfter":0.7,"kind":"phrase","start":546.28,"end":550.792},{"speaker":"Ben","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Gibt es eine direkte Verbindung?","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":551.492,"end":557.156},{"speaker":"Aya","de":"Jetzt kommt ein kurzer Hör- und Grammatikcheck. Antworte zuerst selbst. Danach hörst du die Lösung.","ar":"والآن اختبار قصير في الاستماع والقواعد. أجب أولًا بنفسك ثم استمع إلى الحل.","pauseAfter":0.8,"kind":"section","start":559.356,"end":566.58},{"speaker":"Aya","de":"Frage 1: Das ist ein ___ Beruf.","ar":"السؤال رقم 1. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":567.38,"end":572.06},{"speaker":"Aya","de":"Die Möglichkeiten sind: A, interessanter. B, interessante. C, interessanten.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":572.56,"end":580.024},{"speaker":"Ben","de":"Die richtige Antwort ist A: interessanter. Nominativ maskulin nach ein: interessanter.","ar":"الإجابة الصحيحة: مذكر Nominativ بعد ein: -er.","pauseAfter":1,"kind":"answer","start":583.224,"end":589.968},{"speaker":"Ben","de":"Frage 2: Sie sucht eine ___ Stelle.","ar":"السؤال رقم 2. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":590.968,"end":595.456},{"speaker":"Ben","de":"Die Möglichkeiten sind: A, neuen. B, neue. C, neuer.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":595.956,"end":602.604},{"speaker":"Aya","de":"Die richtige Antwort ist B: neue. Feminin: eine neue Stelle.","ar":"الإجابة الصحيحة: مؤنث: neue.","pauseAfter":1,"kind":"answer","start":605.804,"end":610.94},{"speaker":"Aya","de":"Frage 3: Ich spreche mit einem ___ Kunden.","ar":"السؤال رقم 3. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":611.94,"end":617.052},{"speaker":"Aya","de":"Die Möglichkeiten sind: A, neuer. B, neuen. C, neues.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":617.552,"end":623.312},{"speaker":"Ben","de":"Die richtige Antwort ist B: neuen. Dativ: einem neuen Kunden.","ar":"الإجابة الصحيحة: Dativ: -en.","pauseAfter":1,"kind":"answer","start":626.512,"end":632.176},{"speaker":"Ben","de":"Frage 4: Mein Bruder ___ Arzt.","ar":"السؤال رقم 4. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":633.176,"end":637.496},{"speaker":"Ben","de":"Die Möglichkeiten sind: A, wird. B, werdet. C, wirst.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":637.996,"end":644.596},{"speaker":"Aya","de":"Die richtige Antwort ist A: wird. er → wird.","ar":"الإجابة الصحيحة: مع er نستخدم wird.","pauseAfter":1,"kind":"answer","start":647.796,"end":651.54},{"speaker":"Ben","de":"Zum Abschluss: Nenne drei neue Wörter aus Kapitel 6 und bilde mit jedem Wort einen Satz.","ar":"في الختام: اذكر ثلاث كلمات جديدة من الدرس 6 وكوّن جملة بكل كلمة.","pauseAfter":4,"kind":"interactive","start":652.54,"end":658.564},{"speaker":"Aya","de":"Wenn das noch schwer ist, höre die Folge morgen noch einmal. Beim zweiten Hören wirst du deutlich mehr verstehen.","ar":"إذا كان الأمر ما زال صعبًا، فاستمع إلى الحلقة غدًا مرة أخرى. في المرة الثانية ستفهم أكثر بوضوح.","pauseAfter":0.7,"kind":"outro","start":662.564,"end":669.572},{"speaker":"Ben","de":"Danke fürs Zuhören. Das war Mein erster Arbeitstag. Bis zur nächsten Folge!","ar":"شكرًا على الاستماع. كانت هذه حلقة Mein erster Arbeitstag. إلى الحلقة القادمة!","pauseAfter":1,"kind":"outro","start":670.272,"end":676.944}],"people":[{"name":"Aya","gender":"female","age":24,"voice":"de-DE-SeraphinaMultilingualNeural"},{"name":"Ben","gender":"male","age":39,"voice":"de-DE-KillianNeural"}],"audio":"assets/podcasts/chapter-6.mp3?v=natural-dialogue-2","durationSeconds":678.0},{"chapter":7,"title":"Unterwegs zur Arbeit","duration":"11 Min.","speakers":["Sofia","Malik"],"intro":"Verkehr, Verspätungen und Wegbeschreibung.","keywords":["Verkehrsmittel","umsteigen","Verspätung","Haltestelle","geradeaus"],"lines":[{"speaker":"Sofia","de":"Willkommen zu Folge 7: Unterwegs zur Arbeit. Ich bin Sofia, 32 Jahre alt.","ar":"مرحبًا بكم في الحلقة 7: Unterwegs zur Arbeit. أنا Sofia وعمري 32 عامًا.","pauseAfter":0.5,"kind":"intro","start":0.0,"end":7.008},{"speaker":"Malik","de":"Und ich bin Malik, 35 Jahre alt. Heute sprechen wir über Verkehr, Weg zur Arbeit, Wegbeschreibung.","ar":"وأنا Malik وعمري 35 عامًا. سنتحدث اليوم عن موضوعات الدرس.","pauseAfter":0.6,"kind":"intro","start":7.508,"end":15.044},{"speaker":"Sofia","de":"Hör zuerst entspannt zu. Danach wiederholen wir wichtige Wörter und Redemittel, und am Ende gibt es Fragen für dich.","ar":"استمع أولًا بهدوء. بعد ذلك سنراجع كلمات وتعبيرات مهمة، وفي النهاية توجد أسئلة لك.","pauseAfter":0.7,"kind":"intro","start":15.644,"end":23.276},{"speaker":"Malik","de":"Du kannst jederzeit pausieren, laut antworten und anschließend mit unserer Lösung vergleichen. Los geht es!","ar":"يمكنك إيقاف الحلقة والإجابة بصوت عالٍ ثم مقارنة إجابتك بحلنا. لنبدأ!","pauseAfter":1,"kind":"intro","start":23.976,"end":31.128},{"speaker":"Sofia","de":"Malik, mit welchem Verkehrsmittel fährst du normalerweise zur Arbeit?","ar":"مالك، بأي وسيلة مواصلات تذهب عادةً إلى العمل؟","pauseAfter":0.55,"kind":"scene","start":32.128,"end":36.568},{"speaker":"Malik","de":"Zuerst fahre ich mit dem Bus und dann muss ich in die U-Bahn umsteigen.","ar":"أركب الحافلة أولًا ثم يجب أن أبدّل إلى المترو.","pauseAfter":0.55,"kind":"scene","start":37.118,"end":41.366},{"speaker":"Sofia","de":"Dauert der Weg lange?","ar":"هل تستغرق الطريق وقتًا طويلًا؟","pauseAfter":0.55,"kind":"scene","start":41.916,"end":43.668},{"speaker":"Malik","de":"Wenn alles pünktlich ist, brauche ich ungefähr vierzig Minuten. Heute hatte der Bus aber Verspätung.","ar":"عندما تكون المواصلات في موعدها أحتاج نحو أربعين دقيقة. لكن الحافلة تأخرت اليوم.","pauseAfter":0.55,"kind":"scene","start":44.218,"end":51.106},{"speaker":"Sofia","de":"Ich fahre meistens mit dem Fahrrad. Das ist schnell und ich stehe nicht im Stau.","ar":"أنا أذهب غالبًا بالدراجة. هذا سريع ولا أقف في الازدحام.","pauseAfter":0.55,"kind":"scene","start":51.656,"end":56.912},{"speaker":"Malik","de":"Kannst du mir sagen, wo der neue Fahrradweg beginnt?","ar":"هل يمكنك أن تخبريني أين يبدأ مسار الدراجات الجديد؟","pauseAfter":0.55,"kind":"scene","start":57.462,"end":61.158},{"speaker":"Sofia","de":"Fahr bis zur nächsten Ampel geradeaus und bieg dann links ab. Dort siehst du ein blaues Schild.","ar":"اذهب مستقيمًا حتى إشارة المرور التالية ثم انعطف يسارًا. سترى هناك لافتة زرقاء.","pauseAfter":0.55,"kind":"scene","start":61.708,"end":67.972},{"speaker":"Malik","de":"Danke! Vielleicht probiere ich das Fahrrad morgen auch aus.","ar":"شكرًا! ربما أجرب الدراجة غدًا أيضًا.","pauseAfter":0.55,"kind":"scene","start":68.522,"end":73.202},{"speaker":"Sofia","de":"Am nächsten Morgen probiert Malik tatsächlich den Weg mit dem Fahrrad aus.","ar":"في صباح اليوم التالي يجرب مالك فعلًا الطريق بالدراجة.","pauseAfter":0.28,"kind":"scene","start":73.752,"end":78.144},{"speaker":"Malik","de":"Sofia, ich stehe an einer großen Kreuzung. Wo muss ich jetzt abbiegen?","ar":"صوفيا، أنا عند تقاطع كبير. أين أنعطف الآن؟","pauseAfter":0.28,"kind":"scene","start":78.424,"end":83.92},{"speaker":"Sofia","de":"Siehst du die Baustelle neben der Straßenbahnhaltestelle?","ar":"هل ترى موقع البناء بجانب محطة الترام؟","pauseAfter":0.28,"kind":"scene","start":84.2,"end":87.728},{"speaker":"Malik","de":"Ja, aber der normale Fahrradweg ist dort gesperrt.","ar":"نعم، لكن مسار الدراجات المعتاد مغلق هناك.","pauseAfter":0.28,"kind":"scene","start":88.008,"end":91.68},{"speaker":"Sofia","de":"Dann fahr rechts an der Baustelle vorbei und danach immer geradeaus.","ar":"إذن مر من يمين موقع البناء ثم تابع مستقيمًا.","pauseAfter":0.28,"kind":"scene","start":91.96,"end":96.352},{"speaker":"Malik","de":"Hier ist viel Verkehr. Mit der U-Bahn wäre ich wahrscheinlich schneller.","ar":"حركة المرور كثيفة هنا. ربما كنت سأكون أسرع بالمترو.","pauseAfter":0.28,"kind":"scene","start":96.632,"end":101.6},{"speaker":"Sofia","de":"Heute gibt es dort auch eine Verspätung. Das Fahrrad ist trotzdem eine gute Wahl.","ar":"هناك تأخير في المترو اليوم أيضًا. الدراجة ما زالت اختيارًا جيدًا.","pauseAfter":0.28,"kind":"scene","start":101.88,"end":107.352},{"speaker":"Malik","de":"Ich sehe jetzt ein blaues Schild und eine Ampel.","ar":"أرى الآن لافتة زرقاء وإشارة مرور.","pauseAfter":0.28,"kind":"scene","start":107.632,"end":110.92},{"speaker":"Sofia","de":"An der Ampel links, dann erreichst du in fünf Minuten dein Ziel.","ar":"انعطف يسارًا عند الإشارة وستصل إلى هدفك خلال خمس دقائق.","pauseAfter":0.28,"kind":"scene","start":111.2,"end":115.688},{"speaker":"Malik","de":"Muss ich das Fahrrad an einer bestimmten Station zurückgeben?","ar":"هل يجب أن أعيد الدراجة في محطة محددة؟","pauseAfter":0.28,"kind":"scene","start":115.968,"end":119.952},{"speaker":"Sofia","de":"Ja, direkt vor deiner Firma gibt es eine Station für Leihräder.","ar":"نعم، توجد محطة للدراجات المستأجرة أمام شركتك مباشرة.","pauseAfter":0.28,"kind":"scene","start":120.232,"end":124.576},{"speaker":"Malik","de":"Das ist praktisch. Ein Nachteil ist nur der starke Wind heute.","ar":"هذا عملي. العيب الوحيد هو الرياح القوية اليوم.","pauseAfter":0.28,"kind":"scene","start":124.856,"end":129.608},{"speaker":"Sofia","de":"Dafür stehst du nicht im Stau und musst nicht umsteigen.","ar":"لكن في المقابل لن تقف في الزحام ولن تبدل وسيلة المواصلات.","pauseAfter":0.28,"kind":"scene","start":129.888,"end":133.368},{"speaker":"Malik","de":"Stimmt. Und ich bin trotz der kleinen Umleitung fast pünktlich.","ar":"صحيح. وأنا تقريبًا في الموعد رغم التحويلة الصغيرة.","pauseAfter":0.28,"kind":"scene","start":133.648,"end":138.376},{"speaker":"Sofia","de":"Fahr vorsichtig und achte an der Kreuzung auf die Fußgänger.","ar":"قد بحذر وانتبه للمشاة عند التقاطع.","pauseAfter":0.28,"kind":"scene","start":138.656,"end":142.496},{"speaker":"Malik","de":"Danke für die Wegbeschreibung. Morgen kenne ich den Weg schon allein.","ar":"شكرًا على وصف الطريق. غدًا سأعرفه وحدي.","pauseAfter":0.28,"kind":"scene","start":142.776,"end":147.72},{"speaker":"Sofia","de":"Das war unsere erste Alltagsszene. Welche Wörter und Sätze hast du sofort verstanden?","ar":"كان هذا مشهدنا اليومي الأول. ما الكلمات والجمل التي فهمتها فورًا؟","pauseAfter":3.2,"kind":"interactive","start":148.0,"end":154.0},{"speaker":"Malik","de":"Denk kurz nach. Du musst nicht jedes Wort verstehen. Wichtig ist zuerst die Situation.","ar":"فكّر قليلًا. ليس ضروريًا أن تفهم كل كلمة؛ المهم أولًا هو فهم الموقف.","pauseAfter":2.4,"kind":"interactive","start":157.2,"end":164.064},{"speaker":"Sofia","de":"Die Situation passt zu Kapitel 7. Jetzt sehen wir uns den Wortschatz genauer an.","ar":"الموقف مرتبط بالدرس 7. والآن سنراجع المفردات بدقة أكبر.","pauseAfter":0.8,"kind":"section","start":166.464,"end":172.152},{"speaker":"Sofia","de":"Wort Nummer 1: der Verkehr. Hör genau zu: der Verkehr.","ar":"الكلمة رقم 1: المرور / حركة السير. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":172.952,"end":177.8},{"speaker":"Malik","de":"der Verkehr bedeutet: Alle Autos, Busse und Bahnen, die auf der Straße fahren. Ein Beispiel: Morgens gibt es in der Stadt viel Verkehr.","ar":"معنى der Verkehr: المرور / حركة السير.","pauseAfter":0.6,"kind":"vocab","start":178.25,"end":187.13},{"speaker":"Sofia","de":"Jetzt bist du dran. Sprich laut nach: der Verkehr.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Verkehr.","pauseAfter":1.8,"kind":"interactive","start":187.73,"end":191.738},{"speaker":"Malik","de":"Wort Nummer 2: das Verkehrsmittel, -. Hör genau zu: das Verkehrsmittel, -.","ar":"الكلمة رقم 2: وسيلة مواصلات. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":193.538,"end":199.154},{"speaker":"Sofia","de":"das Verkehrsmittel, - bedeutet: Etwas, mit dem man fährt: Bus, Bahn, Auto, Fahrrad … Ein Beispiel: Welches Verkehrsmittel benutzt du am liebsten?","ar":"معنى das Verkehrsmittel, -: وسيلة مواصلات.","pauseAfter":0.6,"kind":"vocab","start":199.604,"end":210.644},{"speaker":"Malik","de":"Jetzt bist du dran. Sprich laut nach: das Verkehrsmittel, -.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: das Verkehrsmittel, -.","pauseAfter":1.8,"kind":"interactive","start":211.244,"end":216.068},{"speaker":"Sofia","de":"Wort Nummer 3: öffentlich. Hör genau zu: öffentlich.","ar":"الكلمة رقم 3: عام / عمومي. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":217.868,"end":222.644},{"speaker":"Malik","de":"öffentlich bedeutet: Für alle Menschen; das Gegenteil von privat. Ein Beispiel: Ich fahre mit öffentlichen Verkehrsmitteln zur Arbeit.","ar":"معنى öffentlich: عام / عمومي.","pauseAfter":0.6,"kind":"vocab","start":223.094,"end":231.446},{"speaker":"Sofia","de":"Jetzt bist du dran. Sprich laut nach: öffentlich.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: öffentlich.","pauseAfter":1.8,"kind":"interactive","start":232.046,"end":236.126},{"speaker":"Malik","de":"Wort Nummer 4: die U-Bahn, -en. Hör genau zu: die U-Bahn, -en.","ar":"الكلمة رقم 4: المترو. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":237.926,"end":243.494},{"speaker":"Sofia","de":"die U-Bahn, -en bedeutet: Eine Bahn, die unter der Erde fährt. Ein Beispiel: Die U-Bahn kommt alle fünf Minuten.","ar":"معنى die U-Bahn, -en: المترو.","pauseAfter":0.6,"kind":"vocab","start":243.944,"end":252.488},{"speaker":"Malik","de":"Jetzt bist du dran. Sprich laut nach: die U-Bahn, -en.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die U-Bahn, -en.","pauseAfter":1.8,"kind":"interactive","start":253.088,"end":258.008},{"speaker":"Sofia","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":259.808,"end":266.336},{"speaker":"Malik","de":"Die Wörter waren: der Verkehr, das Verkehrsmittel, -, öffentlich, die U-Bahn, -en.","ar":"الكلمات كانت: المرور / حركة السير، وسيلة مواصلات، عام / عمومي، المترو.","pauseAfter":1,"kind":"answer","start":269.336,"end":274.688},{"speaker":"Sofia","de":"Wort Nummer 5: die Straßenbahn, -en. Hör genau zu: die Straßenbahn, -en.","ar":"الكلمة رقم 5: الترام. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":275.688,"end":281.928},{"speaker":"Malik","de":"die Straßenbahn, -en bedeutet: Eine Bahn, die in der Stadt auf der Straße fährt. Ein Beispiel: Die Straßenbahn hält direkt vor meinem Haus.","ar":"معنى die Straßenbahn, -en: الترام.","pauseAfter":0.6,"kind":"vocab","start":282.378,"end":291.354},{"speaker":"Sofia","de":"Jetzt bist du dran. Sprich laut nach: die Straßenbahn, -en.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Straßenbahn, -en.","pauseAfter":1.8,"kind":"interactive","start":291.954,"end":296.778},{"speaker":"Malik","de":"Wort Nummer 6: die Haltestelle, -n. Hör genau zu: die Haltestelle, -n.","ar":"الكلمة رقم 6: المحطة / الموقف. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":298.578,"end":303.954},{"speaker":"Sofia","de":"die Haltestelle, -n bedeutet: Der Ort, wo Bus oder Straßenbahn halten. Ein Beispiel: Ich warte an der Haltestelle auf den Bus.","ar":"معنى die Haltestelle, -n: المحطة / الموقف.","pauseAfter":0.6,"kind":"vocab","start":304.404,"end":313.62},{"speaker":"Malik","de":"Jetzt bist du dran. Sprich laut nach: die Haltestelle, -n.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Haltestelle, -n.","pauseAfter":1.8,"kind":"interactive","start":314.22,"end":319.404},{"speaker":"Sofia","de":"Wort Nummer 7: der Bahnsteig, -e. Hör genau zu: der Bahnsteig, -e.","ar":"الكلمة رقم 7: رصيف القطار. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":321.204,"end":326.82},{"speaker":"Malik","de":"der Bahnsteig, -e bedeutet: Der Platz im Bahnhof, wo man auf den Zug wartet. Ein Beispiel: Der Zug nach Köln fährt von Bahnsteig 3 ab.","ar":"معنى der Bahnsteig, -e: رصيف القطار.","pauseAfter":0.6,"kind":"vocab","start":327.27,"end":336.438},{"speaker":"Sofia","de":"Jetzt bist du dran. Sprich laut nach: der Bahnsteig, -e.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Bahnsteig, -e.","pauseAfter":1.8,"kind":"interactive","start":337.038,"end":341.622},{"speaker":"Malik","de":"Wort Nummer 8: das Gleis, -e. Hör genau zu: das Gleis, -e.","ar":"الكلمة رقم 8: السكة / خط القطار. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":343.422,"end":348.294},{"speaker":"Sofia","de":"das Gleis, -e bedeutet: Die Schienen, auf denen der Zug fährt; auch die Nummer im Bahnhof. Ein Beispiel: Der ICE fährt heute von Gleis 7.","ar":"معنى das Gleis, -e: السكة / خط القطار.","pauseAfter":0.6,"kind":"vocab","start":348.744,"end":359.352},{"speaker":"Malik","de":"Jetzt bist du dran. Sprich laut nach: das Gleis, -e.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: das Gleis, -e.","pauseAfter":1.8,"kind":"interactive","start":359.952,"end":364.848},{"speaker":"Sofia","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":366.648,"end":373.176},{"speaker":"Malik","de":"Die Wörter waren: die Straßenbahn, -en, die Haltestelle, -n, der Bahnsteig, -e, das Gleis, -e.","ar":"الكلمات كانت: الترام، المحطة / الموقف، رصيف القطار، السكة / خط القطار.","pauseAfter":1,"kind":"answer","start":376.176,"end":383.112},{"speaker":"Sofia","de":"Wort Nummer 9: die Verspätung, -en. Hör genau zu: die Verspätung, -en.","ar":"الكلمة رقم 9: تأخير. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":384.112,"end":390.52},{"speaker":"Malik","de":"die Verspätung, -en bedeutet: Wenn der Zug oder Bus zu spät kommt. Ein Beispiel: Der Zug hat 20 Minuten Verspätung.","ar":"معنى die Verspätung, -en: تأخير.","pauseAfter":0.6,"kind":"vocab","start":390.97,"end":399.154},{"speaker":"Sofia","de":"Jetzt bist du dran. Sprich laut nach: die Verspätung, -en.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Verspätung, -en.","pauseAfter":1.8,"kind":"interactive","start":399.754,"end":404.482},{"speaker":"Malik","de":"Wort Nummer 10: der Stau, -s. Hör genau zu: der Stau, -s.","ar":"الكلمة رقم 10: زحمة / اختناق مروري. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":406.282,"end":410.962},{"speaker":"Sofia","de":"der Stau, -s bedeutet: Sehr viele Autos stehen auf der Straße und fahren nicht weiter. Ein Beispiel: Wegen des Staus komme ich zu spät zur Arbeit.","ar":"معنى der Stau, -s: زحمة / اختناق مروري.","pauseAfter":0.6,"kind":"vocab","start":411.412,"end":421.252},{"speaker":"Malik","de":"Jetzt bist du dran. Sprich laut nach: der Stau, -s.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Stau, -s.","pauseAfter":1.8,"kind":"interactive","start":421.852,"end":426.724},{"speaker":"Malik","de":"Sehr gut. Wörter allein reichen aber nicht. Im Gespräch brauchen wir fertige Sätze und passende Reaktionen.","ar":"جيد جدًا. الكلمات وحدها لا تكفي؛ في الحوار نحتاج إلى جمل جاهزة وردود مناسبة.","pauseAfter":0.8,"kind":"section","start":428.524,"end":436.54},{"speaker":"Sofia","de":"Situation 1, Informationen erfragen. Was könntest du sagen?","ar":"الموقف رقم 1. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":437.34,"end":442.308},{"speaker":"Malik","de":"Eine passende Formulierung ist: Könnten Sie mir sagen, wann der Zug abfährt?","ar":"تعبير مناسب هو: ممكن حضرتك تقول لي القطار بيقوم امتى؟","pauseAfter":0.7,"kind":"phrase","start":444.508,"end":449.428},{"speaker":"Sofia","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Könnten Sie mir sagen, wann der Zug abfährt?","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":450.128,"end":456.272},{"speaker":"Malik","de":"Situation 2, Informationen erfragen. Was könntest du sagen?","ar":"الموقف رقم 2. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":458.472,"end":463.992},{"speaker":"Sofia","de":"Eine passende Formulierung ist: Kannst du mir sagen, wo die Haltestelle ist?","ar":"تعبير مناسب هو: ممكن تقول لي المحطة فين؟","pauseAfter":0.7,"kind":"phrase","start":466.192,"end":471.136},{"speaker":"Malik","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Kannst du mir sagen, wo die Haltestelle ist?","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":471.836,"end":477.836},{"speaker":"Sofia","de":"Situation 3, Informationen erfragen. Was könntest du sagen?","ar":"الموقف رقم 3. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":480.036,"end":485.028},{"speaker":"Malik","de":"Eine passende Formulierung ist: Entschuldigung, wissen Sie, ob der Bus hier hält?","ar":"تعبير مناسب هو: عفوًا، حضرتك عارف إذا كان الأتوبيس بيقف هنا؟","pauseAfter":0.7,"kind":"phrase","start":487.228,"end":492.484},{"speaker":"Sofia","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Entschuldigung, wissen Sie, ob der Bus hier hält?","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":493.184,"end":499.52},{"speaker":"Malik","de":"Situation 4, Informationen erfragen. Was könntest du sagen?","ar":"الموقف رقم 4. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":501.72,"end":507.24},{"speaker":"Sofia","de":"Eine passende Formulierung ist: Darf ich Sie / dich fragen, wie viel das Ticket kostet?","ar":"تعبير مناسب هو: ممكن أسأل حضرتك/أسألك التذكرة بكام؟","pauseAfter":0.7,"kind":"phrase","start":509.44,"end":514.864},{"speaker":"Malik","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Darf ich Sie / dich fragen, wie viel das Ticket kostet?","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":515.564,"end":522.14},{"speaker":"Sofia","de":"Situation 5, Informationen erfragen. Was könntest du sagen?","ar":"الموقف رقم 5. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":524.34,"end":529.308},{"speaker":"Malik","de":"Eine passende Formulierung ist: Ich möchte gern wissen, wie ich zum Bahnhof komme.","ar":"تعبير مناسب هو: عايز أعرف أوصل للمحطة إزاي.","pauseAfter":0.7,"kind":"phrase","start":531.508,"end":536.548},{"speaker":"Sofia","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Ich möchte gern wissen, wie ich zum Bahnhof komme.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":537.248,"end":543.776},{"speaker":"Malik","de":"Situation 6, Informationen erfragen. Was könntest du sagen?","ar":"الموقف رقم 6. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":545.976,"end":551.544},{"speaker":"Sofia","de":"Eine passende Formulierung ist: Mich interessiert, welche Verbindung am schnellsten ist.","ar":"تعبير مناسب هو: يهمني أعرف أي خط هو الأسرع.","pauseAfter":0.7,"kind":"phrase","start":553.744,"end":559.672},{"speaker":"Malik","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Mich interessiert, welche Verbindung am schnellsten ist.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":560.372,"end":566.708},{"speaker":"Sofia","de":"Jetzt kommt ein kurzer Hör- und Grammatikcheck. Antworte zuerst selbst. Danach hörst du die Lösung.","ar":"والآن اختبار قصير في الاستماع والقواعد. أجب أولًا بنفسك ثم استمع إلى الحل.","pauseAfter":0.8,"kind":"section","start":568.908,"end":576.132},{"speaker":"Sofia","de":"Frage 1: Ich weiß nicht, wann der Zug ___.","ar":"السؤال رقم 1. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":576.932,"end":582.092},{"speaker":"Sofia","de":"Die Möglichkeiten sind: A, fährt ab. B, abfährt. C, ab fährt er.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":582.592,"end":589.096},{"speaker":"Malik","de":"Die richtige Antwort ist B: abfährt. Im Nebensatz steht das trennbare Verb zusammen am Ende.","ar":"الإجابة الصحيحة: في الجملة الثانوية الفعل المنفصل بيتكتب كلمة واحدة في الآخر.","pauseAfter":1,"kind":"answer","start":592.296,"end":598.704},{"speaker":"Malik","de":"Frage 2: Wissen Sie, ___ der Bus hier hält?","ar":"السؤال رقم 2. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":599.704,"end":604.624},{"speaker":"Malik","de":"Die Möglichkeiten sind: A, ob. B, dass. C, wann.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":605.124,"end":610.38},{"speaker":"Sofia","de":"Die richtige Antwort ist A: ob. Ja/Nein-Frage → indirekte Frage mit „ob“.","ar":"الإجابة الصحيحة: سؤال نعم/لا → في غير المباشر بنستخدم ob.","pauseAfter":1,"kind":"answer","start":613.58,"end":620.684},{"speaker":"Sofia","de":"Frage 3: Sie geht ___ Kaufhaus vorbei.","ar":"السؤال رقم 3. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":621.684,"end":626.724},{"speaker":"Sofia","de":"Die Möglichkeiten sind: A, am. B, an das. C, im.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":627.224,"end":632.096},{"speaker":"Malik","de":"Die richtige Antwort ist A: am. an … vorbei + Dativ: am Kaufhaus vorbei.","ar":"الإجابة الصحيحة: an...vorbei بياخد Dativ.","pauseAfter":1,"kind":"answer","start":635.296,"end":641.392},{"speaker":"Malik","de":"Frage 4: Dann gehst du ___ Park.","ar":"السؤال رقم 4. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":642.392,"end":646.424},{"speaker":"Malik","de":"Die Möglichkeiten sind: A, durch dem. B, durch den. C, bis zum den.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":646.924,"end":653.716},{"speaker":"Sofia","de":"Die richtige Antwort ist B: durch den. durch + Akkusativ: durch den Park.","ar":"الإجابة الصحيحة: durch بياخد Akkusativ.","pauseAfter":1,"kind":"answer","start":656.916,"end":662.844},{"speaker":"Malik","de":"Zum Abschluss: Nenne drei neue Wörter aus Kapitel 7 und bilde mit jedem Wort einen Satz.","ar":"في الختام: اذكر ثلاث كلمات جديدة من الدرس 7 وكوّن جملة بكل كلمة.","pauseAfter":4,"kind":"interactive","start":663.844,"end":669.364},{"speaker":"Sofia","de":"Wenn das noch schwer ist, höre die Folge morgen noch einmal. Beim zweiten Hören wirst du deutlich mehr verstehen.","ar":"إذا كان الأمر ما زال صعبًا، فاستمع إلى الحلقة غدًا مرة أخرى. في المرة الثانية ستفهم أكثر بوضوح.","pauseAfter":0.7,"kind":"outro","start":673.364,"end":680.372},{"speaker":"Malik","de":"Danke fürs Zuhören. Das war Unterwegs zur Arbeit. Bis zur nächsten Folge!","ar":"شكرًا على الاستماع. كانت هذه حلقة Unterwegs zur Arbeit. إلى الحلقة القادمة!","pauseAfter":1,"kind":"outro","start":681.072,"end":687.432}],"people":[{"name":"Sofia","gender":"female","age":32,"voice":"de-DE-SeraphinaMultilingualNeural"},{"name":"Malik","gender":"male","age":35,"voice":"de-DE-ConradNeural"}],"audio":"assets/podcasts/chapter-7.mp3?v=natural-dialogue-2","durationSeconds":688.49},{"chapter":8,"title":"Gut vorbereitet","duration":"11 Min.","speakers":["Klara","Yusuf"],"intro":"Lernen, Prüfungen und Präsentationen.","keywords":["Lernplan","wiederholen","Prüfung","Stichpunkte","auswendig"],"lines":[{"speaker":"Klara","de":"Willkommen zu Folge 8: Gut vorbereitet. Ich bin Klara, 42 Jahre alt.","ar":"مرحبًا بكم في الحلقة 8: Gut vorbereitet. أنا Klara وعمري 42 عامًا.","pauseAfter":0.5,"kind":"intro","start":0.0,"end":6.6},{"speaker":"Yusuf","de":"Und ich bin Yusuf, 23 Jahre alt. Heute sprechen wir über Lernen, Prüfungen, Präsentationen.","ar":"وأنا Yusuf وعمري 23 عامًا. سنتحدث اليوم عن موضوعات الدرس.","pauseAfter":0.6,"kind":"intro","start":7.1,"end":14.636},{"speaker":"Klara","de":"Hör zuerst entspannt zu. Danach wiederholen wir wichtige Wörter und Redemittel, und am Ende gibt es Fragen für dich.","ar":"استمع أولًا بهدوء. بعد ذلك سنراجع كلمات وتعبيرات مهمة، وفي النهاية توجد أسئلة لك.","pauseAfter":0.7,"kind":"intro","start":15.236,"end":22.868},{"speaker":"Yusuf","de":"Du kannst jederzeit pausieren, laut antworten und anschließend mit unserer Lösung vergleichen. Los geht es!","ar":"يمكنك إيقاف الحلقة والإجابة بصوت عالٍ ثم مقارنة إجابتك بحلنا. لنبدأ!","pauseAfter":1,"kind":"intro","start":23.568,"end":30.864},{"speaker":"Klara","de":"Yusuf, du hast nächste Woche deine Deutschprüfung. Wie bereitest du dich vor?","ar":"يوسف، لديك امتحان اللغة الألمانية الأسبوع المقبل. كيف تستعد؟","pauseAfter":0.55,"kind":"scene","start":31.864,"end":37.216},{"speaker":"Yusuf","de":"Ich habe einen Lernplan gemacht und wiederhole jeden Tag ein anderes Thema.","ar":"وضعت خطة للمذاكرة وأراجع كل يوم موضوعًا مختلفًا.","pauseAfter":0.55,"kind":"scene","start":37.766,"end":42.35},{"speaker":"Klara","de":"Lernst du die Wörter alle auswendig?","ar":"هل تحفظ جميع الكلمات عن ظهر قلب؟","pauseAfter":0.55,"kind":"scene","start":42.9,"end":45.636},{"speaker":"Yusuf","de":"Nicht nur. Ich schreibe Beispielsätze und benutze die Wörter beim Sprechen.","ar":"ليس فقط. أكتب جملًا مثالًا وأستخدم الكلمات أثناء التحدث.","pauseAfter":0.55,"kind":"scene","start":46.186,"end":51.514},{"speaker":"Klara","de":"Das ist sinnvoll. Was fällt dir noch schwer?","ar":"هذا مفيد. ما الذي ما زال صعبًا عليك؟","pauseAfter":0.55,"kind":"scene","start":52.064,"end":55.424},{"speaker":"Yusuf","de":"Bei Präsentationen werde ich nervös und spreche manchmal zu schnell.","ar":"أتوتر أثناء العروض وأتحدث بسرعة أحيانًا.","pauseAfter":0.55,"kind":"scene","start":55.974,"end":60.342},{"speaker":"Klara","de":"Schreib nur Stichpunkte auf deine Karten und übe vor einer anderen Person.","ar":"اكتب نقاطًا مختصرة فقط على بطاقاتك وتدرّب أمام شخص آخر.","pauseAfter":0.55,"kind":"scene","start":60.892,"end":65.404},{"speaker":"Yusuf","de":"Gute Idee. Damit ich sicherer werde, übe ich heute Abend vor meiner Schwester.","ar":"فكرة جيدة. لكي أصبح أكثر ثقة سأتدرب هذا المساء أمام أختي.","pauseAfter":0.55,"kind":"scene","start":65.954,"end":71.474},{"speaker":"Klara","de":"Zwei Tage vor der Prüfung treffen sich Klara und Yusuf in der Bibliothek.","ar":"قبل الامتحان بيومين تلتقي كلارا ويوسف في المكتبة.","pauseAfter":0.28,"kind":"scene","start":72.024,"end":76.56},{"speaker":"Yusuf","de":"Ich habe meinen Zeitplan eingehalten, aber der Wortschatz ist noch schwierig.","ar":"التزمت بخطة الوقت لكن المفردات ما زالت صعبة.","pauseAfter":0.28,"kind":"scene","start":76.84,"end":81.424},{"speaker":"Klara","de":"Lern nicht alles auswendig. Ordne die Wörter nach Themen.","ar":"لا تحفظ كل شيء فقط. رتب الكلمات حسب الموضوعات.","pauseAfter":0.28,"kind":"scene","start":81.704,"end":86.12},{"speaker":"Yusuf","de":"Ich habe Karteikarten gemacht, aber manchmal verwechsle ich die Artikel.","ar":"صنعت بطاقات لكنني أخلط أحيانًا بين أدوات التعريف.","pauseAfter":0.28,"kind":"scene","start":86.4,"end":90.792},{"speaker":"Klara","de":"Dann schreib der, die und das in verschiedenen Farben.","ar":"إذن اكتب der وdie وdas بألوان مختلفة.","pauseAfter":0.28,"kind":"scene","start":91.072,"end":94.648},{"speaker":"Yusuf","de":"Gute Idee. Im Wörterbuch schlage ich auch immer einen Beispielsatz nach.","ar":"فكرة جيدة. أبحث أيضًا عن جملة مثال في القاموس.","pauseAfter":0.28,"kind":"scene","start":94.928,"end":100.04},{"speaker":"Klara","de":"Nach vierzig Minuten solltest du eine kurze Pause machen.","ar":"بعد أربعين دقيقة ينبغي أن تأخذ استراحة قصيرة.","pauseAfter":0.28,"kind":"scene","start":100.32,"end":104.04},{"speaker":"Yusuf","de":"Ich habe Angst, dass ich in der Pause zu lange aufs Handy schaue.","ar":"أخشى أن أنظر إلى الهاتف طويلًا أثناء الاستراحة.","pauseAfter":0.28,"kind":"scene","start":104.32,"end":108.232},{"speaker":"Klara","de":"Stell einen Wecker auf zehn Minuten und leg das Handy danach weg.","ar":"اضبط منبهًا لعشر دقائق ثم ضع الهاتف بعيدًا.","pauseAfter":0.28,"kind":"scene","start":108.512,"end":112.784},{"speaker":"Yusuf","de":"Morgen muss ich außerdem meine Präsentation üben.","ar":"يجب عليّ أيضًا التدرب على العرض غدًا.","pauseAfter":0.28,"kind":"scene","start":113.064,"end":116.448},{"speaker":"Klara","de":"Sprich frei und benutze nur wenige Stichpunkte.","ar":"تحدث بحرية واستخدم نقاطًا مختصرة قليلة فقط.","pauseAfter":0.28,"kind":"scene","start":116.728,"end":120.064},{"speaker":"Yusuf","de":"Kannst du zuhören und mir danach eine ehrliche Rückmeldung geben?","ar":"هل يمكنك الاستماع وإعطائي رأيًا صريحًا بعدها؟","pauseAfter":0.28,"kind":"scene","start":120.344,"end":124.568},{"speaker":"Klara","de":"Natürlich. Achte besonders auf eine deutliche Aussprache und Blickkontakt.","ar":"بالطبع. انتبه خصوصًا إلى النطق الواضح والتواصل البصري.","pauseAfter":0.28,"kind":"scene","start":124.848,"end":130.2},{"speaker":"Yusuf","de":"Wenn ich einen Fehler mache, werde ich schnell nervös.","ar":"عندما أخطئ أتوتر بسرعة.","pauseAfter":0.28,"kind":"scene","start":130.48,"end":133.912},{"speaker":"Klara","de":"Fehler sind normal. Verbessere dich kurz und sprich einfach weiter.","ar":"الأخطاء طبيعية. صحح نفسك باختصار وواصل الكلام.","pauseAfter":0.28,"kind":"scene","start":134.192,"end":139.016},{"speaker":"Yusuf","de":"Danke. Mit diesem Plan fühle ich mich schon besser vorbereitet.","ar":"شكرًا. بهذه الخطة أشعر أنني مستعد بصورة أفضل.","pauseAfter":0.28,"kind":"scene","start":139.296,"end":144.048},{"speaker":"Klara","de":"Das war unsere erste Alltagsszene. Welche Wörter und Sätze hast du sofort verstanden?","ar":"كان هذا مشهدنا اليومي الأول. ما الكلمات والجمل التي فهمتها فورًا؟","pauseAfter":3.2,"kind":"interactive","start":144.328,"end":150.328},{"speaker":"Yusuf","de":"Denk kurz nach. Du musst nicht jedes Wort verstehen. Wichtig ist zuerst die Situation.","ar":"فكّر قليلًا. ليس ضروريًا أن تفهم كل كلمة؛ المهم أولًا هو فهم الموقف.","pauseAfter":2.4,"kind":"interactive","start":153.528,"end":160.392},{"speaker":"Klara","de":"Die Situation passt zu Kapitel 8. Jetzt sehen wir uns den Wortschatz genauer an.","ar":"الموقف مرتبط بالدرس 8. والآن سنراجع المفردات بدقة أكبر.","pauseAfter":0.8,"kind":"section","start":162.792,"end":168.528},{"speaker":"Klara","de":"Wort Nummer 1: lernen. Hör genau zu: lernen.","ar":"الكلمة رقم 1: يتعلم / يذاكر. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":169.328,"end":173.672},{"speaker":"Yusuf","de":"lernen bedeutet: Neues Wissen oder eine neue Fähigkeit bekommen. Ein Beispiel: Ich lerne seit einem Jahr Deutsch.","ar":"معنى lernen: يتعلم / يذاكر.","pauseAfter":0.6,"kind":"vocab","start":174.122,"end":181.682},{"speaker":"Klara","de":"Jetzt bist du dran. Sprich laut nach: lernen.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: lernen.","pauseAfter":1.8,"kind":"interactive","start":182.282,"end":186.074},{"speaker":"Yusuf","de":"Wort Nummer 2: die Prüfung, -en. Hör genau zu: die Prüfung, -en.","ar":"الكلمة رقم 2: امتحان. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":187.874,"end":193.706},{"speaker":"Klara","de":"die Prüfung, -en bedeutet: Ein Test: Man zeigt, was man kann und weiß. Ein Beispiel: Nächste Woche habe ich eine wichtige Prüfung.","ar":"معنى die Prüfung, -en: امتحان.","pauseAfter":0.6,"kind":"vocab","start":194.156,"end":203.828},{"speaker":"Yusuf","de":"Jetzt bist du dran. Sprich laut nach: die Prüfung, -en.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Prüfung, -en.","pauseAfter":1.8,"kind":"interactive","start":204.428,"end":209.276},{"speaker":"Klara","de":"Wort Nummer 3: bestehen. Hör genau zu: bestehen.","ar":"الكلمة رقم 3: ينجح في الامتحان. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":211.076,"end":215.78},{"speaker":"Yusuf","de":"bestehen bedeutet: Eine Prüfung mit Erfolg machen. Ein Beispiel: Sie hat die Prüfung beim ersten Mal bestanden.","ar":"معنى bestehen: ينجح في الامتحان.","pauseAfter":0.6,"kind":"vocab","start":216.23,"end":223.574},{"speaker":"Klara","de":"Jetzt bist du dran. Sprich laut nach: bestehen.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: bestehen.","pauseAfter":1.8,"kind":"interactive","start":224.174,"end":228.134},{"speaker":"Yusuf","de":"Wort Nummer 4: durchfallen. Hör genau zu: durchfallen.","ar":"الكلمة رقم 4: يرسب. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":229.934,"end":235.094},{"speaker":"Klara","de":"durchfallen bedeutet: Eine Prüfung nicht bestehen. Ein Beispiel: Er ist leider durch die Prüfung gefallen.","ar":"معنى durchfallen: يرسب.","pauseAfter":0.6,"kind":"vocab","start":235.544,"end":242.528},{"speaker":"Yusuf","de":"Jetzt bist du dran. Sprich laut nach: durchfallen.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: durchfallen.","pauseAfter":1.8,"kind":"interactive","start":243.128,"end":247.616},{"speaker":"Klara","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":249.416,"end":255.944},{"speaker":"Yusuf","de":"Die Wörter waren: lernen, die Prüfung, -en, bestehen, durchfallen.","ar":"الكلمات كانت: يتعلم / يذاكر، امتحان، ينجح في الامتحان، يرسب.","pauseAfter":1,"kind":"answer","start":258.944,"end":263.936},{"speaker":"Klara","de":"Wort Nummer 5: der Stoff. Hör genau zu: der Stoff.","ar":"الكلمة رقم 5: المنهج / المادة. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":264.936,"end":269.568},{"speaker":"Yusuf","de":"der Stoff bedeutet: Alles, was man für eine Prüfung lernen muss. Ein Beispiel: Der Stoff für den Test ist sehr viel.","ar":"معنى der Stoff: المنهج / المادة.","pauseAfter":0.6,"kind":"vocab","start":270.018,"end":277.866},{"speaker":"Klara","de":"Jetzt bist du dran. Sprich laut nach: der Stoff.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Stoff.","pauseAfter":1.8,"kind":"interactive","start":278.466,"end":282.426},{"speaker":"Yusuf","de":"Wort Nummer 6: auswendig lernen. Hör genau zu: auswendig lernen.","ar":"الكلمة رقم 6: يحفظ عن ظهر قلب. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":284.226,"end":290.034},{"speaker":"Klara","de":"auswendig lernen bedeutet: Etwas so lernen, dass man es ohne Buch sagen kann. Ein Beispiel: Ich lerne die Vokabeln auswendig.","ar":"معنى auswendig lernen: يحفظ عن ظهر قلب.","pauseAfter":0.6,"kind":"vocab","start":290.484,"end":299.34},{"speaker":"Yusuf","de":"Jetzt bist du dran. Sprich laut nach: auswendig lernen.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: auswendig lernen.","pauseAfter":1.8,"kind":"interactive","start":299.94,"end":304.884},{"speaker":"Klara","de":"Wort Nummer 7: wiederholen. Hör genau zu: wiederholen.","ar":"الكلمة رقم 7: يراجع / يعيد. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":306.684,"end":311.556},{"speaker":"Yusuf","de":"wiederholen bedeutet: Etwas noch einmal machen oder lernen. Ein Beispiel: Vor der Prüfung wiederhole ich die Grammatik.","ar":"معنى wiederholen: يراجع / يعيد.","pauseAfter":0.6,"kind":"vocab","start":312.006,"end":319.782},{"speaker":"Klara","de":"Jetzt bist du dran. Sprich laut nach: wiederholen.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: wiederholen.","pauseAfter":1.8,"kind":"interactive","start":320.382,"end":324.462},{"speaker":"Yusuf","de":"Wort Nummer 8: sich konzentrieren auf. Hör genau zu: sich konzentrieren auf.","ar":"الكلمة رقم 8: يركّز على. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":326.262,"end":332.214},{"speaker":"Klara","de":"sich konzentrieren auf bedeutet: Nur an eine Sache denken und genau arbeiten. Ein Beispiel: Bei Lärm kann ich mich nicht konzentrieren.","ar":"معنى sich konzentrieren auf: يركّز على.","pauseAfter":0.6,"kind":"vocab","start":332.664,"end":341.976},{"speaker":"Yusuf","de":"Jetzt bist du dran. Sprich laut nach: sich konzentrieren auf.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: sich konzentrieren auf.","pauseAfter":1.8,"kind":"interactive","start":342.576,"end":347.568},{"speaker":"Klara","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":349.368,"end":355.896},{"speaker":"Yusuf","de":"Die Wörter waren: der Stoff, auswendig lernen, wiederholen, sich konzentrieren auf.","ar":"الكلمات كانت: المنهج / المادة، يحفظ عن ظهر قلب، يراجع / يعيد، يركّز على.","pauseAfter":1,"kind":"answer","start":358.896,"end":364.488},{"speaker":"Klara","de":"Wort Nummer 9: sich vorbereiten auf. Hör genau zu: sich vorbereiten auf.","ar":"الكلمة رقم 9: يستعد لـ / يحضّر نفسه. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":365.488,"end":371.344},{"speaker":"Yusuf","de":"sich vorbereiten auf bedeutet: Vor einem Termin alles Nötige machen und lernen. Ein Beispiel: Ich bereite mich auf die B1-Prüfung vor.","ar":"معنى sich vorbereiten auf: يستعد لـ / يحضّر نفسه.","pauseAfter":0.6,"kind":"vocab","start":371.794,"end":381.01},{"speaker":"Klara","de":"Jetzt bist du dran. Sprich laut nach: sich vorbereiten auf.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: sich vorbereiten auf.","pauseAfter":1.8,"kind":"interactive","start":381.61,"end":386.218},{"speaker":"Yusuf","de":"Wort Nummer 10: die Pause, -n. Hör genau zu: die Pause, -n.","ar":"الكلمة رقم 10: استراحة / بريك. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":388.018,"end":392.938},{"speaker":"Klara","de":"die Pause, -n bedeutet: Eine kurze Zeit, in der man nicht arbeitet oder lernt. Ein Beispiel: Mach beim Lernen regelmäßig Pausen!","ar":"معنى die Pause, -n: استراحة / بريك.","pauseAfter":0.6,"kind":"vocab","start":393.388,"end":402.868},{"speaker":"Yusuf","de":"Jetzt bist du dran. Sprich laut nach: die Pause, -n.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Pause, -n.","pauseAfter":1.8,"kind":"interactive","start":403.468,"end":408.34},{"speaker":"Yusuf","de":"Sehr gut. Wörter allein reichen aber nicht. Im Gespräch brauchen wir fertige Sätze und passende Reaktionen.","ar":"جيد جدًا. الكلمات وحدها لا تكفي؛ في الحوار نحتاج إلى جمل جاهزة وردود مناسبة.","pauseAfter":0.8,"kind":"section","start":410.14,"end":418.156},{"speaker":"Klara","de":"Situation 1, Ratschläge geben. Was könntest du sagen?","ar":"الموقف رقم 1. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":418.956,"end":423.54},{"speaker":"Yusuf","de":"Eine passende Formulierung ist: Du solltest einen Zeitplan machen.","ar":"تعبير مناسب هو: المفروض تعمل جدول زمني.","pauseAfter":0.7,"kind":"phrase","start":425.74,"end":429.964},{"speaker":"Klara","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Du solltest einen Zeitplan machen.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":430.664,"end":436.04},{"speaker":"Yusuf","de":"Situation 2, Ratschläge geben. Was könntest du sagen?","ar":"الموقف رقم 2. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":438.24,"end":443.4},{"speaker":"Klara","de":"Eine passende Formulierung ist: Du solltest mit anderen zusammen lernen.","ar":"تعبير مناسب هو: المفروض تذاكر مع ناس تانية.","pauseAfter":0.7,"kind":"phrase","start":445.6,"end":450.28},{"speaker":"Yusuf","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Du solltest mit anderen zusammen lernen.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":450.98,"end":456.812},{"speaker":"Klara","de":"Situation 3, Ratschläge geben. Was könntest du sagen?","ar":"الموقف رقم 3. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":459.012,"end":463.572},{"speaker":"Yusuf","de":"Eine passende Formulierung ist: Mach mehr Pausen!","ar":"تعبير مناسب هو: خد بريكات أكتر!","pauseAfter":0.7,"kind":"phrase","start":465.772,"end":469.252},{"speaker":"Klara","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Mach mehr Pausen!","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":469.952,"end":474.8},{"speaker":"Yusuf","de":"Situation 4, Ratschläge geben. Was könntest du sagen?","ar":"الموقف رقم 4. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":477.0,"end":482.16},{"speaker":"Klara","de":"Eine passende Formulierung ist: Du kannst mit den Prüfenden sprechen.","ar":"تعبير مناسب هو: ممكن تتكلم مع الممتحنين.","pauseAfter":0.7,"kind":"phrase","start":484.36,"end":488.92},{"speaker":"Yusuf","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Du kannst mit den Prüfenden sprechen.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":489.62,"end":495.068},{"speaker":"Klara","de":"Situation 5, Ratschläge geben. Was könntest du sagen?","ar":"الموقف رقم 5. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":497.268,"end":501.852},{"speaker":"Yusuf","de":"Eine passende Formulierung ist: An deiner Stelle würde ich jeden Tag ein bisschen wiederholen.","ar":"تعبير مناسب هو: لو كنت مكانك كنت هراجع شوية كل يوم.","pauseAfter":0.7,"kind":"phrase","start":504.052,"end":509.332},{"speaker":"Klara","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: An deiner Stelle würde ich jeden Tag ein bisschen wiederholen.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":510.032,"end":516.848},{"speaker":"Yusuf","de":"Situation 6, Ratschläge geben. Was könntest du sagen?","ar":"الموقف رقم 6. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":519.048,"end":524.256},{"speaker":"Klara","de":"Eine passende Formulierung ist: Man sollte nicht alles am letzten Tag lernen.","ar":"تعبير مناسب هو: مينفعش الواحد يذاكر كل حاجة آخر يوم.","pauseAfter":0.7,"kind":"phrase","start":526.456,"end":531.28},{"speaker":"Yusuf","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Man sollte nicht alles am letzten Tag lernen.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":531.98,"end":537.956},{"speaker":"Klara","de":"Jetzt kommt ein kurzer Hör- und Grammatikcheck. Antworte zuerst selbst. Danach hörst du die Lösung.","ar":"والآن اختبار قصير في الاستماع والقواعد. أجب أولًا بنفسك ثم استمع إلى الحل.","pauseAfter":0.8,"kind":"section","start":540.156,"end":547.38},{"speaker":"Klara","de":"Frage 1: Du ___ mehr Pausen machen.","ar":"السؤال رقم 1. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":548.18,"end":552.932},{"speaker":"Klara","de":"Die Möglichkeiten sind: A, sollst. B, solltest. C, sollten.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":553.432,"end":559.456},{"speaker":"Yusuf","de":"Die richtige Antwort ist B: solltest. Ratschlag mit Konjunktiv II: du solltest.","ar":"الإجابة الصحيحة: النصيحة بـ solltest مع du.","pauseAfter":1,"kind":"answer","start":562.656,"end":569.136},{"speaker":"Yusuf","de":"Frage 2: ___ Film magst du am liebsten?","ar":"السؤال رقم 2. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":570.136,"end":574.96},{"speaker":"Yusuf","de":"Die Möglichkeiten sind: A, Was für ein. B, Was für einen. C, Was für einem.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":575.46,"end":582.708},{"speaker":"Klara","de":"Die richtige Antwort ist B: Was für einen. mögen + Akkusativ, der Film → Was für einen Film.","ar":"الإجابة الصحيحة: الفعل بياخد Akkusativ والفيلم مذكر → einen.","pauseAfter":1,"kind":"answer","start":585.908,"end":592.724},{"speaker":"Klara","de":"Frage 3: „die Prüfung bestehen“ bedeutet:","ar":"السؤال رقم 3. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":593.724,"end":597.276},{"speaker":"Klara","de":"Die Möglichkeiten sind: A, die Prüfung mit Erfolg machen. B, die Prüfung nicht schaffen. C, die Prüfung wiederholen.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":597.776,"end":606.368},{"speaker":"Yusuf","de":"Die richtige Antwort ist A: die Prüfung mit Erfolg machen. bestehen = Erfolg haben. Das Gegenteil: durchfallen.","ar":"الإجابة الصحيحة: bestehen = ينجح، وعكسها durchfallen = يرسب.","pauseAfter":1,"kind":"answer","start":609.568,"end":618.328},{"speaker":"Yusuf","de":"Frage 4: Womit beginnt eine gute Präsentation?","ar":"السؤال رقم 4. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":619.328,"end":623.36},{"speaker":"Yusuf","de":"Die Möglichkeiten sind: A, Mit dem Schluss. B, Mit der Einleitung. C, Mit den Fragen.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":623.86,"end":631.348},{"speaker":"Klara","de":"Die richtige Antwort ist B: Mit der Einleitung. Reihenfolge: Einleitung → Hauptteil → Schluss.","ar":"الإجابة الصحيحة: الترتيب: مقدمة ← موضوع ← خاتمة.","pauseAfter":1,"kind":"answer","start":634.548,"end":641.268},{"speaker":"Yusuf","de":"Zum Abschluss: Nenne drei neue Wörter aus Kapitel 8 und bilde mit jedem Wort einen Satz.","ar":"في الختام: اذكر ثلاث كلمات جديدة من الدرس 8 وكوّن جملة بكل كلمة.","pauseAfter":4,"kind":"interactive","start":642.268,"end":647.98},{"speaker":"Klara","de":"Wenn das noch schwer ist, höre die Folge morgen noch einmal. Beim zweiten Hören wirst du deutlich mehr verstehen.","ar":"إذا كان الأمر ما زال صعبًا، فاستمع إلى الحلقة غدًا مرة أخرى. في المرة الثانية ستفهم أكثر بوضوح.","pauseAfter":0.7,"kind":"outro","start":651.98,"end":658.988},{"speaker":"Yusuf","de":"Danke fürs Zuhören. Das war Gut vorbereitet. Bis zur nächsten Folge!","ar":"شكرًا على الاستماع. كانت هذه حلقة Gut vorbereitet. إلى الحلقة القادمة!","pauseAfter":1,"kind":"outro","start":659.688,"end":665.952}],"people":[{"name":"Klara","gender":"female","age":42,"voice":"de-DE-SeraphinaMultilingualNeural"},{"name":"Yusuf","gender":"male","age":23,"voice":"de-DE-KillianNeural"}],"audio":"assets/podcasts/chapter-8.mp3?v=natural-dialogue-2","durationSeconds":667.01},{"chapter":9,"title":"Training für das Finale","duration":"11 Min.","speakers":["Salma","David"],"intro":"Sport, Verein, Fans und Verabredungen.","keywords":["Mannschaft","Training","Wettkampf","anfeuern","durchhalten"],"lines":[{"speaker":"Salma","de":"Willkommen zu Folge 9: Training für das Finale. Ich bin Salma, 26 Jahre alt.","ar":"مرحبًا بكم في الحلقة 9: Training für das Finale. أنا Salma وعمري 26 عامًا.","pauseAfter":0.5,"kind":"intro","start":0.0,"end":6.744},{"speaker":"David","de":"Und ich bin David, 29 Jahre alt. Heute sprechen wir über Sport, Fans, Verabredungen.","ar":"وأنا David وعمري 29 عامًا. سنتحدث اليوم عن موضوعات الدرس.","pauseAfter":0.6,"kind":"intro","start":7.244,"end":13.628},{"speaker":"Salma","de":"Hör zuerst entspannt zu. Danach wiederholen wir wichtige Wörter und Redemittel, und am Ende gibt es Fragen für dich.","ar":"استمع أولًا بهدوء. بعد ذلك سنراجع كلمات وتعبيرات مهمة، وفي النهاية توجد أسئلة لك.","pauseAfter":0.7,"kind":"intro","start":14.228,"end":21.86},{"speaker":"David","de":"Du kannst jederzeit pausieren, laut antworten und anschließend mit unserer Lösung vergleichen. Los geht es!","ar":"يمكنك إيقاف الحلقة والإجابة بصوت عالٍ ثم مقارنة إجابتك بحلنا. لنبدأ!","pauseAfter":1,"kind":"intro","start":22.56,"end":28.632},{"speaker":"David","de":"Salma, warum gehst du heute so früh zum Sportplatz?","ar":"سلمى، لماذا تذهبين إلى الملعب مبكرًا اليوم؟","pauseAfter":0.55,"kind":"scene","start":29.632,"end":32.944},{"speaker":"Salma","de":"Unsere Mannschaft spielt am Wochenende im Finale. Deshalb trainieren wir heute länger.","ar":"سيلعب فريقنا في النهائي في عطلة نهاية الأسبوع. لذلك سنتدرب اليوم مدة أطول.","pauseAfter":0.55,"kind":"scene","start":33.494,"end":39.158},{"speaker":"David","de":"Bist du vor dem Wettkampf aufgeregt?","ar":"هل أنت متحمسة أو متوترة قبل المنافسة؟","pauseAfter":0.55,"kind":"scene","start":39.708,"end":41.964},{"speaker":"Salma","de":"Ein bisschen, obwohl wir in dieser Saison fast alle Spiele gewonnen haben.","ar":"قليلًا، رغم أننا فزنا تقريبًا بكل المباريات هذا الموسم.","pauseAfter":0.55,"kind":"scene","start":42.514,"end":46.834},{"speaker":"David","de":"Ich komme am Samstag und feuere euch an. Soll ich noch Freunde mitbringen?","ar":"سآتي يوم السبت لأشجعكم. هل أحضر أصدقاء أيضًا؟","pauseAfter":0.55,"kind":"scene","start":47.384,"end":51.776},{"speaker":"Salma","de":"Sehr gern! Je mehr Fans da sind, desto motivierter sind wir.","ar":"بكل سرور! كلما زاد عدد المشجعين زاد حماسنا.","pauseAfter":0.55,"kind":"scene","start":52.326,"end":56.982},{"speaker":"David","de":"Was macht ihr heute beim Training?","ar":"ماذا ستفعلون في التدريب اليوم؟","pauseAfter":0.55,"kind":"scene","start":57.532,"end":59.476},{"speaker":"Salma","de":"Wir wärmen uns zuerst auf, üben Pässe und trainieren unsere Ausdauer. Wir müssen bis zum Ende durchhalten.","ar":"سنقوم بالإحماء أولًا ونتدرب على التمريرات وعلى التحمل. يجب أن نصمد حتى النهاية.","pauseAfter":0.55,"kind":"scene","start":60.026,"end":67.298},{"speaker":"Salma","de":"Am Samstag beginnt das Finale, und David sitzt mit anderen Fans im Stadion.","ar":"يوم السبت تبدأ المباراة النهائية ويجلس ديفيد مع مشجعين آخرين في الملعب.","pauseAfter":0.28,"kind":"scene","start":67.848,"end":72.888},{"speaker":"David","de":"Salma, wir sind da! Eure Mannschaft läuft gerade auf den Platz.","ar":"سلمى، نحن هنا! فريقكم يدخل الملعب الآن.","pauseAfter":0.28,"kind":"scene","start":73.168,"end":77.488},{"speaker":"Salma","de":"Ich bin so aufgeregt. Wir haben uns lange auf diesen Wettkampf vorbereitet.","ar":"أنا متحمسة جدًا. استعددنا طويلًا لهذه المنافسة.","pauseAfter":0.28,"kind":"scene","start":77.768,"end":82.952},{"speaker":"David","de":"Die Fans feuern euch laut an. Das gibt bestimmt zusätzliche Energie.","ar":"المشجعون يشجعونكم بصوت عالٍ. هذا يمنحكم طاقة إضافية بالتأكيد.","pauseAfter":0.28,"kind":"scene","start":83.232,"end":87.624},{"speaker":"Salma","de":"In der ersten Hälfte müssen wir ruhig spielen und gut zusammenarbeiten.","ar":"في الشوط الأول يجب أن نلعب بهدوء ونتعاون جيدًا.","pauseAfter":0.28,"kind":"scene","start":87.904,"end":92.056},{"speaker":"David","de":"Eure Gegnerinnen sind schnell, aber eure Mannschaft hat mehr Ausdauer.","ar":"منافساتكم سريعات لكن فريقكم يملك قدرة تحمل أكبر.","pauseAfter":0.28,"kind":"scene","start":92.336,"end":96.248},{"speaker":"Salma","de":"Da kommt der erste Pass. Jetzt haben wir eine gute Chance!","ar":"ها هي التمريرة الأولى. لدينا فرصة جيدة الآن!","pauseAfter":0.28,"kind":"scene","start":96.528,"end":100.608},{"speaker":"David","de":"Tor! Unglaublich, das war großartig!","ar":"هدف! لا يصدق، كان رائعًا!","pauseAfter":0.28,"kind":"scene","start":100.888,"end":104.176},{"speaker":"Salma","de":"Wir dürfen uns nicht zu früh freuen. Das Spiel dauert noch lange.","ar":"يجب ألا نفرح مبكرًا. المباراة ما زالت طويلة.","pauseAfter":0.28,"kind":"scene","start":104.456,"end":108.872},{"speaker":"David","de":"Nach der Pause steht es eins zu eins. Wie fühlst du dich?","ar":"بعد الاستراحة النتيجة واحد لواحد. كيف تشعرين؟","pauseAfter":0.28,"kind":"scene","start":109.152,"end":112.896},{"speaker":"Salma","de":"Müde, aber ich will bis zum Ende durchhalten.","ar":"متعبة، لكنني أريد الصمود حتى النهاية.","pauseAfter":0.28,"kind":"scene","start":113.176,"end":116.44},{"speaker":"David","de":"Wir glauben an euch. Das nächste Tor klappt bestimmt.","ar":"نحن نؤمن بكم. الهدف التالي سينجح بالتأكيد.","pauseAfter":0.28,"kind":"scene","start":116.72,"end":120.296},{"speaker":"Salma","de":"Noch eine Minute. Unsere Stürmerin schießt und trifft!","ar":"بقيت دقيقة واحدة. مهاجمتنا تسدد وتصيب الهدف!","pauseAfter":0.28,"kind":"scene","start":120.576,"end":124.848},{"speaker":"David","de":"Ihr habt gewonnen! Die ganze Tribüne jubelt.","ar":"لقد فزتم! المدرج كله يهتف.","pauseAfter":0.28,"kind":"scene","start":125.128,"end":128.44},{"speaker":"Salma","de":"Was für ein Sieg. Jetzt bin ich einfach nur stolz auf die Mannschaft.","ar":"يا له من فوز. أنا الآن فخورة فقط بالفريق.","pauseAfter":0.28,"kind":"scene","start":128.72,"end":133.352},{"speaker":"David","de":"Kommt nachher zu uns. Wir möchten gemeinsam mit euch feiern.","ar":"تعالوا إلينا بعد المباراة. نريد الاحتفال معكم.","pauseAfter":0.28,"kind":"scene","start":133.632,"end":137.4},{"speaker":"Salma","de":"Das war unsere erste Alltagsszene. Welche Wörter und Sätze hast du sofort verstanden?","ar":"كان هذا مشهدنا اليومي الأول. ما الكلمات والجمل التي فهمتها فورًا؟","pauseAfter":3.2,"kind":"interactive","start":137.68,"end":143.68},{"speaker":"David","de":"Denk kurz nach. Du musst nicht jedes Wort verstehen. Wichtig ist zuerst die Situation.","ar":"فكّر قليلًا. ليس ضروريًا أن تفهم كل كلمة؛ المهم أولًا هو فهم الموقف.","pauseAfter":2.4,"kind":"interactive","start":146.88,"end":152.616},{"speaker":"Salma","de":"Die Situation passt zu Kapitel 9. Jetzt sehen wir uns den Wortschatz genauer an.","ar":"الموقف مرتبط بالدرس 9. والآن سنراجع المفردات بدقة أكبر.","pauseAfter":0.8,"kind":"section","start":155.016,"end":160.656},{"speaker":"Salma","de":"Wort Nummer 1: der Sport. Hör genau zu: der Sport.","ar":"الكلمة رقم 1: الرياضة. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":161.456,"end":166.232},{"speaker":"David","de":"der Sport bedeutet: Körperliche Aktivität wie Fußball, Schwimmen oder Laufen. Ein Beispiel: Sport ist gut für die Gesundheit.","ar":"معنى der Sport: الرياضة.","pauseAfter":0.6,"kind":"vocab","start":166.682,"end":174.242},{"speaker":"Salma","de":"Jetzt bist du dran. Sprich laut nach: der Sport.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Sport.","pauseAfter":1.8,"kind":"interactive","start":174.842,"end":178.874},{"speaker":"David","de":"Wort Nummer 2: die Sportart, -en. Hör genau zu: die Sportart, -en.","ar":"الكلمة رقم 2: نوع رياضة. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":180.674,"end":186.482},{"speaker":"Salma","de":"die Sportart, -en bedeutet: Eine Art von Sport, z. B. Tennis oder Schwimmen. Ein Beispiel: Welche Sportart machst du am liebsten?","ar":"معنى die Sportart, -en: نوع رياضة.","pauseAfter":0.6,"kind":"vocab","start":186.932,"end":196.34},{"speaker":"David","de":"Jetzt bist du dran. Sprich laut nach: die Sportart, -en.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Sportart, -en.","pauseAfter":1.8,"kind":"interactive","start":196.94,"end":201.212},{"speaker":"Salma","de":"Wort Nummer 3: der Verein, -e. Hör genau zu: der Verein, -e.","ar":"الكلمة رقم 3: نادي. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":203.012,"end":208.052},{"speaker":"David","de":"der Verein, -e bedeutet: Eine Gruppe von Menschen mit demselben Hobby oder Ziel. Ein Beispiel: Mein Sohn spielt Fußball im Verein.","ar":"معنى der Verein, -e: نادي.","pauseAfter":0.6,"kind":"vocab","start":208.502,"end":216.59},{"speaker":"Salma","de":"Jetzt bist du dran. Sprich laut nach: der Verein, -e.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Verein, -e.","pauseAfter":1.8,"kind":"interactive","start":217.19,"end":221.606},{"speaker":"David","de":"Wort Nummer 4: das Training. Hör genau zu: das Training.","ar":"الكلمة رقم 4: التمرين / التدريب. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":223.406,"end":228.038},{"speaker":"Salma","de":"das Training bedeutet: Regelmäßiges Üben im Sport. Ein Beispiel: Wir haben zweimal pro Woche Training.","ar":"معنى das Training: التمرين / التدريب.","pauseAfter":0.6,"kind":"vocab","start":228.488,"end":236.048},{"speaker":"David","de":"Jetzt bist du dran. Sprich laut nach: das Training.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: das Training.","pauseAfter":1.8,"kind":"interactive","start":236.648,"end":240.296},{"speaker":"Salma","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":242.096,"end":248.624},{"speaker":"David","de":"Die Wörter waren: der Sport, die Sportart, -en, der Verein, -e, das Training.","ar":"الكلمات كانت: الرياضة، نوع رياضة، نادي، التمرين / التدريب.","pauseAfter":1,"kind":"answer","start":251.624,"end":257.12},{"speaker":"Salma","de":"Wort Nummer 5: trainieren. Hör genau zu: trainieren.","ar":"الكلمة رقم 5: يتمرن. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":258.12,"end":263.016},{"speaker":"David","de":"trainieren bedeutet: Sport machen, um besser oder fitter zu werden. Ein Beispiel: Sie trainiert jeden Tag für den Marathon.","ar":"معنى trainieren: يتمرن.","pauseAfter":0.6,"kind":"vocab","start":263.466,"end":270.762},{"speaker":"Salma","de":"Jetzt bist du dran. Sprich laut nach: trainieren.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: trainieren.","pauseAfter":1.8,"kind":"interactive","start":271.362,"end":275.394},{"speaker":"David","de":"Wort Nummer 6: die Mannschaft, -en. Hör genau zu: die Mannschaft, -en.","ar":"الكلمة رقم 6: الفريق. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":277.194,"end":283.074},{"speaker":"Salma","de":"die Mannschaft, -en bedeutet: Eine Gruppe von Sportlern, die zusammen spielt; das Team. Ein Beispiel: Unsere Mannschaft hat heute gewonnen!","ar":"معنى die Mannschaft, -en: الفريق.","pauseAfter":0.6,"kind":"vocab","start":283.524,"end":292.908},{"speaker":"David","de":"Jetzt bist du dran. Sprich laut nach: die Mannschaft, -en.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Mannschaft, -en.","pauseAfter":1.8,"kind":"interactive","start":293.508,"end":297.708},{"speaker":"Salma","de":"Wort Nummer 7: der Fan, -s. Hör genau zu: der Fan, -s.","ar":"الكلمة رقم 7: مشجع. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":299.508,"end":304.548},{"speaker":"David","de":"der Fan, -s bedeutet: Eine Person, die ein Team oder einen Star sehr toll findet. Ein Beispiel: Die Fans singen im Stadion.","ar":"معنى der Fan, -s: مشجع.","pauseAfter":0.6,"kind":"vocab","start":304.998,"end":313.014},{"speaker":"Salma","de":"Jetzt bist du dran. Sprich laut nach: der Fan, -s.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Fan, -s.","pauseAfter":1.8,"kind":"interactive","start":313.614,"end":317.982},{"speaker":"David","de":"Wort Nummer 8: das Spiel, -e. Hör genau zu: das Spiel, -e.","ar":"الكلمة رقم 8: المباراة / الماتش. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":319.782,"end":324.75},{"speaker":"Salma","de":"das Spiel, -e bedeutet: Ein sportlicher Wettkampf zwischen zwei Teams. Ein Beispiel: Das Spiel beginnt um 18 Uhr.","ar":"معنى das Spiel, -e: المباراة / الماتش.","pauseAfter":0.6,"kind":"vocab","start":325.2,"end":334.08},{"speaker":"David","de":"Jetzt bist du dran. Sprich laut nach: das Spiel, -e.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: das Spiel, -e.","pauseAfter":1.8,"kind":"interactive","start":334.68,"end":338.736},{"speaker":"Salma","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":340.536,"end":347.064},{"speaker":"David","de":"Die Wörter waren: trainieren, die Mannschaft, -en, der Fan, -s, das Spiel, -e.","ar":"الكلمات كانت: يتمرن، الفريق، مشجع، المباراة / الماتش.","pauseAfter":1,"kind":"answer","start":350.064,"end":355.608},{"speaker":"Salma","de":"Wort Nummer 9: das Stadion, Stadien. Hör genau zu: das Stadion, Stadien.","ar":"الكلمة رقم 9: الإستاد. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":356.608,"end":363.208},{"speaker":"David","de":"das Stadion, Stadien bedeutet: Ein großer Platz mit vielen Sitzen für Sport. Ein Beispiel: Im Stadion waren 50.000 Zuschauer.","ar":"معنى das Stadion, Stadien: الإستاد.","pauseAfter":0.6,"kind":"vocab","start":363.658,"end":371.842},{"speaker":"Salma","de":"Jetzt bist du dran. Sprich laut nach: das Stadion, Stadien.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: das Stadion, Stadien.","pauseAfter":1.8,"kind":"interactive","start":372.442,"end":377.458},{"speaker":"David","de":"Wort Nummer 10: gewinnen. Hör genau zu: gewinnen.","ar":"الكلمة رقم 10: يكسب / يفوز. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":379.258,"end":383.434},{"speaker":"Salma","de":"gewinnen bedeutet: In einem Spiel oder Wettkampf der/die Beste sein. Ein Beispiel: Wer hat das Spiel gewonnen?","ar":"معنى gewinnen: يكسب / يفوز.","pauseAfter":0.6,"kind":"vocab","start":383.884,"end":391.204},{"speaker":"David","de":"Jetzt bist du dran. Sprich laut nach: gewinnen.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: gewinnen.","pauseAfter":1.8,"kind":"interactive","start":391.804,"end":395.308},{"speaker":"David","de":"Sehr gut. Wörter allein reichen aber nicht. Im Gespräch brauchen wir fertige Sätze und passende Reaktionen.","ar":"جيد جدًا. الكلمات وحدها لا تكفي؛ في الحوار نحتاج إلى جمل جاهزة وردود مناسبة.","pauseAfter":0.8,"kind":"section","start":397.108,"end":403.972},{"speaker":"Salma","de":"Situation 1, Begeisterung ausdrücken. Was könntest du sagen?","ar":"الموقف رقم 1. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":404.772,"end":409.596},{"speaker":"David","de":"Eine passende Formulierung ist: So toll! Das war großartig!","ar":"تعبير مناسب هو: رائع جدًا! كان عظيمًا!","pauseAfter":0.7,"kind":"phrase","start":411.796,"end":416.212},{"speaker":"Salma","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: So toll! Das war großartig!","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":416.912,"end":422.984},{"speaker":"David","de":"Situation 2, Begeisterung ausdrücken. Was könntest du sagen?","ar":"الموقف رقم 2. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":425.184,"end":429.528},{"speaker":"Salma","de":"Eine passende Formulierung ist: Wahnsinn! Einfach mega!","ar":"تعبير مناسب هو: جنان! حاجة خرافية!","pauseAfter":0.7,"kind":"phrase","start":431.728,"end":436.168},{"speaker":"David","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Wahnsinn! Einfach mega!","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":436.868,"end":441.98},{"speaker":"Salma","de":"Situation 3, Begeisterung ausdrücken. Was könntest du sagen?","ar":"الموقف رقم 3. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":444.18,"end":449.052},{"speaker":"David","de":"Eine passende Formulierung ist: Unglaublich – einfach genial!","ar":"تعبير مناسب هو: مش معقول — عبقري ببساطة!","pauseAfter":0.7,"kind":"phrase","start":451.252,"end":455.356},{"speaker":"Salma","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Unglaublich – einfach genial!","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":456.056,"end":461.576},{"speaker":"David","de":"Situation 4, Begeisterung ausdrücken. Was könntest du sagen?","ar":"الموقف رقم 4. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":463.776,"end":468.168},{"speaker":"Salma","de":"Eine passende Formulierung ist: Ich glaub' es nicht, das ist super!","ar":"تعبير مناسب هو: مش مصدق، ده شيء سوبر!","pauseAfter":0.7,"kind":"phrase","start":470.368,"end":474.952},{"speaker":"David","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Ich glaub' es nicht, das ist super!","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":475.652,"end":480.812},{"speaker":"Salma","de":"Situation 5, Hoffnung ausdrücken. Was könntest du sagen?","ar":"الموقف رقم 5. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":483.012,"end":487.716},{"speaker":"David","de":"Eine passende Formulierung ist: Ich habe ein gutes Gefühl!","ar":"تعبير مناسب هو: عندي إحساس كويس!","pauseAfter":0.7,"kind":"phrase","start":489.916,"end":493.492},{"speaker":"Salma","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Ich habe ein gutes Gefühl!","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":494.192,"end":499.544},{"speaker":"David","de":"Situation 6, Hoffnung ausdrücken. Was könntest du sagen?","ar":"الموقف رقم 6. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":501.744,"end":505.992},{"speaker":"Salma","de":"Eine passende Formulierung ist: Das nächste Mal klappt es bestimmt.","ar":"تعبير مناسب هو: المرة الجاية هتنجح أكيد.","pauseAfter":0.7,"kind":"phrase","start":508.192,"end":512.608},{"speaker":"David","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Das nächste Mal klappt es bestimmt.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":513.308,"end":518.276},{"speaker":"Salma","de":"Jetzt kommt ein kurzer Hör- und Grammatikcheck. Antworte zuerst selbst. Danach hörst du die Lösung.","ar":"والآن اختبار قصير في الاستماع والقواعد. أجب أولًا بنفسك ثم استمع إلى الحل.","pauseAfter":0.8,"kind":"section","start":520.476,"end":527.7},{"speaker":"Salma","de":"Frage 1: Alle spielen schlecht, ___ haben sie gewonnen.","ar":"السؤال رقم 1. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":528.5,"end":534.188},{"speaker":"Salma","de":"Die Möglichkeiten sind: A, deshalb. B, trotzdem. C, weil.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":534.688,"end":540.592},{"speaker":"David","de":"Die richtige Antwort ist B: trotzdem. Kontrast (unerwartet!) → trotzdem.","ar":"الإجابة الصحيحة: حاجة عكس المتوقع → trotzdem.","pauseAfter":1,"kind":"answer","start":543.792,"end":549.744},{"speaker":"David","de":"Frage 2: Es regnet stark, ___ bleiben wir zu Hause.","ar":"السؤال رقم 2. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":550.744,"end":555.976},{"speaker":"David","de":"Die Möglichkeiten sind: A, deshalb. B, trotzdem. C, ob.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":556.476,"end":561.804},{"speaker":"Salma","de":"Die richtige Antwort ist A: deshalb. Logische Folge → deshalb.","ar":"الإجابة الصحيحة: نتيجة منطقية → deshalb.","pauseAfter":1,"kind":"answer","start":565.004,"end":570.044},{"speaker":"Salma","de":"Frage 3: Wir erklären ___ die Regeln.","ar":"السؤال رقم 3. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":571.044,"end":576.036},{"speaker":"Salma","de":"Die Möglichkeiten sind: A, den Gästen. B, die Gäste. C, der Gäste.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":576.536,"end":583.064},{"speaker":"David","de":"Die richtige Antwort ist A: den Gästen. Person im Dativ: den Gästen (Plural-Dativ mit -n).","ar":"الإجابة الصحيحة: الشخص في Dativ، والجمع بياخد n.","pauseAfter":1,"kind":"answer","start":586.264,"end":593.488},{"speaker":"David","de":"Frage 4: Die Helme? Wir leihen ___ euch.","ar":"السؤال رقم 4. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":594.488,"end":599.552},{"speaker":"David","de":"Die Möglichkeiten sind: A, sie. B, ihnen. C, es.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":600.052,"end":604.852},{"speaker":"Salma","de":"Die richtige Antwort ist A: sie. Akkusativ-Pronomen (die Helme → sie) steht vor dem Dativ.","ar":"الإجابة الصحيحة: الضمير sie (بدل الخوذات) بييجي قبل euch.","pauseAfter":1,"kind":"answer","start":608.052,"end":615.18},{"speaker":"David","de":"Zum Abschluss: Nenne drei neue Wörter aus Kapitel 9 und bilde mit jedem Wort einen Satz.","ar":"في الختام: اذكر ثلاث كلمات جديدة من الدرس 9 وكوّن جملة بكل كلمة.","pauseAfter":4,"kind":"interactive","start":616.18,"end":621.22},{"speaker":"Salma","de":"Wenn das noch schwer ist, höre die Folge morgen noch einmal. Beim zweiten Hören wirst du deutlich mehr verstehen.","ar":"إذا كان الأمر ما زال صعبًا، فاستمع إلى الحلقة غدًا مرة أخرى. في المرة الثانية ستفهم أكثر بوضوح.","pauseAfter":0.7,"kind":"outro","start":625.22,"end":632.228},{"speaker":"David","de":"Danke fürs Zuhören. Das war Training für das Finale. Bis zur nächsten Folge!","ar":"شكرًا على الاستماع. كانت هذه حلقة Training für das Finale. إلى الحلقة القادمة!","pauseAfter":1,"kind":"outro","start":632.928,"end":638.208}],"people":[{"name":"Salma","gender":"female","age":26,"voice":"de-DE-SeraphinaMultilingualNeural"},{"name":"David","gender":"male","age":29,"voice":"de-DE-FlorianMultilingualNeural"}],"audio":"assets/podcasts/chapter-9.mp3?v=natural-dialogue-2","durationSeconds":639.26},{"chapter":10,"title":"Neue Nachbarn","duration":"11 Min.","speakers":["Hanna","Rami"],"intro":"Wohnen, Nachbarn, Umzug und Zusammenleben.","keywords":["Nachbar","umziehen","Hausordnung","Rücksicht","Gefallen"],"lines":[{"speaker":"Hanna","de":"Willkommen zu Folge 10: Neue Nachbarn. Ich bin Hanna, 51 Jahre alt.","ar":"مرحبًا بكم في الحلقة 10: Neue Nachbarn. أنا Hanna وعمري 51 عامًا.","pauseAfter":0.5,"kind":"intro","start":0.0,"end":6.048},{"speaker":"Rami","de":"Und ich bin Rami, 38 Jahre alt. Heute sprechen wir über Wohnen, Nachbarn, Umziehen, Tiere.","ar":"وأنا Rami وعمري 38 عامًا. سنتحدث اليوم عن موضوعات الدرس.","pauseAfter":0.6,"kind":"intro","start":6.548,"end":14.252},{"speaker":"Hanna","de":"Hör zuerst entspannt zu. Danach wiederholen wir wichtige Wörter und Redemittel, und am Ende gibt es Fragen für dich.","ar":"استمع أولًا بهدوء. بعد ذلك سنراجع كلمات وتعبيرات مهمة، وفي النهاية توجد أسئلة لك.","pauseAfter":0.7,"kind":"intro","start":14.852,"end":22.484},{"speaker":"Rami","de":"Du kannst jederzeit pausieren, laut antworten und anschließend mit unserer Lösung vergleichen. Los geht es!","ar":"يمكنك إيقاف الحلقة والإجابة بصوت عالٍ ثم مقارنة إجابتك بحلنا. لنبدأ!","pauseAfter":1,"kind":"intro","start":23.184,"end":30.456},{"speaker":"Hanna","de":"Hallo, ich bin Hanna aus dem zweiten Stock. Seid ihr gestern eingezogen?","ar":"مرحبًا، أنا هانا من الطابق الثاني. هل انتقلتم للسكن أمس؟","pauseAfter":0.55,"kind":"scene","start":31.456,"end":36.592},{"speaker":"Rami","de":"Ja, wir sind die neuen Nachbarn. In der Wohnung stehen noch überall Kartons.","ar":"نعم، نحن الجيران الجدد. لا تزال الصناديق موجودة في كل مكان بالشقة.","pauseAfter":0.55,"kind":"scene","start":37.142,"end":42.59},{"speaker":"Hanna","de":"Wenn ihr Hilfe braucht, sagt einfach Bescheid. Ich kann euch gern einen Gefallen tun.","ar":"إذا احتجتم إلى المساعدة فأخبروني ببساطة. يسعدني أن أقدم لكم خدمة.","pauseAfter":0.55,"kind":"scene","start":43.14,"end":48.804},{"speaker":"Rami","de":"Danke! Kannst du mir erklären, wann hier die Ruhezeiten sind?","ar":"شكرًا! هل يمكنك أن توضحي لي متى تكون أوقات الهدوء هنا؟","pauseAfter":0.55,"kind":"scene","start":49.354,"end":54.37},{"speaker":"Hanna","de":"Laut Hausordnung soll es nach zehn Uhr abends ruhig sein.","ar":"وفقًا لقواعد المبنى يجب أن يسود الهدوء بعد الساعة العاشرة مساءً.","pauseAfter":0.55,"kind":"scene","start":54.92,"end":58.544},{"speaker":"Rami","de":"Kein Problem. Wir nehmen Rücksicht auf die anderen Bewohner.","ar":"لا مشكلة. سنراعي السكان الآخرين.","pauseAfter":0.55,"kind":"scene","start":59.094,"end":63.798},{"speaker":"Hanna","de":"Am Freitag treffen sich einige Nachbarn im Hof. Kommt doch auch vorbei.","ar":"يوم الجمعة سيلتقي بعض الجيران في الفناء. تعالوا أنتم أيضًا.","pauseAfter":0.55,"kind":"scene","start":64.348,"end":69.244},{"speaker":"Rami","de":"Sehr gern. So können wir gleich alle kennenlernen.","ar":"بكل سرور. وهكذا يمكننا التعرف على الجميع مباشرة.","pauseAfter":0.55,"kind":"scene","start":69.794,"end":74.162},{"speaker":"Hanna","de":"Am Freitag kommt Rami zum ersten Treffen der Nachbarn in den Hof.","ar":"يوم الجمعة يأتي رامي إلى أول لقاء للجيران في الفناء.","pauseAfter":0.28,"kind":"scene","start":74.712,"end":78.888},{"speaker":"Rami","de":"Schön, dass du da bist. Hast du dich in der neuen Wohnung schon eingerichtet?","ar":"جميل أنك هنا. هل رتبت الشقة الجديدة بالفعل؟","pauseAfter":0.28,"kind":"scene","start":79.168,"end":84.76},{"speaker":"Hanna","de":"Fast. Einige Kartons stehen noch im Keller, und ein Regal fehlt.","ar":"تقريبًا. ما زالت بعض الصناديق في القبو وينقصنا رف.","pauseAfter":0.28,"kind":"scene","start":85.04,"end":89.84},{"speaker":"Rami","de":"Mein Mann hat Werkzeug. Er kann dir morgen beim Aufbau helfen.","ar":"زوجي لديه أدوات ويمكنه مساعدتك غدًا في التركيب.","pauseAfter":0.28,"kind":"scene","start":90.12,"end":95.04},{"speaker":"Hanna","de":"Das wäre ein großer Gefallen. Dafür gieße ich gern eure Blumen im Urlaub.","ar":"ستكون هذه خدمة كبيرة. وفي المقابل يسعدني سقي زهوركم في الإجازة.","pauseAfter":0.28,"kind":"scene","start":95.32,"end":100.576},{"speaker":"Rami","de":"Danke. Wir suchen sowieso jemanden, der auch den Briefkasten leert.","ar":"شكرًا. نحن نبحث أصلًا عمن يفرغ صندوق البريد أيضًا.","pauseAfter":0.28,"kind":"scene","start":100.856,"end":106.304},{"speaker":"Hanna","de":"Kein Problem. Sag mir einfach, wann ihr wegfahrt.","ar":"لا مشكلة. أخبريني فقط متى ستسافرون.","pauseAfter":0.28,"kind":"scene","start":106.584,"end":110.544},{"speaker":"Rami","de":"Übrigens hat sich gestern jemand über Lärm im Treppenhaus beschwert.","ar":"بالمناسبة اشتكى شخص أمس من الضوضاء في بيت الدرج.","pauseAfter":0.28,"kind":"scene","start":110.824,"end":115.024},{"speaker":"Hanna","de":"Das waren wahrscheinlich wir beim Auspacken. Das tut mir leid.","ar":"غالبًا كنا نحن أثناء تفريغ الصناديق. أنا آسف.","pauseAfter":0.28,"kind":"scene","start":115.304,"end":119.576},{"speaker":"Rami","de":"Es war noch vor der Ruhezeit. Aber abends sollte es leiser sein.","ar":"كان ذلك قبل وقت الهدوء، لكن يجب أن يكون الصوت أخفض مساءً.","pauseAfter":0.28,"kind":"scene","start":119.856,"end":124.8},{"speaker":"Hanna","de":"Natürlich. Wir nehmen Rücksicht und tragen die restlichen Möbel am Vormittag.","ar":"بالطبع. سنراعي الآخرين وننقل بقية الأثاث صباحًا.","pauseAfter":0.28,"kind":"scene","start":125.08,"end":130.456},{"speaker":"Rami","de":"Dann gibt es sicher kein Problem mit der Hausordnung.","ar":"إذن لن تكون هناك مشكلة مع قواعد المبنى.","pauseAfter":0.28,"kind":"scene","start":130.736,"end":134.072},{"speaker":"Hanna","de":"Ich finde es gut, dass man hier offen miteinander sprechen kann.","ar":"يعجبني أن الناس هنا يستطيعون التحدث بصراحة.","pauseAfter":0.28,"kind":"scene","start":134.352,"end":138.24},{"speaker":"Rami","de":"Eine gute Nachbarschaft beginnt mit freundlichen Gesprächen.","ar":"الجيرة الجيدة تبدأ بمحادثات ودية.","pauseAfter":0.28,"kind":"scene","start":138.52,"end":142.336},{"speaker":"Hanna","de":"Da stimme ich zu. Ich bringe beim nächsten Treffen etwas zu essen mit.","ar":"أوافق. سأحضر طعامًا في اللقاء القادم.","pauseAfter":0.28,"kind":"scene","start":142.616,"end":147.272},{"speaker":"Rami","de":"Sehr gern. Dann lernst du auch die Nachbarn aus dem dritten Stock kennen.","ar":"بكل سرور. وستتعرف أيضًا على جيران الطابق الثالث.","pauseAfter":0.28,"kind":"scene","start":147.552,"end":152.664},{"speaker":"Hanna","de":"Das war unsere erste Alltagsszene. Welche Wörter und Sätze hast du sofort verstanden?","ar":"كان هذا مشهدنا اليومي الأول. ما الكلمات والجمل التي فهمتها فورًا؟","pauseAfter":3.2,"kind":"interactive","start":152.944,"end":158.944},{"speaker":"Rami","de":"Denk kurz nach. Du musst nicht jedes Wort verstehen. Wichtig ist zuerst die Situation.","ar":"فكّر قليلًا. ليس ضروريًا أن تفهم كل كلمة؛ المهم أولًا هو فهم الموقف.","pauseAfter":2.4,"kind":"interactive","start":162.144,"end":169.152},{"speaker":"Hanna","de":"Die Situation passt zu Kapitel 10. Jetzt sehen wir uns den Wortschatz genauer an.","ar":"الموقف مرتبط بالدرس 10. والآن سنراجع المفردات بدقة أكبر.","pauseAfter":0.8,"kind":"section","start":171.552,"end":177.24},{"speaker":"Hanna","de":"Wort Nummer 1: der Nachbar, -n. Hör genau zu: der Nachbar, -n.","ar":"الكلمة رقم 1: الجار. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":178.04,"end":183.176},{"speaker":"Rami","de":"der Nachbar, -n bedeutet: Die Person, die neben dir wohnt. (n-Deklination!) Ein Beispiel: Unsere Nachbarn sind sehr freundlich.","ar":"معنى der Nachbar, -n: الجار.","pauseAfter":0.6,"kind":"vocab","start":183.626,"end":193.37},{"speaker":"Hanna","de":"Jetzt bist du dran. Sprich laut nach: der Nachbar, -n.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Nachbar, -n.","pauseAfter":1.8,"kind":"interactive","start":193.97,"end":198.482},{"speaker":"Rami","de":"Wort Nummer 2: die Nachbarschaft. Hör genau zu: die Nachbarschaft.","ar":"الكلمة رقم 2: الجيرة / الحي. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":200.282,"end":205.778},{"speaker":"Hanna","de":"die Nachbarschaft bedeutet: Alle Nachbarn zusammen; die Gegend um dein Haus. Ein Beispiel: In unserer Nachbarschaft helfen sich alle.","ar":"معنى die Nachbarschaft: الجيرة / الحي.","pauseAfter":0.6,"kind":"vocab","start":206.228,"end":214.916},{"speaker":"Rami","de":"Jetzt bist du dran. Sprich laut nach: die Nachbarschaft.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Nachbarschaft.","pauseAfter":1.8,"kind":"interactive","start":215.516,"end":220.388},{"speaker":"Hanna","de":"Wort Nummer 3: der Mieter, -. Hör genau zu: der Mieter, -.","ar":"الكلمة رقم 3: المستأجر. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":222.188,"end":227.396},{"speaker":"Rami","de":"der Mieter, - bedeutet: Eine Person, die eine Wohnung mietet und Miete bezahlt. Ein Beispiel: Die Mieter treffen sich im Hof.","ar":"معنى der Mieter, -: المستأجر.","pauseAfter":0.6,"kind":"vocab","start":227.846,"end":236.246},{"speaker":"Hanna","de":"Jetzt bist du dran. Sprich laut nach: der Mieter, -.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Mieter, -.","pauseAfter":1.8,"kind":"interactive","start":236.846,"end":241.118},{"speaker":"Rami","de":"Wort Nummer 4: der Vermieter, -. Hör genau zu: der Vermieter, -.","ar":"الكلمة رقم 4: المؤجّر / صاحب البيت. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":242.918,"end":248.174},{"speaker":"Hanna","de":"der Vermieter, - bedeutet: Die Person, der die Wohnung gehört. Sie bekommt die Miete. Ein Beispiel: Der Vermieter hat die Heizung repariert.","ar":"معنى der Vermieter, -: المؤجّر / صاحب البيت.","pauseAfter":0.6,"kind":"vocab","start":248.624,"end":258.584},{"speaker":"Rami","de":"Jetzt bist du dran. Sprich laut nach: der Vermieter, -.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Vermieter, -.","pauseAfter":1.8,"kind":"interactive","start":259.184,"end":263.888},{"speaker":"Hanna","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":265.688,"end":272.216},{"speaker":"Rami","de":"Die Wörter waren: der Nachbar, -n, die Nachbarschaft, der Mieter, -, der Vermieter, -.","ar":"الكلمات كانت: الجار، الجيرة / الحي، المستأجر، المؤجّر / صاحب البيت.","pauseAfter":1,"kind":"answer","start":275.216,"end":280.904},{"speaker":"Hanna","de":"Wort Nummer 5: die Miete, -n. Hör genau zu: die Miete, -n.","ar":"الكلمة رقم 5: الإيجار. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":281.904,"end":287.04},{"speaker":"Rami","de":"die Miete, -n bedeutet: Das Geld, das man jeden Monat für die Wohnung bezahlt. Ein Beispiel: Die Miete ist in der Stadt sehr hoch.","ar":"معنى die Miete, -n: الإيجار.","pauseAfter":0.6,"kind":"vocab","start":287.49,"end":296.178},{"speaker":"Hanna","de":"Jetzt bist du dran. Sprich laut nach: die Miete, -n.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Miete, -n.","pauseAfter":1.8,"kind":"interactive","start":296.778,"end":301.17},{"speaker":"Rami","de":"Wort Nummer 6: der Lärm. Hör genau zu: der Lärm.","ar":"الكلمة رقم 6: الضوضاء / الدوشة. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":302.97,"end":307.818},{"speaker":"Hanna","de":"der Lärm bedeutet: Laute, unangenehme Geräusche. Ein Beispiel: Der Lärm von der Straße stört mich beim Schlafen.","ar":"معنى der Lärm: الضوضاء / الدوشة.","pauseAfter":0.6,"kind":"vocab","start":308.268,"end":316.452},{"speaker":"Rami","de":"Jetzt bist du dran. Sprich laut nach: der Lärm.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Lärm.","pauseAfter":1.8,"kind":"interactive","start":317.052,"end":321.54},{"speaker":"Hanna","de":"Wort Nummer 7: laut / leise. Hör genau zu: laut / leise.","ar":"الكلمة رقم 7: عالي الصوت / هادئ. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":323.34,"end":328.716},{"speaker":"Rami","de":"laut / leise bedeutet: laut = mit viel Lärm; leise = fast ohne Geräusch. Ein Beispiel: Bitte sei leise, das Baby schläft!","ar":"معنى laut / leise: عالي الصوت / هادئ.","pauseAfter":0.6,"kind":"vocab","start":329.166,"end":338.382},{"speaker":"Hanna","de":"Jetzt bist du dran. Sprich laut nach: laut / leise.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: laut / leise.","pauseAfter":1.8,"kind":"interactive","start":338.982,"end":343.398},{"speaker":"Rami","de":"Wort Nummer 8: sich beschweren bei … über …. Hör genau zu: sich beschweren bei … über ….","ar":"الكلمة رقم 8: يشتكي لـ... من.... استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":345.198,"end":351.846},{"speaker":"Hanna","de":"sich beschweren bei … über … bedeutet: Sagen, dass man mit etwas nicht zufrieden ist. Ein Beispiel: Ich beschwere mich beim Vermieter über den Lärm.","ar":"معنى sich beschweren bei … über …: يشتكي لـ... من....","pauseAfter":0.6,"kind":"vocab","start":352.296,"end":362.304},{"speaker":"Rami","de":"Jetzt bist du dran. Sprich laut nach: sich beschweren bei … über ….","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: sich beschweren bei … über ….","pauseAfter":1.8,"kind":"interactive","start":362.904,"end":368.256},{"speaker":"Hanna","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":370.056,"end":376.584},{"speaker":"Rami","de":"Die Wörter waren: die Miete, -n, der Lärm, laut / leise, sich beschweren bei … über ….","ar":"الكلمات كانت: الإيجار، الضوضاء / الدوشة، عالي الصوت / هادئ، يشتكي لـ... من....","pauseAfter":1,"kind":"answer","start":379.584,"end":385.872},{"speaker":"Hanna","de":"Wort Nummer 9: stören. Hör genau zu: stören.","ar":"الكلمة رقم 9: يزعج / يضايق. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":386.872,"end":391.48},{"speaker":"Rami","de":"stören bedeutet: Eine Person bei etwas unterbrechen oder ihr Probleme machen. Ein Beispiel: Es stört mich, wenn die Musik so laut ist.","ar":"معنى stören: يزعج / يضايق.","pauseAfter":0.6,"kind":"vocab","start":391.93,"end":400.69},{"speaker":"Hanna","de":"Jetzt bist du dran. Sprich laut nach: stören.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: stören.","pauseAfter":1.8,"kind":"interactive","start":401.29,"end":405.274},{"speaker":"Rami","de":"Wort Nummer 10: sich entschuldigen. Hör genau zu: sich entschuldigen.","ar":"الكلمة رقم 10: يعتذر. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":407.074,"end":412.69},{"speaker":"Hanna","de":"sich entschuldigen bedeutet: „Entschuldigung“ sagen, wenn man einen Fehler gemacht hat. Ein Beispiel: Er hat sich für den Lärm entschuldigt.","ar":"معنى sich entschuldigen: يعتذر.","pauseAfter":0.6,"kind":"vocab","start":413.14,"end":421.756},{"speaker":"Rami","de":"Jetzt bist du dran. Sprich laut nach: sich entschuldigen.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: sich entschuldigen.","pauseAfter":1.8,"kind":"interactive","start":422.356,"end":427.204},{"speaker":"Rami","de":"Sehr gut. Wörter allein reichen aber nicht. Im Gespräch brauchen wir fertige Sätze und passende Reaktionen.","ar":"جيد جدًا. الكلمات وحدها لا تكفي؛ في الحوار نحتاج إلى جمل جاهزة وردود مناسبة.","pauseAfter":0.8,"kind":"section","start":429.004,"end":437.164},{"speaker":"Hanna","de":"Situation 1, Um einen Gefallen bitten. Was könntest du sagen?","ar":"الموقف رقم 1. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":437.964,"end":442.86},{"speaker":"Rami","de":"Eine passende Formulierung ist: Könnten Sie mir einen Gefallen tun?","ar":"تعبير مناسب هو: ممكن حضرتك تعمل لي معروف؟","pauseAfter":0.7,"kind":"phrase","start":445.06,"end":449.452},{"speaker":"Hanna","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Könnten Sie mir einen Gefallen tun?","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":450.152,"end":455.864},{"speaker":"Rami","de":"Situation 2, Um einen Gefallen bitten. Was könntest du sagen?","ar":"الموقف رقم 2. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":458.064,"end":463.44},{"speaker":"Hanna","de":"Eine passende Formulierung ist: Könntest du meine Blumen gießen?","ar":"تعبير مناسب هو: ممكن تسقي الزرع بتاعي؟","pauseAfter":0.7,"kind":"phrase","start":465.64,"end":469.72},{"speaker":"Rami","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Könntest du meine Blumen gießen?","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":470.42,"end":475.772},{"speaker":"Hanna","de":"Situation 3, Um einen Gefallen bitten. Was könntest du sagen?","ar":"الموقف رقم 3. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":477.972,"end":482.796},{"speaker":"Rami","de":"Eine passende Formulierung ist: Ich wollte Sie fragen, ob Sie meinen Briefkasten leeren könnten.","ar":"تعبير مناسب هو: كنت عايز أسأل حضرتك إذا كان ممكن تفضّي صندوق بريدي.","pauseAfter":0.7,"kind":"phrase","start":484.996,"end":490.756},{"speaker":"Hanna","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Ich wollte Sie fragen, ob Sie meinen Briefkasten leeren könnten.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":491.456,"end":498.56},{"speaker":"Rami","de":"Situation 4, Um einen Gefallen bitten. Was könntest du sagen?","ar":"الموقف رقم 4. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":500.76,"end":506.136},{"speaker":"Hanna","de":"Eine passende Formulierung ist: Ich hätte eine Bitte: …","ar":"تعبير مناسب هو: عندي طلب: ...","pauseAfter":0.7,"kind":"phrase","start":508.336,"end":512.128},{"speaker":"Rami","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Ich hätte eine Bitte: …","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":512.828,"end":517.532},{"speaker":"Hanna","de":"Situation 5, Auf eine Bitte reagieren. Was könntest du sagen?","ar":"الموقف رقم 5. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":519.732,"end":524.916},{"speaker":"Rami","de":"Eine passende Formulierung ist: Ja, gerne. / Kein Problem!","ar":"تعبير مناسب هو: أيوه، بكل سرور. / مفيش مشكلة!","pauseAfter":0.7,"kind":"phrase","start":527.116,"end":532.348},{"speaker":"Hanna","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Ja, gerne. / Kein Problem!","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":533.048,"end":538.976},{"speaker":"Rami","de":"Situation 6, Auf eine Bitte reagieren. Was könntest du sagen?","ar":"الموقف رقم 6. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":541.176,"end":546.72},{"speaker":"Hanna","de":"Eine passende Formulierung ist: Natürlich, das mache ich gern.","ar":"تعبير مناسب هو: طبعًا، بعمل ده بكل سرور.","pauseAfter":0.7,"kind":"phrase","start":548.92,"end":553.288},{"speaker":"Rami","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Natürlich, das mache ich gern.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":553.988,"end":559.46},{"speaker":"Hanna","de":"Jetzt kommt ein kurzer Hör- und Grammatikcheck. Antworte zuerst selbst. Danach hörst du die Lösung.","ar":"والآن اختبار قصير في الاستماع والقواعد. أجب أولًا بنفسك ثم استمع إلى الحل.","pauseAfter":0.8,"kind":"section","start":561.66,"end":568.884},{"speaker":"Hanna","de":"Frage 1: Die Lampe hängt ___ Tisch.","ar":"السؤال رقم 1. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":569.684,"end":574.436},{"speaker":"Hanna","de":"Die Möglichkeiten sind: A, über den. B, über dem. C, über das.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":574.936,"end":581.08},{"speaker":"Rami","de":"Die richtige Antwort ist B: über dem. Wo? (Position) → Dativ: über dem Tisch.","ar":"الإجابة الصحيحة: مكان ثابت → Dativ.","pauseAfter":1,"kind":"answer","start":584.28,"end":591.36},{"speaker":"Rami","de":"Frage 2: Sie stellt das Fahrrad ___ Garage.","ar":"السؤال رقم 2. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":592.36,"end":597.304},{"speaker":"Rami","de":"Die Möglichkeiten sind: A, in der. B, in die. C, in das.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":597.804,"end":604.356},{"speaker":"Hanna","de":"Die richtige Antwort ist B: in die. Wohin? (Richtung) → Akkusativ: in die Garage.","ar":"الإجابة الصحيحة: حركة واتجاه → Akkusativ.","pauseAfter":1,"kind":"answer","start":607.556,"end":614.3},{"speaker":"Hanna","de":"Frage 3: Das Buch ___ auf dem Tisch.","ar":"السؤال رقم 3. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":615.3,"end":620.22},{"speaker":"Hanna","de":"Die Möglichkeiten sind: A, legt. B, liegt. C, stellt.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":620.72,"end":626.528},{"speaker":"Rami","de":"Die richtige Antwort ist B: liegt. Position → liegen. (legen = Aktion!)","ar":"الإجابة الصحيحة: وضع ثابت → liegen.","pauseAfter":1,"kind":"answer","start":629.728,"end":636.448},{"speaker":"Rami","de":"Frage 4: ___ ich 14 Jahre alt war, sind wir nach Kairo gezogen.","ar":"السؤال رقم 4. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":637.448,"end":643.64},{"speaker":"Rami","de":"Die Möglichkeiten sind: A, Wenn. B, Als. C, Ob.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":644.14,"end":650.188},{"speaker":"Hanna","de":"Die richtige Antwort ist B: Als. Einmaliges Ereignis in der Vergangenheit → als.","ar":"الإجابة الصحيحة: حدث مرة واحدة في الماضي → als.","pauseAfter":1,"kind":"answer","start":653.388,"end":659.508},{"speaker":"Rami","de":"Zum Abschluss: Nenne drei neue Wörter aus Kapitel 10 und bilde mit jedem Wort einen Satz.","ar":"في الختام: اذكر ثلاث كلمات جديدة من الدرس 10 وكوّن جملة بكل كلمة.","pauseAfter":4,"kind":"interactive","start":660.508,"end":666.148},{"speaker":"Hanna","de":"Wenn das noch schwer ist, höre die Folge morgen noch einmal. Beim zweiten Hören wirst du deutlich mehr verstehen.","ar":"إذا كان الأمر ما زال صعبًا، فاستمع إلى الحلقة غدًا مرة أخرى. في المرة الثانية ستفهم أكثر بوضوح.","pauseAfter":0.7,"kind":"outro","start":670.148,"end":677.156},{"speaker":"Rami","de":"Danke fürs Zuhören. Das war Neue Nachbarn. Bis zur nächsten Folge!","ar":"شكرًا على الاستماع. كانت هذه حلقة Neue Nachbarn. إلى الحلقة القادمة!","pauseAfter":1,"kind":"outro","start":677.856,"end":684.048}],"people":[{"name":"Hanna","gender":"female","age":51,"voice":"de-DE-SeraphinaMultilingualNeural"},{"name":"Rami","gender":"male","age":38,"voice":"de-DE-ConradNeural"}],"audio":"assets/podcasts/chapter-10.mp3?v=natural-dialogue-2","durationSeconds":685.1},{"chapter":11,"title":"Mehr Zeit für mich","duration":"10 Min.","speakers":["Julia","Karim"],"intro":"Zeit, Gewohnheiten, Wünsche und Pläne.","keywords":["Zeitdruck","Gewohnheit","verschieben","sich vornehmen","verwirklichen"],"lines":[{"speaker":"Julia","de":"Willkommen zu Folge 11: Mehr Zeit für mich. Ich bin Julia, 44 Jahre alt.","ar":"مرحبًا بكم في الحلقة 11: Mehr Zeit für mich. أنا Julia وعمري 44 عامًا.","pauseAfter":0.5,"kind":"intro","start":0.0,"end":6.48},{"speaker":"Karim","de":"Und ich bin Karim, 46 Jahre alt. Heute sprechen wir über Zeit, Wünsche, Pläne.","ar":"وأنا Karim وعمري 46 عامًا. سنتحدث اليوم عن موضوعات الدرس.","pauseAfter":0.6,"kind":"intro","start":6.98,"end":13.268},{"speaker":"Julia","de":"Hör zuerst entspannt zu. Danach wiederholen wir wichtige Wörter und Redemittel, und am Ende gibt es Fragen für dich.","ar":"استمع أولًا بهدوء. بعد ذلك سنراجع كلمات وتعبيرات مهمة، وفي النهاية توجد أسئلة لك.","pauseAfter":0.7,"kind":"intro","start":13.868,"end":21.5},{"speaker":"Karim","de":"Du kannst jederzeit pausieren, laut antworten und anschließend mit unserer Lösung vergleichen. Los geht es!","ar":"يمكنك إيقاف الحلقة والإجابة بصوت عالٍ ثم مقارنة إجابتك بحلنا. لنبدأ!","pauseAfter":1,"kind":"intro","start":22.2,"end":28.44},{"speaker":"Julia","de":"Karim, du wirkst in letzter Zeit so gestresst. Hast du zu viele Termine?","ar":"كريم، تبدو متوترًا جدًا مؤخرًا. هل لديك مواعيد كثيرة؟","pauseAfter":0.55,"kind":"scene","start":29.44,"end":34.816},{"speaker":"Karim","de":"Ja. Nach der Arbeit erledige ich noch viele Dinge und habe kaum Zeit für mich.","ar":"نعم. بعد العمل أنجز أشياء كثيرة ولا أجد وقتًا لنفسي تقريبًا.","pauseAfter":0.55,"kind":"scene","start":35.366,"end":39.998},{"speaker":"Julia","de":"Ich kenne das. Früher habe ich meine Pausen immer verschoben.","ar":"أعرف ذلك. في السابق كنت أؤجل فترات راحتي دائمًا.","pauseAfter":0.55,"kind":"scene","start":40.548,"end":44.748},{"speaker":"Karim","de":"Was hast du geändert?","ar":"ماذا غيّرتِ؟","pauseAfter":0.55,"kind":"scene","start":45.298,"end":46.882},{"speaker":"Julia","de":"Ich trage freie Zeit in meinen Kalender ein und schalte am Abend das Handy aus.","ar":"أدوّن وقت الفراغ في تقويمي وأغلق الهاتف مساءً.","pauseAfter":0.55,"kind":"scene","start":47.432,"end":52.664},{"speaker":"Karim","de":"Das möchte ich auch versuchen. Ich nehme mir vor, zweimal pro Woche spazieren zu gehen.","ar":"أريد تجربة ذلك أيضًا. أنوي المشي مرتين في الأسبوع.","pauseAfter":0.55,"kind":"scene","start":53.214,"end":58.398},{"speaker":"Julia","de":"Sehr gut. Kleine regelmäßige Gewohnheiten sind oft besser als große Pläne.","ar":"جيد جدًا. العادات الصغيرة المنتظمة غالبًا أفضل من الخطط الكبيرة.","pauseAfter":0.55,"kind":"scene","start":58.948,"end":64.396},{"speaker":"Karim","de":"Stimmt. Vielleicht kann ich so meinen Wunsch nach mehr Ruhe endlich verwirklichen.","ar":"صحيح. ربما أستطيع هكذا تحقيق رغبتي في مزيد من الهدوء أخيرًا.","pauseAfter":0.55,"kind":"scene","start":64.946,"end":69.434},{"speaker":"Julia","de":"Eine Woche später sprechen Julia und Karim darüber, ob ihr neuer Plan funktioniert.","ar":"بعد أسبوع تتحدث يوليا وكريم عما إذا كانت خطتهما الجديدة نجحت.","pauseAfter":0.28,"kind":"scene","start":69.984,"end":75.24},{"speaker":"Karim","de":"Ich habe zwei Spaziergänge geschafft und drei Abende das Handy ausgeschaltet.","ar":"نجحت في المشي مرتين وأغلقت الهاتف ثلاث أمسيات.","pauseAfter":0.28,"kind":"scene","start":75.52,"end":79.744},{"speaker":"Julia","de":"Das klingt gut. Hattest du dadurch wirklich weniger Stress?","ar":"هذا جيد. هل أصبح لديك ضغط أقل فعلًا؟","pauseAfter":0.28,"kind":"scene","start":80.024,"end":84.272},{"speaker":"Karim","de":"Ja. Die Zeit ist langsamer vergangen, weil ich nicht ständig Nachrichten gelesen habe.","ar":"نعم. مر الوقت ببطء أكثر لأنني لم أقرأ الرسائل باستمرار.","pauseAfter":0.28,"kind":"scene","start":84.552,"end":89.64},{"speaker":"Julia","de":"Ich verbringe meinen Feierabend jetzt öfter mit einem Buch.","ar":"أقضي وقتي بعد العمل الآن غالبًا مع كتاب.","pauseAfter":0.28,"kind":"scene","start":89.92,"end":93.52},{"speaker":"Karim","de":"Früher wollte ich auch mehr lesen, aber ich habe es immer verschoben.","ar":"كنت أريد أيضًا القراءة أكثر لكنني كنت أؤجل ذلك دائمًا.","pauseAfter":0.28,"kind":"scene","start":93.8,"end":97.544},{"speaker":"Julia","de":"Man braucht ein konkretes Ziel. Wie viele Seiten möchtest du täglich lesen?","ar":"يحتاج المرء إلى هدف محدد. كم صفحة تريد قراءتها يوميًا؟","pauseAfter":0.28,"kind":"scene","start":97.824,"end":103.056},{"speaker":"Karim","de":"Zehn Seiten sind realistisch. Eine Stunde wäre wahrscheinlich zu viel.","ar":"عشر صفحات واقعية. ساعة كاملة ستكون كثيرة غالبًا.","pauseAfter":0.28,"kind":"scene","start":103.336,"end":107.752},{"speaker":"Julia","de":"Und was machst du mit Terminen, die nicht wirklich wichtig sind?","ar":"وماذا تفعل بالمواعيد غير المهمة فعلًا؟","pauseAfter":0.28,"kind":"scene","start":108.032,"end":111.656},{"speaker":"Karim","de":"Ich sage öfter ab oder schlage einen anderen Tag vor.","ar":"أعتذر عنها أكثر أو أقترح يومًا آخر.","pauseAfter":0.28,"kind":"scene","start":111.936,"end":115.152},{"speaker":"Julia","de":"Das ist nicht unhöflich. Du musst deine eigene Zeit auch schützen.","ar":"هذا ليس غير مهذب. يجب أن تحمي وقتك أيضًا.","pauseAfter":0.28,"kind":"scene","start":115.432,"end":119.992},{"speaker":"Karim","de":"Mein großer Wunsch ist eine Reise, für die ich bisher nie Zeit hatte.","ar":"رغبتي الكبيرة رحلة لم أجد لها وقتًا من قبل.","pauseAfter":0.28,"kind":"scene","start":120.272,"end":124.04},{"speaker":"Julia","de":"Trag sie jetzt in den Kalender ein, sonst bleibt sie nur ein Traum.","ar":"سجلها الآن في التقويم وإلا ستبقى مجرد حلم.","pauseAfter":0.28,"kind":"scene","start":124.32,"end":128.376},{"speaker":"Karim","de":"Du hast recht. Im September würde ich gern eine Woche ans Meer fahren.","ar":"معك حق. أود السفر أسبوعًا إلى البحر في سبتمبر.","pauseAfter":0.28,"kind":"scene","start":128.656,"end":132.976},{"speaker":"Julia","de":"Dann kannst du jeden Monat etwas Geld und freie Zeit dafür planen.","ar":"يمكنك إذن التخطيط كل شهر لبعض المال والوقت الحر.","pauseAfter":0.28,"kind":"scene","start":133.256,"end":137.504},{"speaker":"Karim","de":"So wird aus einem Wunsch langsam ein erreichbares Ziel.","ar":"وهكذا تتحول الرغبة تدريجيًا إلى هدف يمكن تحقيقه.","pauseAfter":0.28,"kind":"scene","start":137.784,"end":141.048},{"speaker":"Julia","de":"Das war unsere erste Alltagsszene. Welche Wörter und Sätze hast du sofort verstanden?","ar":"كان هذا مشهدنا اليومي الأول. ما الكلمات والجمل التي فهمتها فورًا؟","pauseAfter":3.2,"kind":"interactive","start":141.328,"end":147.328},{"speaker":"Karim","de":"Denk kurz nach. Du musst nicht jedes Wort verstehen. Wichtig ist zuerst die Situation.","ar":"فكّر قليلًا. ليس ضروريًا أن تفهم كل كلمة؛ المهم أولًا هو فهم الموقف.","pauseAfter":2.4,"kind":"interactive","start":150.528,"end":156.408},{"speaker":"Julia","de":"Die Situation passt zu Kapitel 11. Jetzt sehen wir uns den Wortschatz genauer an.","ar":"الموقف مرتبط بالدرس 11. والآن سنراجع المفردات بدقة أكبر.","pauseAfter":0.8,"kind":"section","start":158.808,"end":164.496},{"speaker":"Julia","de":"Wort Nummer 1: die Zeit. Hör genau zu: die Zeit.","ar":"الكلمة رقم 1: الوقت. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":165.296,"end":169.928},{"speaker":"Karim","de":"die Zeit bedeutet: Minuten, Stunden, Tage … Man kann sie nicht kaufen! Ein Beispiel: Ich habe heute leider keine Zeit.","ar":"معنى die Zeit: الوقت.","pauseAfter":0.6,"kind":"vocab","start":170.378,"end":178.706},{"speaker":"Julia","de":"Jetzt bist du dran. Sprich laut nach: die Zeit.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Zeit.","pauseAfter":1.8,"kind":"interactive","start":179.306,"end":183.266},{"speaker":"Karim","de":"Wort Nummer 2: die Freizeit. Hör genau zu: die Freizeit.","ar":"الكلمة رقم 2: وقت الفراغ. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":185.066,"end":189.89},{"speaker":"Julia","de":"die Freizeit bedeutet: Die Zeit ohne Arbeit oder Schule. Ein Beispiel: In meiner Freizeit lese ich gern.","ar":"معنى die Freizeit: وقت الفراغ.","pauseAfter":0.6,"kind":"vocab","start":190.34,"end":198.02},{"speaker":"Karim","de":"Jetzt bist du dran. Sprich laut nach: die Freizeit.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Freizeit.","pauseAfter":1.8,"kind":"interactive","start":198.62,"end":202.412},{"speaker":"Julia","de":"Wort Nummer 3: vergehen. Hör genau zu: vergehen.","ar":"الكلمة رقم 3: يمضي / يعدي (الوقت). استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":204.212,"end":208.988},{"speaker":"Karim","de":"vergehen bedeutet: Die Zeit läuft und ist dann vorbei. Ein Beispiel: Wie schnell die Zeit vergeht!","ar":"معنى vergehen: يمضي / يعدي (الوقت).","pauseAfter":0.6,"kind":"vocab","start":209.438,"end":215.654},{"speaker":"Julia","de":"Jetzt bist du dran. Sprich laut nach: vergehen.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: vergehen.","pauseAfter":1.8,"kind":"interactive","start":216.254,"end":220.334},{"speaker":"Karim","de":"Wort Nummer 4: verbringen. Hör genau zu: verbringen.","ar":"الكلمة رقم 4: يقضي (وقت). استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":222.134,"end":226.55},{"speaker":"Julia","de":"verbringen bedeutet: Zeit an einem Ort oder mit einer Aktivität sein. Ein Beispiel: Wir verbringen das Wochenende am Meer.","ar":"معنى verbringen: يقضي (وقت).","pauseAfter":0.6,"kind":"vocab","start":227.0,"end":235.688},{"speaker":"Karim","de":"Jetzt bist du dran. Sprich laut nach: verbringen.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: verbringen.","pauseAfter":1.8,"kind":"interactive","start":236.288,"end":239.936},{"speaker":"Julia","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":241.736,"end":248.264},{"speaker":"Karim","de":"Die Wörter waren: die Zeit, die Freizeit, vergehen, verbringen.","ar":"الكلمات كانت: الوقت، وقت الفراغ، يمضي / يعدي (الوقت)، يقضي (وقت).","pauseAfter":1,"kind":"answer","start":251.264,"end":255.824},{"speaker":"Julia","de":"Wort Nummer 5: der Stress. Hör genau zu: der Stress.","ar":"الكلمة رقم 5: الضغط / التوتر. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":256.824,"end":261.624},{"speaker":"Karim","de":"der Stress bedeutet: Zu viel Arbeit, zu wenig Zeit – man fühlt sich nicht gut. Ein Beispiel: Ich habe im Moment viel Stress im Job.","ar":"معنى der Stress: الضغط / التوتر.","pauseAfter":0.6,"kind":"vocab","start":262.074,"end":270.33},{"speaker":"Julia","de":"Jetzt bist du dran. Sprich laut nach: der Stress.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Stress.","pauseAfter":1.8,"kind":"interactive","start":270.93,"end":274.962},{"speaker":"Karim","de":"Wort Nummer 6: stressig. Hör genau zu: stressig.","ar":"الكلمة رقم 6: مرهق / مضغوط. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":276.762,"end":281.058},{"speaker":"Julia","de":"stressig bedeutet: Mit viel Stress. Ein Beispiel: Heute war ein stressiger Tag.","ar":"معنى stressig: مرهق / مضغوط.","pauseAfter":0.6,"kind":"vocab","start":281.508,"end":287.916},{"speaker":"Karim","de":"Jetzt bist du dran. Sprich laut nach: stressig.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: stressig.","pauseAfter":1.8,"kind":"interactive","start":288.516,"end":292.116},{"speaker":"Julia","de":"Wort Nummer 7: der Termin, -e. Hör genau zu: der Termin, -e.","ar":"الكلمة رقم 7: ميعاد / موعد رسمي. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":293.916,"end":298.98},{"speaker":"Karim","de":"der Termin, -e bedeutet: Eine feste Zeit für ein Treffen, z. B. beim Arzt. Ein Beispiel: Ich habe morgen einen Termin beim Zahnarzt.","ar":"معنى der Termin, -e: ميعاد / موعد رسمي.","pauseAfter":0.6,"kind":"vocab","start":299.43,"end":308.502},{"speaker":"Julia","de":"Jetzt bist du dran. Sprich laut nach: der Termin, -e.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Termin, -e.","pauseAfter":1.8,"kind":"interactive","start":309.102,"end":313.542},{"speaker":"Karim","de":"Wort Nummer 8: der Kalender, -. Hör genau zu: der Kalender, -.","ar":"الكلمة رقم 8: النتيجة / الأجندة. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":315.342,"end":321.006},{"speaker":"Julia","de":"der Kalender, - bedeutet: Hier schreibt man Termine und Tage auf. Ein Beispiel: Der Termin steht in meinem Kalender.","ar":"معنى der Kalender, -: النتيجة / الأجندة.","pauseAfter":0.6,"kind":"vocab","start":321.456,"end":329.976},{"speaker":"Karim","de":"Jetzt bist du dran. Sprich laut nach: der Kalender, -.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Kalender, -.","pauseAfter":1.8,"kind":"interactive","start":330.576,"end":334.728},{"speaker":"Julia","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":336.528,"end":343.056},{"speaker":"Karim","de":"Die Wörter waren: der Stress, stressig, der Termin, -e, der Kalender, -.","ar":"الكلمات كانت: الضغط / التوتر، مرهق / مضغوط، ميعاد / موعد رسمي، النتيجة / الأجندة.","pauseAfter":1,"kind":"answer","start":346.056,"end":351.456},{"speaker":"Julia","de":"Wort Nummer 9: planen. Hör genau zu: planen.","ar":"الكلمة رقم 9: يخطط. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":352.456,"end":356.992},{"speaker":"Karim","de":"planen bedeutet: Vorher überlegen, was und wann man etwas macht. Ein Beispiel: Wir planen eine Party für Samstag.","ar":"معنى planen: يخطط.","pauseAfter":0.6,"kind":"vocab","start":357.442,"end":365.074},{"speaker":"Julia","de":"Jetzt bist du dran. Sprich laut nach: planen.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: planen.","pauseAfter":1.8,"kind":"interactive","start":365.674,"end":369.61},{"speaker":"Karim","de":"Wort Nummer 10: der Plan, ⸚e. Hör genau zu: der Plan, ⸚e.","ar":"الكلمة رقم 10: خطة. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":371.41,"end":376.69},{"speaker":"Julia","de":"der Plan, ⸚e bedeutet: Eine Idee, was man machen will. Ein Beispiel: Hast du schon Pläne fürs Wochenende?","ar":"معنى der Plan, ⸚e: خطة.","pauseAfter":0.6,"kind":"vocab","start":377.14,"end":384.676},{"speaker":"Karim","de":"Jetzt bist du dran. Sprich laut nach: der Plan, ⸚e.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Plan, ⸚e.","pauseAfter":1.8,"kind":"interactive","start":385.276,"end":389.404},{"speaker":"Karim","de":"Sehr gut. Wörter allein reichen aber nicht. Im Gespräch brauchen wir fertige Sätze und passende Reaktionen.","ar":"جيد جدًا. الكلمات وحدها لا تكفي؛ في الحوار نحتاج إلى جمل جاهزة وردود مناسبة.","pauseAfter":0.8,"kind":"section","start":391.204,"end":398.26},{"speaker":"Julia","de":"Situation 1, Wünsche äußern. Was könntest du sagen?","ar":"الموقف رقم 1. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":399.06,"end":403.332},{"speaker":"Karim","de":"Eine passende Formulierung ist: Ich hätte gern mehr Zeit mit meinen Freunden.","ar":"تعبير مناسب هو: يا ريت كان عندي وقت أكتر مع أصحابي.","pauseAfter":0.7,"kind":"phrase","start":405.532,"end":409.732},{"speaker":"Julia","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Ich hätte gern mehr Zeit mit meinen Freunden.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":410.432,"end":416.504},{"speaker":"Karim","de":"Situation 2, Wünsche äußern. Was könntest du sagen?","ar":"الموقف رقم 2. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":418.704,"end":422.784},{"speaker":"Julia","de":"Eine passende Formulierung ist: Wir hätten gern einen Hund.","ar":"تعبير مناسب هو: نفسنا في كلب.","pauseAfter":0.7,"kind":"phrase","start":424.984,"end":428.968},{"speaker":"Karim","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Wir hätten gern einen Hund.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":429.668,"end":434.492},{"speaker":"Julia","de":"Situation 3, Wünsche äußern. Was könntest du sagen?","ar":"الموقف رقم 3. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":436.692,"end":441.084},{"speaker":"Karim","de":"Eine passende Formulierung ist: Er würde gern mehr lesen.","ar":"تعبير مناسب هو: هو نفسه يقرأ أكتر.","pauseAfter":0.7,"kind":"phrase","start":443.284,"end":446.884},{"speaker":"Julia","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Er würde gern mehr lesen.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":447.584,"end":452.744},{"speaker":"Karim","de":"Situation 4, Wünsche äußern. Was könntest du sagen?","ar":"الموقف رقم 4. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":454.944,"end":459.072},{"speaker":"Julia","de":"Eine passende Formulierung ist: Ich wäre gern öfter zu Hause.","ar":"تعبير مناسب هو: يا ريتني أكون في البيت أكتر.","pauseAfter":0.7,"kind":"phrase","start":461.272,"end":465.424},{"speaker":"Karim","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Ich wäre gern öfter zu Hause.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":466.124,"end":471.02},{"speaker":"Julia","de":"Situation 5, Ratschläge geben. Was könntest du sagen?","ar":"الموقف رقم 5. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":473.22,"end":477.804},{"speaker":"Karim","de":"Eine passende Formulierung ist: Ich würde mit dem Chef sprechen.","ar":"تعبير مناسب هو: أنا مكانك كنت هكلم المدير.","pauseAfter":0.7,"kind":"phrase","start":480.004,"end":483.7},{"speaker":"Julia","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Ich würde mit dem Chef sprechen.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":484.4,"end":489.608},{"speaker":"Karim","de":"Situation 6, Ratschläge geben. Was könntest du sagen?","ar":"الموقف رقم 6. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":491.808,"end":496.104},{"speaker":"Julia","de":"Eine passende Formulierung ist: Du könntest deinen Kollegen sagen, dass sie leise reden sollen.","ar":"تعبير مناسب هو: ممكن تقول لزمايلك يوطّوا صوتهم.","pauseAfter":0.7,"kind":"phrase","start":498.304,"end":503.848},{"speaker":"Karim","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Du könntest deinen Kollegen sagen, dass sie leise reden sollen.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":504.548,"end":510.74},{"speaker":"Julia","de":"Jetzt kommt ein kurzer Hör- und Grammatikcheck. Antworte zuerst selbst. Danach hörst du die Lösung.","ar":"والآن اختبار قصير في الاستماع والقواعد. أجب أولًا بنفسك ثم استمع إلى الحل.","pauseAfter":0.8,"kind":"section","start":512.94,"end":520.164},{"speaker":"Julia","de":"Frage 1: Ich ___ gern mehr Zeit für meine Familie.","ar":"السؤال رقم 1. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":520.964,"end":526.532},{"speaker":"Julia","de":"Die Möglichkeiten sind: A, hätte. B, wäre. C, würde.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":527.032,"end":532.576},{"speaker":"Karim","de":"Die richtige Antwort ist A: hätte. Wunsch mit haben → hätte gern.","ar":"الإجابة الصحيحة: التمني بحاجة تمتلكها → hätte gern.","pauseAfter":1,"kind":"answer","start":535.776,"end":540.096},{"speaker":"Karim","de":"Frage 2: An deiner Stelle ___ ich mit dem Chef sprechen.","ar":"السؤال رقم 2. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":541.096,"end":545.992},{"speaker":"Karim","de":"Die Möglichkeiten sind: A, würde. B, hätte. C, wäre.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":546.492,"end":551.748},{"speaker":"Julia","de":"Die richtige Antwort ist A: würde. Ratschlag: An deiner Stelle würde ich + Infinitiv.","ar":"الإجابة الصحيحة: النصيحة: لو كنت مكانك + würde.","pauseAfter":1,"kind":"answer","start":554.948,"end":561.764},{"speaker":"Julia","de":"Frage 3: Wir freuen uns ___ das Wochenende. (Es kommt noch!)","ar":"السؤال رقم 3. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":562.764,"end":569.532},{"speaker":"Julia","de":"Die Möglichkeiten sind: A, über. B, auf. C, mit.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":570.032,"end":575.504},{"speaker":"Karim","de":"Die richtige Antwort ist B: auf. Zukunft → sich freuen auf.","ar":"الإجابة الصحيحة: حاجة جاية في المستقبل → auf.","pauseAfter":1,"kind":"answer","start":578.704,"end":582.88},{"speaker":"Karim","de":"Frage 4: ___ wartest du? – Auf den Bus.","ar":"السؤال رقم 4. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":583.88,"end":589.04},{"speaker":"Karim","de":"Die Möglichkeiten sind: A, Auf wen. B, Worauf. C, Wofür.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":589.54,"end":594.964},{"speaker":"Julia","de":"Die richtige Antwort ist B: Worauf. Sache/Ding → wo(r) + Präposition: Worauf.","ar":"الإجابة الصحيحة: سؤال عن شيء → worauf.","pauseAfter":1,"kind":"answer","start":598.164,"end":605.772},{"speaker":"Karim","de":"Zum Abschluss: Nenne drei neue Wörter aus Kapitel 11 und bilde mit jedem Wort einen Satz.","ar":"في الختام: اذكر ثلاث كلمات جديدة من الدرس 11 وكوّن جملة بكل كلمة.","pauseAfter":4,"kind":"interactive","start":606.772,"end":611.98},{"speaker":"Julia","de":"Wenn das noch schwer ist, höre die Folge morgen noch einmal. Beim zweiten Hören wirst du deutlich mehr verstehen.","ar":"إذا كان الأمر ما زال صعبًا، فاستمع إلى الحلقة غدًا مرة أخرى. في المرة الثانية ستفهم أكثر بوضوح.","pauseAfter":0.7,"kind":"outro","start":615.98,"end":622.988},{"speaker":"Karim","de":"Danke fürs Zuhören. Das war Mehr Zeit für mich. Bis zur nächsten Folge!","ar":"شكرًا على الاستماع. كانت هذه حلقة Mehr Zeit für mich. إلى الحلقة القادمة!","pauseAfter":1,"kind":"outro","start":623.688,"end":628.776}],"people":[{"name":"Julia","gender":"female","age":44,"voice":"de-DE-SeraphinaMultilingualNeural"},{"name":"Karim","gender":"male","age":46,"voice":"de-DE-FlorianMultilingualNeural"}],"audio":"assets/podcasts/chapter-11.mp3?v=natural-dialogue-2","durationSeconds":629.83},{"chapter":12,"title":"Musik verbindet","duration":"12 Min.","speakers":["Nina","Adel"],"intro":"Musik, Konzerte, Bands und Bilder beschreiben.","keywords":["Konzert","Band","Bühne","Melodie","begeistert"],"lines":[{"speaker":"Nina","de":"Willkommen zu Folge 12: Musik verbindet. Ich bin Nina, 22 Jahre alt.","ar":"مرحبًا بكم في الحلقة 12: Musik verbindet. أنا Nina وعمري 22 عامًا.","pauseAfter":0.5,"kind":"intro","start":0.0,"end":6.432},{"speaker":"Adel","de":"Und ich bin Adel, 27 Jahre alt. Heute sprechen wir über Musik, Bands, Bilder beschreiben.","ar":"وأنا Adel وعمري 27 عامًا. سنتحدث اليوم عن موضوعات الدرس.","pauseAfter":0.6,"kind":"intro","start":6.932,"end":14.156},{"speaker":"Nina","de":"Hör zuerst entspannt zu. Danach wiederholen wir wichtige Wörter und Redemittel, und am Ende gibt es Fragen für dich.","ar":"استمع أولًا بهدوء. بعد ذلك سنراجع كلمات وتعبيرات مهمة، وفي النهاية توجد أسئلة لك.","pauseAfter":0.7,"kind":"intro","start":14.756,"end":22.388},{"speaker":"Adel","de":"Du kannst jederzeit pausieren, laut antworten und anschließend mit unserer Lösung vergleichen. Los geht es!","ar":"يمكنك إيقاف الحلقة والإجابة بصوت عالٍ ثم مقارنة إجابتك بحلنا. لنبدأ!","pauseAfter":1,"kind":"intro","start":23.088,"end":30.432},{"speaker":"Nina","de":"Adel, warst du gestern bei dem Konzert im Stadtpark?","ar":"عادل، هل كنت أمس في الحفل الموسيقي بحديقة المدينة؟","pauseAfter":0.55,"kind":"scene","start":31.432,"end":35.032},{"speaker":"Adel","de":"Ja, und ich war begeistert. Drei verschiedene Bands sind aufgetreten.","ar":"نعم، وقد كنت منبهرًا. قدمت ثلاث فرق موسيقية مختلفة عروضًا.","pauseAfter":0.55,"kind":"scene","start":35.582,"end":40.934},{"speaker":"Nina","de":"Welche Musik hat dir am besten gefallen?","ar":"أي موسيقى أعجبتك أكثر؟","pauseAfter":0.55,"kind":"scene","start":41.484,"end":44.1},{"speaker":"Adel","de":"Die letzte Band war großartig. Ihre Melodien waren ruhig, aber der Rhythmus war sehr modern.","ar":"كانت الفرقة الأخيرة رائعة. ألحانهم كانت هادئة لكن الإيقاع كان حديثًا جدًا.","pauseAfter":0.55,"kind":"scene","start":44.65,"end":51.154},{"speaker":"Nina","de":"Ich habe online ein Foto gesehen. Auf der Bühne standen sechs Musiker, oder?","ar":"رأيت صورة عبر الإنترنت. كان هناك ستة موسيقيين على المسرح، أليس كذلك؟","pauseAfter":0.55,"kind":"scene","start":51.704,"end":57.2},{"speaker":"Adel","de":"Genau. Im Vordergrund spielte eine Frau Gitarre, und hinter ihr standen der Sänger und der Schlagzeuger.","ar":"بالضبط. في المقدمة كانت امرأة تعزف الجيتار، وخلفها وقف المغني وعازف الطبول.","pauseAfter":0.55,"kind":"scene","start":57.75,"end":64.926},{"speaker":"Nina","de":"Schade, dass ich keine Karte mehr bekommen habe.","ar":"من المؤسف أنني لم أستطع الحصول على تذكرة.","pauseAfter":0.55,"kind":"scene","start":65.476,"end":68.62},{"speaker":"Adel","de":"Die Band kommt im Herbst wieder. Dann kaufen wir die Karten früh und gehen zusammen hin.","ar":"ستعود الفرقة في الخريف. عندها سنشتري التذاكر مبكرًا ونذهب معًا.","pauseAfter":0.55,"kind":"scene","start":69.17,"end":74.882},{"speaker":"Nina","de":"Nach dem Konzert hören Nina und Adel im Zug noch einmal einige Lieder der Band.","ar":"بعد الحفل تستمع نينا وعادل في القطار إلى بعض أغاني الفرقة مجددًا.","pauseAfter":0.28,"kind":"scene","start":75.432,"end":80.16},{"speaker":"Adel","de":"Dieses Lied klingt live ganz anders als auf der Aufnahme.","ar":"تبدو هذه الأغنية في الحفل مختلفة تمامًا عن التسجيل.","pauseAfter":0.28,"kind":"scene","start":80.44,"end":84.328},{"speaker":"Nina","de":"Der Rhythmus war auf der Bühne viel stärker, und das Publikum hat mitgesungen.","ar":"كان الإيقاع على المسرح أقوى كثيرًا وغنى الجمهور معه.","pauseAfter":0.28,"kind":"scene","start":84.608,"end":89.264},{"speaker":"Adel","de":"Mir gefällt besonders die Melodie am Anfang. Sie ist ruhig und klar.","ar":"تعجبني خصوصًا النغمة في البداية، فهي هادئة وواضحة.","pauseAfter":0.28,"kind":"scene","start":89.544,"end":94.992},{"speaker":"Nina","de":"Hast du den Text verstanden? In dem Lied geht es um eine lange Reise.","ar":"هل فهمت الكلمات؟ تتحدث الأغنية عن رحلة طويلة.","pauseAfter":0.28,"kind":"scene","start":95.272,"end":100.048},{"speaker":"Adel","de":"Nicht jedes Wort. Aber der Sänger hat sehr deutlich gesprochen.","ar":"ليس كل كلمة، لكن المغني نطق بوضوح شديد.","pauseAfter":0.28,"kind":"scene","start":100.328,"end":105.08},{"speaker":"Nina","de":"Auf meinem Foto sieht man die ganze Band auf der Bühne.","ar":"في صورتي تظهر الفرقة كلها على المسرح.","pauseAfter":0.28,"kind":"scene","start":105.36,"end":108.648},{"speaker":"Adel","de":"Im Vordergrund steht die Gitarristin, und im Hintergrund sieht man das Schlagzeug.","ar":"في المقدمة تقف عازفة الجيتار وفي الخلف تظهر الطبول.","pauseAfter":0.28,"kind":"scene","start":108.928,"end":113.896},{"speaker":"Nina","de":"Das Licht war blau und violett. Dadurch wirkt das Bild fast wie ein Gemälde.","ar":"كانت الإضاءة زرقاء وبنفسجية، لذلك تبدو الصورة كلوحة تقريبًا.","pauseAfter":0.28,"kind":"scene","start":114.176,"end":119.384},{"speaker":"Adel","de":"Schick mir das Foto bitte. Ich möchte es meiner Schwester zeigen.","ar":"أرسل لي الصورة من فضلك. أريد عرضها على أختي.","pauseAfter":0.28,"kind":"scene","start":119.664,"end":124.512},{"speaker":"Nina","de":"Sie spielt selbst ein Instrument, oder?","ar":"هي تعزف آلة موسيقية أيضًا، أليس كذلك؟","pauseAfter":0.28,"kind":"scene","start":124.792,"end":127.6},{"speaker":"Adel","de":"Ja, sie spielt Klavier und tritt manchmal mit einer kleinen Gruppe auf.","ar":"نعم، تعزف البيانو وتقدم عروضًا أحيانًا مع مجموعة صغيرة.","pauseAfter":0.28,"kind":"scene","start":127.88,"end":132.44},{"speaker":"Nina","de":"Vielleicht kann ihre Gruppe beim nächsten Stadtfest spielen.","ar":"ربما يمكن لمجموعتها العزف في مهرجان المدينة القادم.","pauseAfter":0.28,"kind":"scene","start":132.72,"end":136.2},{"speaker":"Adel","de":"Dafür brauchen sie noch einen guten Namen und ein bekanntes Lied.","ar":"يحتاجون لذلك إلى اسم جيد وأغنية معروفة.","pauseAfter":0.28,"kind":"scene","start":136.48,"end":140.536},{"speaker":"Nina","de":"Wir können sie am Wochenende besuchen und beim Üben zuhören.","ar":"يمكننا زيارتها في عطلة نهاية الأسبوع والاستماع إلى تدريبهم.","pauseAfter":0.28,"kind":"scene","start":140.816,"end":144.656},{"speaker":"Adel","de":"Gern. Nach diesem Konzert habe ich noch mehr Lust auf Live-Musik.","ar":"بكل سرور. بعد هذا الحفل أصبحت أرغب أكثر في الموسيقى الحية.","pauseAfter":0.28,"kind":"scene","start":144.936,"end":149.664},{"speaker":"Nina","de":"Das war unsere erste Alltagsszene. Welche Wörter und Sätze hast du sofort verstanden?","ar":"كان هذا مشهدنا اليومي الأول. ما الكلمات والجمل التي فهمتها فورًا؟","pauseAfter":3.2,"kind":"interactive","start":149.944,"end":155.944},{"speaker":"Adel","de":"Denk kurz nach. Du musst nicht jedes Wort verstehen. Wichtig ist zuerst die Situation.","ar":"فكّر قليلًا. ليس ضروريًا أن تفهم كل كلمة؛ المهم أولًا هو فهم الموقف.","pauseAfter":2.4,"kind":"interactive","start":159.144,"end":166.056},{"speaker":"Nina","de":"Die Situation passt zu Kapitel 12. Jetzt sehen wir uns den Wortschatz genauer an.","ar":"الموقف مرتبط بالدرس 12. والآن سنراجع المفردات بدقة أكبر.","pauseAfter":0.8,"kind":"section","start":168.456,"end":174.24},{"speaker":"Nina","de":"Wort Nummer 1: die Unterhaltung. Hör genau zu: die Unterhaltung.","ar":"الكلمة رقم 1: الترفيه / التسلية. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":175.04,"end":180.368},{"speaker":"Adel","de":"die Unterhaltung bedeutet: Alles, was Spaß macht: Musik, Filme, Spiele … Ein Beispiel: Gute Unterhaltung beim Konzert!","ar":"معنى die Unterhaltung: الترفيه / التسلية.","pauseAfter":0.6,"kind":"vocab","start":180.818,"end":189.746},{"speaker":"Nina","de":"Jetzt bist du dran. Sprich laut nach: die Unterhaltung.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Unterhaltung.","pauseAfter":1.8,"kind":"interactive","start":190.346,"end":194.666},{"speaker":"Adel","de":"Wort Nummer 2: die Musik. Hör genau zu: die Musik.","ar":"الكلمة رقم 2: الموسيقى. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":196.466,"end":201.41},{"speaker":"Nina","de":"die Musik bedeutet: Töne und Melodien; man hört sie oder macht sie selbst. Ein Beispiel: Ohne Musik kann ich nicht leben!","ar":"معنى die Musik: الموسيقى.","pauseAfter":0.6,"kind":"vocab","start":201.86,"end":210.068},{"speaker":"Adel","de":"Jetzt bist du dran. Sprich laut nach: die Musik.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Musik.","pauseAfter":1.8,"kind":"interactive","start":210.668,"end":215.132},{"speaker":"Nina","de":"Wort Nummer 3: der Musiker, - / die Musikerin, -nen. Hör genau zu: der Musiker, - / die Musikerin, -nen.","ar":"الكلمة رقم 3: الموسيقي / الموسيقية. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":216.932,"end":225.404},{"speaker":"Adel","de":"der Musiker, - / die Musikerin, -nen bedeutet: Eine Person, die Musik macht. Ein Beispiel: Die Musikerin spielt drei Instrumente.","ar":"معنى der Musiker, - / die Musikerin, -nen: الموسيقي / الموسيقية.","pauseAfter":0.6,"kind":"vocab","start":225.854,"end":235.046},{"speaker":"Nina","de":"Jetzt bist du dran. Sprich laut nach: der Musiker, - / die Musikerin, -nen.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Musiker, - / die Musikerin, -nen.","pauseAfter":1.8,"kind":"interactive","start":235.646,"end":241.382},{"speaker":"Adel","de":"Wort Nummer 4: die Band, -s. Hör genau zu: die Band, -s.","ar":"الكلمة رقم 4: الفرقة الموسيقية / الباند. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":243.182,"end":247.982},{"speaker":"Nina","de":"die Band, -s bedeutet: Eine Gruppe von Musikern. Ein Beispiel: Die Band gibt es seit zehn Jahren.","ar":"معنى die Band, -s: الفرقة الموسيقية / الباند.","pauseAfter":0.6,"kind":"vocab","start":248.432,"end":255.776},{"speaker":"Adel","de":"Jetzt bist du dran. Sprich laut nach: die Band, -s.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Band, -s.","pauseAfter":1.8,"kind":"interactive","start":256.376,"end":261.2},{"speaker":"Nina","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":263.0,"end":269.528},{"speaker":"Adel","de":"Die Wörter waren: die Unterhaltung, die Musik, der Musiker, - / die Musikerin, -nen, die Band, -s.","ar":"الكلمات كانت: الترفيه / التسلية، الموسيقى، الموسيقي / الموسيقية، الفرقة الموسيقية / الباند.","pauseAfter":1,"kind":"answer","start":272.528,"end":279.368},{"speaker":"Nina","de":"Wort Nummer 5: das Mitglied, -er. Hör genau zu: das Mitglied, -er.","ar":"الكلمة رقم 5: عضو. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":280.368,"end":286.32},{"speaker":"Adel","de":"das Mitglied, -er bedeutet: Eine Person in einer Gruppe oder Band. Ein Beispiel: Die Band hat vier Mitglieder.","ar":"معنى das Mitglied, -er: عضو.","pauseAfter":0.6,"kind":"vocab","start":286.77,"end":294.426},{"speaker":"Nina","de":"Jetzt bist du dran. Sprich laut nach: das Mitglied, -er.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: das Mitglied, -er.","pauseAfter":1.8,"kind":"interactive","start":295.026,"end":299.634},{"speaker":"Adel","de":"Wort Nummer 6: das Lied, -er. Hör genau zu: das Lied, -er.","ar":"الكلمة رقم 6: أغنية. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":301.434,"end":307.266},{"speaker":"Nina","de":"das Lied, -er bedeutet: Musik mit Text zum Singen; der Song. Ein Beispiel: Ein bekanntes Lied von ihnen heißt „Sommer“.","ar":"معنى das Lied, -er: أغنية.","pauseAfter":0.6,"kind":"vocab","start":307.716,"end":317.076},{"speaker":"Adel","de":"Jetzt bist du dran. Sprich laut nach: das Lied, -er.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: das Lied, -er.","pauseAfter":1.8,"kind":"interactive","start":317.676,"end":322.572},{"speaker":"Nina","de":"Wort Nummer 7: der Text, -e. Hör genau zu: der Text, -e.","ar":"الكلمة رقم 7: كلمات الأغنية / النص. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":324.372,"end":329.412},{"speaker":"Adel","de":"der Text, -e bedeutet: Die Wörter von einem Lied. Ein Beispiel: In den Texten geht es oft um Liebe.","ar":"معنى der Text, -e: كلمات الأغنية / النص.","pauseAfter":0.6,"kind":"vocab","start":329.862,"end":336.99},{"speaker":"Nina","de":"Jetzt bist du dran. Sprich laut nach: der Text, -e.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Text, -e.","pauseAfter":1.8,"kind":"interactive","start":337.59,"end":342.006},{"speaker":"Adel","de":"Wort Nummer 8: die Melodie, -n. Hör genau zu: die Melodie, -n.","ar":"الكلمة رقم 8: اللحن. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":343.806,"end":348.894},{"speaker":"Nina","de":"die Melodie, -n bedeutet: Die Töne von einem Lied, die man mitsingen kann. Ein Beispiel: Die Melodie geht mir nicht aus dem Kopf!","ar":"معنى die Melodie, -n: اللحن.","pauseAfter":0.6,"kind":"vocab","start":349.344,"end":358.056},{"speaker":"Adel","de":"Jetzt bist du dran. Sprich laut nach: die Melodie, -n.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: die Melodie, -n.","pauseAfter":1.8,"kind":"interactive","start":358.656,"end":363.672},{"speaker":"Nina","de":"Mini-Wiederholung: Welche vier Wörter hast du gerade gehört? Nenne sie ohne auf den Text zu schauen.","ar":"مراجعة صغيرة: ما الكلمات الأربع التي سمعتها؟ قلها من دون النظر إلى النص.","pauseAfter":3,"kind":"interactive","start":365.472,"end":372.0},{"speaker":"Adel","de":"Die Wörter waren: das Mitglied, -er, das Lied, -er, der Text, -e, die Melodie, -n.","ar":"الكلمات كانت: عضو، أغنية، كلمات الأغنية / النص، اللحن.","pauseAfter":1,"kind":"answer","start":375.0,"end":381.6},{"speaker":"Nina","de":"Wort Nummer 9: der Rhythmus. Hör genau zu: der Rhythmus.","ar":"الكلمة رقم 9: الإيقاع. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":382.6,"end":387.544},{"speaker":"Adel","de":"der Rhythmus bedeutet: Der „Beat“ der Musik; das Tempo. Ein Beispiel: Der Rhythmus macht sofort gute Laune.","ar":"معنى der Rhythmus: الإيقاع.","pauseAfter":0.6,"kind":"vocab","start":387.994,"end":395.794},{"speaker":"Nina","de":"Jetzt bist du dran. Sprich laut nach: der Rhythmus.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: der Rhythmus.","pauseAfter":1.8,"kind":"interactive","start":396.394,"end":400.546},{"speaker":"Adel","de":"Wort Nummer 10: das Konzert, -e. Hör genau zu: das Konzert, -e.","ar":"الكلمة رقم 10: حفلة موسيقية. استمع جيدًا إلى نطقها.","pauseAfter":0.45,"kind":"vocab","start":402.346,"end":407.482},{"speaker":"Nina","de":"das Konzert, -e bedeutet: Musiker spielen live vor Publikum. Ein Beispiel: Wir gehen am Freitag auf ein Konzert.","ar":"معنى das Konzert, -e: حفلة موسيقية.","pauseAfter":0.6,"kind":"vocab","start":407.932,"end":416.908},{"speaker":"Adel","de":"Jetzt bist du dran. Sprich laut nach: das Konzert, -e.","ar":"دورك الآن. كرر الكلمة بصوت عالٍ: das Konzert, -e.","pauseAfter":1.8,"kind":"interactive","start":417.508,"end":422.524},{"speaker":"Adel","de":"Sehr gut. Wörter allein reichen aber nicht. Im Gespräch brauchen wir fertige Sätze und passende Reaktionen.","ar":"جيد جدًا. الكلمات وحدها لا تكفي؛ في الحوار نحتاج إلى جمل جاهزة وردود مناسبة.","pauseAfter":0.8,"kind":"section","start":424.324,"end":432.412},{"speaker":"Nina","de":"Situation 1, Eine Band / einen Musiker vorstellen. Was könntest du sagen?","ar":"الموقف رقم 1. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":433.212,"end":438.876},{"speaker":"Adel","de":"Eine passende Formulierung ist: Die Band heißt … / Er/Sie heißt …","ar":"تعبير مناسب هو: الفرقة اسمها ... / هو/هي اسمه ...","pauseAfter":0.7,"kind":"phrase","start":441.076,"end":445.396},{"speaker":"Nina","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Die Band heißt … / Er/Sie heißt …","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":446.096,"end":452.192},{"speaker":"Adel","de":"Situation 2, Eine Band / einen Musiker vorstellen. Was könntest du sagen?","ar":"الموقف رقم 2. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":454.392,"end":460.512},{"speaker":"Nina","de":"Eine passende Formulierung ist: Die Band gibt es seit … / Er macht seit … Musik.","ar":"تعبير مناسب هو: الفرقة موجودة من سنة ... / بيعمل موسيقى من ...","pauseAfter":0.7,"kind":"phrase","start":462.712,"end":468.568},{"speaker":"Adel","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Die Band gibt es seit … / Er macht seit … Musik.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":469.268,"end":476.228},{"speaker":"Nina","de":"Situation 3, Eine Band / einen Musiker vorstellen. Was könntest du sagen?","ar":"الموقف رقم 3. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":478.428,"end":484.044},{"speaker":"Adel","de":"Eine passende Formulierung ist: Die Band hat … Mitglieder. Sie kommen aus …","ar":"تعبير مناسب هو: الفرقة فيها ... أعضاء. وهم من ...","pauseAfter":0.7,"kind":"phrase","start":486.244,"end":492.748},{"speaker":"Nina","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Die Band hat … Mitglieder. Sie kommen aus …","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":493.448,"end":500.552},{"speaker":"Adel","de":"Situation 4, Eine Band / einen Musiker vorstellen. Was könntest du sagen?","ar":"الموقف رقم 4. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":502.752,"end":508.872},{"speaker":"Nina","de":"Eine passende Formulierung ist: Die Musik ist rockig / schnell / langsam / melodisch.","ar":"تعبير مناسب هو: الموسيقى روك / سريعة / هادية / لحنية.","pauseAfter":0.7,"kind":"phrase","start":511.072,"end":516.736},{"speaker":"Adel","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Die Musik ist rockig / schnell / langsam / melodisch.","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":517.436,"end":523.844},{"speaker":"Nina","de":"Situation 5, Eine Band / einen Musiker vorstellen. Was könntest du sagen?","ar":"الموقف رقم 5. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":526.044,"end":531.708},{"speaker":"Adel","de":"Eine passende Formulierung ist: Ein bekanntes Lied heißt … In den Liedern geht es oft um …","ar":"تعبير مناسب هو: في أغنية مشهورة اسمها ... وأغانيهم غالبًا بتتكلم عن ...","pauseAfter":0.7,"kind":"phrase","start":533.908,"end":540.148},{"speaker":"Nina","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Ein bekanntes Lied heißt … In den Liedern geht es oft um …","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":540.848,"end":548.072},{"speaker":"Adel","de":"Situation 6, Eine Band / einen Musiker vorstellen. Was könntest du sagen?","ar":"الموقف رقم 6. ماذا يمكنك أن تقول؟","pauseAfter":2.2,"kind":"interactive","start":550.272,"end":556.344},{"speaker":"Nina","de":"Eine passende Formulierung ist: Am besten gefällt mir das Lied …, weil …","ar":"تعبير مناسب هو: أكتر أغنية بحبها هي ... لأن ...","pauseAfter":0.7,"kind":"phrase","start":558.544,"end":563.176},{"speaker":"Adel","de":"Wiederhole den ganzen Satz mit der gleichen Satzmelodie: Am besten gefällt mir das Lied …, weil …","ar":"كرر الجملة كاملة بنفس نغمة الكلام.","pauseAfter":2.2,"kind":"interactive","start":563.876,"end":569.78},{"speaker":"Nina","de":"Jetzt kommt ein kurzer Hör- und Grammatikcheck. Antworte zuerst selbst. Danach hörst du die Lösung.","ar":"والآن اختبار قصير في الاستماع والقواعد. أجب أولًا بنفسك ثم استمع إلى الحل.","pauseAfter":0.8,"kind":"section","start":571.98,"end":579.204},{"speaker":"Nina","de":"Frage 1: Das ist der Sänger, ___ eine tolle Stimme hat.","ar":"السؤال رقم 1. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":580.004,"end":585.596},{"speaker":"Nina","de":"Die Möglichkeiten sind: A, den. B, der. C, das.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":586.096,"end":591.376},{"speaker":"Adel","de":"Die richtige Antwort ist B: der. Das Pronomen ist Subjekt (er hat) → Nominativ maskulin: der.","ar":"الإجابة الصحيحة: الضمير فاعل في جملة الوصل → der.","pauseAfter":1,"kind":"answer","start":594.576,"end":601.92},{"speaker":"Adel","de":"Frage 2: Das ist das Lied, ___ ich am liebsten höre.","ar":"السؤال رقم 2. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":602.92,"end":608.464},{"speaker":"Adel","de":"Die Möglichkeiten sind: A, das. B, den. C, die.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":608.964,"end":614.148},{"speaker":"Nina","de":"Die richtige Antwort ist A: das. das Lied (neutral) + Akkusativ → das.","ar":"الإجابة الصحيحة: الأغنية محايدة وفي النصب → das.","pauseAfter":1,"kind":"answer","start":617.348,"end":622.988},{"speaker":"Nina","de":"Frage 3: Die Band, ___ viele Menschen kennen, kommt aus Wien.","ar":"السؤال رقم 3. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":623.988,"end":629.988},{"speaker":"Nina","de":"Die Möglichkeiten sind: A, der. B, die. C, den.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":630.488,"end":635.744},{"speaker":"Adel","de":"Die richtige Antwort ist B: die. die Band (feminin), Akkusativ-Objekt → die.","ar":"الإجابة الصحيحة: الفرقة مؤنثة وفي النصب → die.","pauseAfter":1,"kind":"answer","start":638.944,"end":645.208},{"speaker":"Adel","de":"Frage 4: Hast du ___ gesehen? – Nein, niemanden.","ar":"السؤال رقم 4. اختر الإجابة الصحيحة من النص الألماني.","pauseAfter":0.5,"kind":"quiz","start":646.208,"end":652.64},{"speaker":"Adel","de":"Die Möglichkeiten sind: A, jemanden. B, etwas. C, nichts.","ar":"استمع إلى الاختيارات ثم أوقف الصوت وأجب.","pauseAfter":3.2,"kind":"interactive","start":653.14,"end":659.86},{"speaker":"Nina","de":"Die richtige Antwort ist A: jemanden. Person → jemand(en); die Negation ist niemand(en).","ar":"الإجابة الصحيحة: سؤال عن شخص → jemanden.","pauseAfter":1,"kind":"answer","start":663.06,"end":670.548},{"speaker":"Adel","de":"Zum Abschluss: Nenne drei neue Wörter aus Kapitel 12 und bilde mit jedem Wort einen Satz.","ar":"في الختام: اذكر ثلاث كلمات جديدة من الدرس 12 وكوّن جملة بكل كلمة.","pauseAfter":4,"kind":"interactive","start":671.548,"end":677.5},{"speaker":"Nina","de":"Wenn das noch schwer ist, höre die Folge morgen noch einmal. Beim zweiten Hören wirst du deutlich mehr verstehen.","ar":"إذا كان الأمر ما زال صعبًا، فاستمع إلى الحلقة غدًا مرة أخرى. في المرة الثانية ستفهم أكثر بوضوح.","pauseAfter":0.7,"kind":"outro","start":681.5,"end":688.508},{"speaker":"Adel","de":"Danke fürs Zuhören. Das war Musik verbindet. Bis zur nächsten Folge!","ar":"شكرًا على الاستماع. كانت هذه حلقة Musik verbindet. إلى الحلقة القادمة!","pauseAfter":1,"kind":"outro","start":689.208,"end":695.496}],"people":[{"name":"Nina","gender":"female","age":22,"voice":"de-DE-SeraphinaMultilingualNeural"},{"name":"Adel","gender":"male","age":27,"voice":"de-DE-KillianNeural"}],"audio":"assets/podcasts/chapter-12.mp3?v=natural-dialogue-2","durationSeconds":696.55}];
